class HomePage extends StatefulWidget {
  final String userName;

  const HomePage({
    super.key,
    required this.userName,
  });

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  // ============================================================
  // GOOGLE API KEY
  // ============================================================

  static const String _googlePlacesApiKey =
      "AIzaSyAxmD8Gvtn1KGomBFy3pWXRFgvw0c4a-48";

  // ============================================================
  // DEFAULT LOCATIONS
  // ============================================================

  // ============================================================
  // STATE
  // ============================================================

  LatLng? userLocation;

  // NEW:
  // Exact coordinates for the selected pickup and destination.
  LatLng? pickupLocation;
  LatLng? destinationLocation;

  GoogleMapController? _mapController;

  Set<Marker> _markers = {};

  // ============================================================
  // ROUTE STATE
  // ============================================================

  Set<Polyline> _polylines = {};

  List<LatLng> _routePoints = [];

  bool _isLoadingRoute = false;

  Timer? _routeAnimationTimer;

  String pickupAddress = '';

  bool _mapReady = false;
  bool _locationLoaded = false;

  final TextEditingController _pickupController = TextEditingController();

  final FocusNode _pickupFocusNode = FocusNode();

  final TextEditingController _destinationController = TextEditingController();

  final FocusNode _destinationFocusNode = FocusNode();

  // ============================================================
  // AUTOCOMPLETE STATE
  // ============================================================

  List<Map<String, dynamic>> _pickupSuggestions = [];
  List<Map<String, dynamic>> _destinationSuggestions = [];

  bool _loadingPickupSuggestions = false;
  bool _loadingDestinationSuggestions = false;

  Timer? _pickupDebounce;
  Timer? _destinationDebounce;

  String? _activeAutocompleteField;

  // ============================================================
  // INIT
  // ============================================================

  @override
  void initState() {
    super.initState();

    // Start GPS immediately.
    //
    // IMPORTANT:
    // The map itself does NOT wait for this.
    _loadCurrentAddress();

    // Listen for autocomplete text changes.
    _pickupController.addListener(_onPickupChanged);
    _destinationController.addListener(_onDestinationChanged);
  }

  // ============================================================
  // DISPOSE
  // ============================================================

  @override
  void dispose() {
    _pickupDebounce?.cancel();
    _destinationDebounce?.cancel();

    _routeAnimationTimer?.cancel();

    _pickupController.removeListener(_onPickupChanged);
    _destinationController.removeListener(_onDestinationChanged);

    _pickupController.dispose();
    _pickupFocusNode.dispose();

    _destinationController.dispose();
    _destinationFocusNode.dispose();

    _mapController?.dispose();

    super.dispose();
  }

  // ============================================================
  // MAP CREATED
  // ============================================================

  void _onMapCreated(GoogleMapController controller) {
    _mapController = controller;
    _mapReady = true;

    // If Firebase currentAddress has already been loaded,
    // immediately center the map on it.
    if (userLocation != null) {
      _moveMapToCurrentLocation();
    }
  }

  Future<void> _moveMapToCurrentLocation() async {
    if (_mapController == null || userLocation == null) return;

    try {
      await _mapController!.animateCamera(
        CameraUpdate.newCameraPosition(
          CameraPosition(
            target: userLocation!,
            zoom: 16,
          ),
        ),
      );
    } catch (e) {
      debugPrint(
        "Error moving map to Firebase current location: $e",
      );
    }
  }

  Future<void> _loadCurrentAddress() async {
    final uid = FirebaseAuth.instance.currentUser?.uid;

    if (uid == null) return;

    try {
      final doc =
          await FirebaseFirestore.instance.collection("users").doc(uid).get();

      final data = doc.data();

      if (data == null) return;

      final currentAddress = data["currentAddress"];

      if (currentAddress == null) {
        return;
      }

      final Map<String, dynamic> location =
          Map<String, dynamic>.from(currentAddress);

      final String fullAddress =
          location["fullAddress"]?.toString().trim() ?? "";

      final double? latitude = (location["latitude"] as num?)?.toDouble();

      final double? longitude = (location["longitude"] as num?)?.toDouble();

      // We need both address and valid coordinates.
      if (fullAddress.isEmpty || latitude == null || longitude == null) {
        return;
      }

      final LatLng firebaseLocation = LatLng(
        latitude,
        longitude,
      );

      if (!mounted) return;

      setState(() {
        userLocation = firebaseLocation;
        pickupLocation = firebaseLocation;
        pickupAddress = fullAddress;

        _pickupController.text = fullAddress;

        _locationLoaded = true;

        _markers = {
          Marker(
            markerId: const MarkerId("user"),
            position: firebaseLocation,
            infoWindow: const InfoWindow(
              title: "Your current location",
            ),
            icon: BitmapDescriptor.defaultMarkerWithHue(
              BitmapDescriptor.hueBlue,
            ),
          ),
        };
      });

      // If the map has already been created,
      // move it to the Firebase location.
      if (_mapReady && _mapController != null) {
        await _moveMapToCurrentLocation();
      }
    } catch (e) {
      debugPrint(
        "Error loading current address from Firebase: $e",
      );
    }
  }

  // ============================================================
  // INITIAL MAP LOCATION
  // ============================================================

  // ============================================================
  // GET USER LOCATION
  // ============================================================

  Future<void> _fetchUserLocation() async {
    try {
      LocationPermission permission = await Geolocator.checkPermission();

      if (permission == LocationPermission.denied) {
        permission = await Geolocator.requestPermission();
      }

      if (permission == LocationPermission.denied ||
          permission == LocationPermission.deniedForever) {
        debugPrint(
          "Location permission unavailable.",
        );

        // Keep the map at ATBU Gubi.
        return;
      }

      final Position position = await Geolocator.getCurrentPosition(
        desiredAccuracy: LocationAccuracy.high,
      );

      if (!mounted) return;

      final LatLng location = LatLng(
        position.latitude,
        position.longitude,
      );

      setState(() {
        userLocation = location;

        // NEW:
        // GPS location is the initial pickup location.
        pickupLocation = location;

        _locationLoaded = true;
      });

      // Set user marker.
      _setMarkers();

      // Get address for pickup.
      await _getAddressFromLatLng(
        position.latitude,
        position.longitude,
      );

      // Once GPS is available, move map automatically.
      if (_mapReady && _mapController != null) {
        await Future.delayed(
          const Duration(milliseconds: 200),
        );

        if (!mounted || _mapController == null) return;

        await _mapController!.animateCamera(
          CameraUpdate.newCameraPosition(
            CameraPosition(
              target: location,
              zoom: 16,
            ),
          ),
        );
      }
    } catch (e) {
      debugPrint(
        "Error fetching location: $e",
      );
    }
  }

  // ============================================================
  // GET ADDRESS FROM COORDINATES
  // ============================================================

  Future<void> _getAddressFromLatLng(
    double lat,
    double lng,
  ) async {
    try {
      final List<Placemark> placemarks = await placemarkFromCoordinates(
        lat,
        lng,
      );

      if (placemarks.isEmpty) return;

      final Placemark place = placemarks.first;

      final List<String> parts = [];

      if ((place.street ?? '').trim().isNotEmpty) {
        parts.add(place.street!.trim());
      }

      if ((place.locality ?? '').trim().isNotEmpty) {
        parts.add(place.locality!.trim());
      }

      if ((place.administrativeArea ?? '').trim().isNotEmpty) {
        parts.add(
          place.administrativeArea!.trim(),
        );
      }

      final String address = parts.join(', ');

      if (!mounted) return;

      setState(() {
        pickupAddress = address;

        // Only autofill if the user has not typed anything.
        if (_pickupController.text.trim().isEmpty) {
          _pickupController.text = address;
        }
      });
    } catch (e) {
      debugPrint(
        "Error getting address: $e",
      );
    }
  }

  // ============================================================
  // MARKER
  // ============================================================

  void _setMarkers() {
    if (userLocation == null) return;

    setState(() {
      _markers = {
        Marker(
          markerId: const MarkerId('user'),
          position: userLocation!,
          infoWindow: const InfoWindow(
            title: "Your location",
          ),
          icon: BitmapDescriptor.defaultMarkerWithHue(
            BitmapDescriptor.hueBlue,
          ),
        ),
      };
    });
  }

  // ============================================================
  // PICKUP AUTOCOMPLETE
  // ============================================================

  void _onPickupChanged() {
    final String query = _pickupController.text.trim();

    if (query.isEmpty) {
      setState(() {
        _pickupSuggestions = [];
      });
      return;
    }

    _pickupDebounce?.cancel();

    _pickupDebounce = Timer(
      const Duration(milliseconds: 350),
      () {
        _fetchPlaceSuggestions(
          query,
          isPickup: true,
        );
      },
    );
  }

  // ============================================================
  // DESTINATION AUTOCOMPLETE
  // ============================================================

  void _onDestinationChanged() {
    final String query = _destinationController.text.trim();

    if (query.isEmpty) {
      setState(() {
        _destinationSuggestions = [];
      });
      return;
    }

    _destinationDebounce?.cancel();

    _destinationDebounce = Timer(
      const Duration(milliseconds: 350),
      () {
        _fetchPlaceSuggestions(
          query,
          isPickup: false,
        );
      },
    );
  }

  // ============================================================
  // GOOGLE PLACES AUTOCOMPLETE
  // ============================================================

  Future<void> _fetchPlaceSuggestions(
    String query, {
    required bool isPickup,
  }) async {
    if (query.trim().isEmpty) return;

    if (_googlePlacesApiKey == "YOUR_GOOGLE_MAPS_API_KEY") {
      debugPrint(
        "Google Places API key has not been configured.",
      );
      return;
    }

    if (!mounted) return;

    setState(() {
      if (isPickup) {
        _loadingPickupSuggestions = true;
      } else {
        _loadingDestinationSuggestions = true;
      }
    });

    try {
      final Map<String, dynamic> requestBody = {
        "input": query,

        // Restrict results to Nigeria.
        "includedRegionCodes": ["ng"],

        // Prefer locations around the user.
        if (userLocation != null)
          "locationBias": {
            "circle": {
              "center": {
                "latitude": userLocation!.latitude,
                "longitude": userLocation!.longitude,
              },
              "radius": 25000.0,
            },
          }
      };

      final response = await http.post(
        Uri.parse(
          "https://places.googleapis.com/v1/places:autocomplete",
        ),
        headers: {
          "Content-Type": "application/json",
          "X-Goog-Api-Key": _googlePlacesApiKey,
          "X-Goog-FieldMask": "suggestions.placePrediction.placeId,"
              "suggestions.placePrediction.text,"
              "suggestions.placePrediction.structuredFormat",
        },
        body: jsonEncode(requestBody),
      );

      if (response.statusCode != 200) {
        debugPrint(
          "Places autocomplete error: "
          "${response.statusCode} ${response.body}",
        );
        return;
      }

      final Map<String, dynamic> data = jsonDecode(response.body);

      final List suggestions = data["suggestions"] ?? [];

      final List<Map<String, dynamic>> results = [];

      for (final item in suggestions) {
        final prediction = item["placePrediction"];

        if (prediction == null) continue;

        final String placeId = prediction["placeId"]?.toString() ?? "";

        final String description =
            prediction["text"]?["text"]?.toString() ?? "";

        final String mainText =
            prediction["structuredFormat"]?["mainText"]?["text"]?.toString() ??
                description;

        final String secondaryText = prediction["structuredFormat"]
                    ?["secondaryText"]?["text"]
                ?.toString() ??
            "";

        if (description.isEmpty) continue;

        results.add({
          "placeId": placeId,
          "description": description,
          "mainText": mainText,
          "secondaryText": secondaryText,
        });
      }

      if (!mounted) return;

      setState(() {
        if (isPickup) {
          _pickupSuggestions = results;
        } else {
          _destinationSuggestions = results;
        }
      });
    } catch (e) {
      debugPrint(
        "Autocomplete request failed: $e",
      );
    } finally {
      if (!mounted) return;

      setState(() {
        if (isPickup) {
          _loadingPickupSuggestions = false;
        } else {
          _loadingDestinationSuggestions = false;
        }
      });
    }
  }

  // ============================================================
  // GET PLACE DETAILS
  // ============================================================

  Future<LatLng?> _getPlaceLocation(
    String placeId,
  ) async {
    if (placeId.isEmpty) return null;

    try {
      final response = await http.get(
        Uri.parse(
          "https://places.googleapis.com/v1/places/$placeId",
        ),
        headers: {
          "X-Goog-Api-Key": _googlePlacesApiKey,
          "X-Goog-FieldMask": "location,formattedAddress,displayName",
        },
      );

      if (response.statusCode != 200) {
        debugPrint(
          "Place details error: "
          "${response.statusCode}",
        );
        return null;
      }

      final Map<String, dynamic> data = jsonDecode(response.body);

      final location = data["location"];

      if (location == null) return null;

      final double? lat = (location["latitude"] as num?)?.toDouble();

      final double? lng = (location["longitude"] as num?)?.toDouble();

      if (lat == null || lng == null) {
        return null;
      }

      return LatLng(lat, lng);
    } catch (e) {
      debugPrint(
        "Place details failed: $e",
      );
      return null;
    }
  }

  // ============================================================
  // GET GOOGLE ROAD ROUTE
  // ============================================================

  Future<List<LatLng>> _getRoutePoints(
    LatLng pickup,
    LatLng destination,
  ) async {
    try {
      final response = await http.post(
        Uri.parse(
          "https://routes.googleapis.com/directions/v2:computeRoutes",
        ),
        headers: {
          "Content-Type": "application/json",
          "X-Goog-Api-Key": _googlePlacesApiKey,

          // We intentionally request GeoJSON instead of an
          // encoded polyline. This prevents coordinate decoding
          // errors and gives us [longitude, latitude] directly.
          "X-Goog-FieldMask": "routes.polyline.geoJsonLinestring",
        },
        body: jsonEncode({
          "origin": {
            "location": {
              "latLng": {
                "latitude": pickup.latitude,
                "longitude": pickup.longitude,
              },
            },
          },
          "destination": {
            "location": {
              "latLng": {
                "latitude": destination.latitude,
                "longitude": destination.longitude,
              },
            },
          },
          "travelMode": "DRIVE",
          "routingPreference": "TRAFFIC_AWARE",
          "computeAlternativeRoutes": false,
          "polylineQuality": "HIGH_QUALITY",
          "polylineEncoding": "GEO_JSON_LINESTRING",
        }),
      );

      debugPrint(
        "ROUTES STATUS: ${response.statusCode}",
      );

      if (response.statusCode != 200) {
        debugPrint(
          "ROUTES ERROR: ${response.body}",
        );
        return [];
      }

      final Map<String, dynamic> data = jsonDecode(response.body);

      final List routes = data["routes"] ?? [];

      if (routes.isEmpty) {
        debugPrint(
          "NO ROUTE FOUND",
        );
        return [];
      }

      final dynamic geometry = routes.first["polyline"]?["geoJsonLinestring"];

      if (geometry == null) {
        debugPrint(
          "NO GEOJSON ROUTE RETURNED",
        );
        return [];
      }

      final List coordinates = geometry["coordinates"] ?? [];

      if (coordinates.length < 2) {
        debugPrint(
          "ROUTE HAS TOO FEW POINTS",
        );
        return [];
      }

      final List<LatLng> points = [];

      for (final dynamic coordinate in coordinates) {
        if (coordinate is! List || coordinate.length < 2) {
          continue;
        }

        // IMPORTANT:
        // GeoJSON coordinates are:
        //
        // [longitude, latitude]
        //
        // GoogleMap LatLng requires:
        //
        // LatLng(latitude, longitude)
        final double? longitude = (coordinate[0] as num?)?.toDouble();

        final double? latitude = (coordinate[1] as num?)?.toDouble();

        if (latitude == null || longitude == null) {
          continue;
        }

        points.add(
          LatLng(
            latitude,
            longitude,
          ),
        );
      }

      if (points.length < 2) {
        debugPrint(
          "DECODED ROUTE HAS TOO FEW POINTS",
        );
        return [];
      }

      // Replace ONLY the first and last route points.
      //
      // This makes the line begin exactly at our pickup
      // and finish exactly at our destination while
      // preserving Google's road geometry between them.
      points[0] = pickup;
      points[points.length - 1] = destination;

      debugPrint(
        "ROUTE POINTS: ${points.length}",
      );

      debugPrint(
        "ROUTE START: "
        "${points.first.latitude}, "
        "${points.first.longitude}",
      );

      debugPrint(
        "ROUTE END: "
        "${points.last.latitude}, "
        "${points.last.longitude}",
      );

      return points;
    } catch (e) {
      debugPrint(
        "GET ROUTE ERROR: $e",
      );

      return [];
    }
  }

  // ============================================================
  // ANIMATE ROUTE FROM PICKUP TO DESTINATION
  // ============================================================

  Future<void> _drawAnimatedRoute() async {
    if (pickupLocation == null || destinationLocation == null) {
      return;
    }

    final LatLng pickup = pickupLocation!;

    final LatLng destination = destinationLocation!;

    // Cancel any previous route animation.
    _routeAnimationTimer?.cancel();

    if (!mounted) return;

    // Clear old route immediately.
    setState(() {
      _isLoadingRoute = true;
      _routePoints = [];
      _polylines = {};
    });

    final List<LatLng> points = await _getRoutePoints(
      pickup,
      destination,
    );

    if (!mounted) return;

    if (points.length < 2) {
      setState(() {
        _isLoadingRoute = false;
      });

      return;
    }

    _routePoints = points;

    setState(() {
      _isLoadingRoute = false;
    });

    // Fit the complete route into the visible map.
    await _fitRouteOnMap();

    if (!mounted) return;

    // ==========================================================
    // START ANIMATION
    // ==========================================================

    // Start with two points so the route is immediately visible.
    int visiblePoints = 2;

    setState(() {
      _polylines = {
        Polyline(
          polylineId: const PolylineId("ride_route"),
          points: _routePoints.take(visiblePoints).toList(),
          color: Colors.green,
          width: 5,
          geodesic: false,
          jointType: JointType.round,
          startCap: Cap.roundCap,
          endCap: Cap.roundCap,
        ),
      };
    });

    _routeAnimationTimer = Timer.periodic(
      const Duration(milliseconds: 25),
      (timer) {
        if (!mounted) {
          timer.cancel();
          return;
        }

        // ========================================================
        // FINISHED
        // ========================================================

        if (visiblePoints >= _routePoints.length) {
          timer.cancel();

          setState(() {
            _polylines = {
              Polyline(
                polylineId: const PolylineId(
                  "ride_route",
                ),
                points: List<LatLng>.from(
                  _routePoints,
                ),
                color: Colors.green,
                width: 5,
                geodesic: false,
                jointType: JointType.round,
                startCap: Cap.roundCap,
                endCap: Cap.roundCap,
              ),
            };
          });

          return;
        }

        // ========================================================
        // ADVANCE ANIMATION
        // ========================================================

        final int step = (_routePoints.length / 100).ceil().clamp(1, 8);

        visiblePoints += step;

        if (visiblePoints > _routePoints.length) {
          visiblePoints = _routePoints.length;
        }

        setState(() {
          _polylines = {
            Polyline(
              polylineId: const PolylineId(
                "ride_route",
              ),
              points: _routePoints.take(visiblePoints).toList(),
              color: Colors.green,
              width: 5,
              geodesic: false,
              jointType: JointType.round,
              startCap: Cap.roundCap,
              endCap: Cap.roundCap,
            ),
          };
        });
      },
    );
  }

  // ============================================================
  // FIT ENTIRE ROAD ROUTE ON MAP
  // ============================================================

  Future<void> _fitRouteOnMap() async {
    if (_mapController == null || _routePoints.isEmpty) {
      return;
    }

    double minLat = _routePoints.first.latitude;

    double maxLat = _routePoints.first.latitude;

    double minLng = _routePoints.first.longitude;

    double maxLng = _routePoints.first.longitude;

    for (final LatLng point in _routePoints) {
      if (point.latitude < minLat) {
        minLat = point.latitude;
      }

      if (point.latitude > maxLat) {
        maxLat = point.latitude;
      }

      if (point.longitude < minLng) {
        minLng = point.longitude;
      }

      if (point.longitude > maxLng) {
        maxLng = point.longitude;
      }
    }

    // Prevent zero-size bounds for very short routes.
    if ((maxLat - minLat).abs() < 0.001) {
      minLat -= 0.001;
      maxLat += 0.001;
    }

    if ((maxLng - minLng).abs() < 0.001) {
      minLng -= 0.001;
      maxLng += 0.001;
    }

    try {
      await _mapController!.animateCamera(
        CameraUpdate.newLatLngBounds(
          LatLngBounds(
            southwest: LatLng(
              minLat,
              minLng,
            ),
            northeast: LatLng(
              maxLat,
              maxLng,
            ),
          ),
          70,
        ),
      );
    } catch (e) {
      debugPrint(
        "FIT ROUTE ERROR: $e",
      );
    }
  }

  // ============================================================
  // SELECT AUTOCOMPLETE RESULT
  // ============================================================

  Future<void> _selectSuggestion(
    Map<String, dynamic> suggestion, {
    required bool isPickup,
  }) async {
    final String description = suggestion["description"]?.toString() ?? "";

    final String placeId = suggestion["placeId"]?.toString() ?? "";

    if (description.isEmpty) return;

    FocusScope.of(context).unfocus();

    setState(() {
      if (isPickup) {
        _pickupController.text = description;

        _pickupSuggestions = [];
      } else {
        _destinationController.text = description;

        _destinationSuggestions = [];
      }

      _activeAutocompleteField = null;
    });

    // Get exact coordinates of selected place.
    final LatLng? location = await _getPlaceLocation(placeId);

    if (location == null) return;

    if (!mounted) return;

    // ==========================================================
    // PICKUP SELECTED
    // ==========================================================

    if (isPickup) {
      // Any existing route is now invalid because
      // the pickup has changed.
      _routeAnimationTimer?.cancel();

      _routePoints = [];

      setState(() {
        pickupLocation = location;
        _polylines = {};
      });
    }

    // ==========================================================
    // DESTINATION SELECTED
    // ==========================================================

    else {
      setState(() {
        destinationLocation = location;
      });
    }

    // ==========================================================
    // UPDATE MARKERS
    // ==========================================================

    final Set<Marker> updatedMarkers = {
      ..._markers,
      Marker(
        markerId: MarkerId(
          isPickup ? "selected_pickup" : "selected_destination",
        ),
        position: location,
        infoWindow: InfoWindow(
          title: isPickup ? "Pickup location" : "Destination",
          snippet: description,
        ),
      ),
    };

    setState(() {
      _markers = updatedMarkers;
    });

    // ==========================================================
    // DRAW ROUTE ONLY AFTER DESTINATION IS SELECTED
    // ==========================================================

    if (!isPickup && pickupLocation != null && destinationLocation != null) {
      await _drawAnimatedRoute();
    }

    // ==========================================================
    // MOVE CAMERA FOR PICKUP
    // ==========================================================

    else if (isPickup && _mapController != null) {
      await _mapController!.animateCamera(
        CameraUpdate.newCameraPosition(
          CameraPosition(
            target: location,
            zoom: 16,
          ),
        ),
      );
    }
  }

  // ============================================================
  // AUTOCOMPLETE FIELD
  // ============================================================

  Widget _buildLocationField({
    required TextEditingController controller,
    required FocusNode focusNode,
    required String hintText,
    required IconData icon,
    required Color iconColor,
    required bool isPickup,
  }) {
    final List<Map<String, dynamic>> suggestions =
        isPickup ? _pickupSuggestions : _destinationSuggestions;

    final bool loading =
        isPickup ? _loadingPickupSuggestions : _loadingDestinationSuggestions;

    return Column(
      children: [
        TextField(
          controller: controller,
          focusNode: focusNode,
          onTap: () {
            setState(() {
              _activeAutocompleteField = isPickup ? "pickup" : "destination";
            });

            if (controller.text.trim().isNotEmpty) {
              _fetchPlaceSuggestions(
                controller.text.trim(),
                isPickup: isPickup,
              );
            }
          },
          decoration: InputDecoration(
            hintText: hintText,
            filled: true,
            fillColor: Colors.grey[100],
            prefixIcon: Icon(
              icon,
              color: iconColor,
            ),

            // ==================================================
            // BLACK AUTOCOMPLETE LOADING INDICATOR
            // ==================================================

            suffixIcon: loading
                ? const Padding(
                    padding: EdgeInsets.all(14),
                    child: SizedBox(
                      width: 16,
                      height: 16,
                      child: CircularProgressIndicator(
                        strokeWidth: 2,
                        color: Colors.black,
                      ),
                    ),
                  )
                : null,

            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(14),
              borderSide: BorderSide.none,
            ),
          ),
        ),

        // ======================================================
        // AUTOCOMPLETE RESULTS
        // ======================================================

        if (_activeAutocompleteField == (isPickup ? "pickup" : "destination") &&
            suggestions.isNotEmpty)
          Container(
            margin: const EdgeInsets.only(top: 4),
            constraints: const BoxConstraints(
              maxHeight: 190,
            ),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(14),
              boxShadow: [
                BoxShadow(
                  color: Colors.black.withOpacity(
                    0.08,
                  ),
                  blurRadius: 10,
                  offset: const Offset(0, 4),
                ),
              ],
            ),
            child: ListView.separated(
              shrinkWrap: true,
              padding: const EdgeInsets.symmetric(
                vertical: 6,
              ),
              itemCount: suggestions.length,
              separatorBuilder: (_, __) => const Divider(
                height: 1,
                indent: 52,
                endIndent: 12,
              ),
              itemBuilder: (context, index) {
                final suggestion = suggestions[index];

                return ListTile(
                  dense: true,
                  leading: Container(
                    width: 34,
                    height: 34,
                    decoration: BoxDecoration(
                      color: Colors.grey[100],
                      shape: BoxShape.circle,
                    ),
                    child: const Icon(
                      Icons.location_on_outlined,
                      size: 18,
                      color: Colors.black87,
                    ),
                  ),
                  title: Text(
                    suggestion["mainText"] ?? suggestion["description"] ?? "",
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  subtitle:
                      suggestion["secondaryText"]?.toString().isNotEmpty == true
                          ? Text(
                              suggestion["secondaryText"],
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                fontSize: 11,
                                color: Colors.grey[600],
                              ),
                            )
                          : null,
                  onTap: () {
                    _selectSuggestion(
                      suggestion,
                      isPickup: isPickup,
                    );
                  },
                );
              },
            ),
          ),
      ],
    );
  }

  // ============================================================
  // RIDE FLOW
  // ============================================================

  void _handleRideSelection(
    String rideType,
  ) {
    final String pickup = _pickupController.text.trim();

    final String destination = _destinationController.text.trim();

    // ============================================================
    // VALIDATE PICKUP
    // ============================================================

    if (pickup.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            "Please select a pickup location.",
          ),
        ),
      );

      return;
    }

    // ============================================================
    // VALIDATE DESTINATION
    // ============================================================

    if (destination.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            "Please select a destination.",
          ),
        ),
      );

      return;
    }

    // ============================================================
    // VALIDATE PICKUP COORDINATES
    // ============================================================

    if (pickupLocation == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            "Please select your pickup location again.",
          ),
        ),
      );

      return;
    }

    // ============================================================
    // VALIDATE DESTINATION COORDINATES
    // ============================================================

    if (destinationLocation == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            "Please select your destination again.",
          ),
        ),
      );

      return;
    }

    // ============================================================
    // OPEN SEARCHING SCREEN IMMEDIATELY
    // ============================================================

    Navigator.of(context).push(
      MaterialPageRoute(
        fullscreenDialog: true,
        builder: (_) => SearchingScreen(
          rideType: rideType,
          pickupLocation: pickup,
          destination: destination,
          pickupLat: pickupLocation!.latitude,
          pickupLng: pickupLocation!.longitude,
          destinationLat: destinationLocation!.latitude,
          destinationLng: destinationLocation!.longitude,
