                // BUSINESS NAME
                // ==================================================

                TextFormField(
                  controller: _businessNameController,
                  decoration: _inputDecoration(
                    'Business Name',
                  ),
                  validator: (value) {
                    if (value == null || value.trim().isEmpty) {
                      return 'Enter business name';
                    }

                    return null;
                  },
                ),

                const SizedBox(
                  height: 16,
                ),

                // ==================================================
                // CATEGORY
                // ==================================================

                DropdownButtonFormField<String>(
                  value: _selectedCategory,
                  items: _categories
                      .map(
                        (category) => DropdownMenuItem(
                          value: category,
                          child: Text(
                            category,
                          ),
                        ),
                      )
                      .toList(),
                  onChanged: (value) {
                    setState(() {
                      _selectedCategory = value;
                    });
                  },
                  decoration: _inputDecoration(
                    'Select Category',
                  ),
                  validator: (value) =>
                      value == null ? 'Select a category' : null,
                ),

                const SizedBox(
                  height: 20,
                ),

                // ==================================================
                // OPERATING HOURS
                // ==================================================

                _buildOperatingHoursCard(),

                const SizedBox(
                  height: 20,
                ),

                // ==================================================
                // STORE LOCATION
                // ==================================================

                _buildLocationCard(),

                const SizedBox(
                  height: 20,
                ),

                // ==================================================
                // ACCOUNT NUMBER
                // ==================================================

                TextFormField(
                  controller: _accountNumberController,
                  keyboardType: TextInputType.number,
                  decoration: _inputDecoration(
                    'Account Number',
                  ),
                  validator: (value) {
                    if (value == null || value.trim().isEmpty) {
                      return 'Enter account number';
                    }

                    return null;
                  },
                ),

                const SizedBox(
                  height: 16,
                ),

                // ==================================================
                // BANK
                // ==================================================

                DropdownButtonFormField<String>(
                  value: _selectedBank,
                  items: _banks
                      .map(
                        (bank) => DropdownMenuItem(
                          value: bank,
                          child: Text(
                            bank,
                          ),
                        ),
                      )
                      .toList(),
                  onChanged: (value) {
                    setState(() {
                      _selectedBank = value;
                    });
                  },
                  decoration: _inputDecoration(
                    'Select Bank',
                  ),
                  validator: (value) => value == null ? 'Select a bank' : null,
                ),

                const SizedBox(
                  height: 16,
                ),

                // ==================================================
                // ACCOUNT NAME
                // ==================================================

                TextFormField(
                  controller: _accountNameController,
                  decoration: _inputDecoration(
                    'Account Name',
                  ),
                  validator: (value) {
                    if (value == null || value.trim().isEmpty) {
                      return 'Enter account name';
                    }

                    return null;
                  },
                ),

                const SizedBox(
                  height: 24,
                ),

                // ==================================================
                // SUBMIT
                // ==================================================

                SizedBox(
                  width: double.infinity,
                  height: 52,
                  child: ElevatedButton(
                    onPressed: _isLoading ? null : _submitVendor,
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.black,
                      disabledBackgroundColor: Colors.grey.shade300,
                      elevation: 0,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(
                          13,
                        ),
                      ),
                    ),
                    child: _isLoading
                        ? const SizedBox(
                            width: 21,
                            height: 21,
                            child: CircularProgressIndicator(
                              color: Colors.white,
                              strokeWidth: 2,
                            ),
                          )
                        : const Text(
                            'Get Onboard',
                            style: TextStyle(
                              fontSize: 17,
                              fontWeight: FontWeight.bold,
                              color: Colors.white,
                            ),
                          ),
                  ),
                ),

                const SizedBox(
                  height: 24,
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// ============================================================================
// VENDOR MAP LOCATION PAGE
//
// This replaces the old location picker + reverse-geocoding flow.
//
// Google Places is ONLY used to:
// 1. Help the vendor search for an area.
// 2. Move the map/pin to that area's coordinates.
//
// It does NOT provide the address that gets saved.
// ============================================================================

class _VendorManualMapPage extends StatefulWidget {
  final double? initialLatitude;
  final double? initialLongitude;

  final String state;
  final String city;

  final Future<List<Map<String, dynamic>>> Function(
    String query,
  ) fetchSuggestions;

  final Future<Map<String, dynamic>?> Function(
    String placeId,
  ) getPlaceDetails;

  final Future<LatLng?> Function() resolveCityCoordinates;

  const _VendorManualMapPage({
    required this.initialLatitude,
    required this.initialLongitude,
    required this.state,
    required this.city,
    required this.fetchSuggestions,
    required this.getPlaceDetails,
    required this.resolveCityCoordinates,
  });

  @override
  State<_VendorManualMapPage> createState() => _VendorManualMapPageState();
}

// ============================================================================
// MAP STATE
// ============================================================================

class _VendorManualMapPageState extends State<_VendorManualMapPage> {
  GoogleMapController? _mapController;

  final TextEditingController _searchController = TextEditingController();

  Timer? _searchDebounce;

  List<Map<String, dynamic>> _suggestions = [];

  LatLng? _selectedPosition;

  LatLng? _cityCenter;

  bool _loadingCity = false;

  bool _loadingSuggestions = false;

  bool _loadingPlaceDetails = false;

  static const LatLng _nigeriaCenter = LatLng(
    9.0820,
    8.6753,
  );

  @override
  void initState() {
    super.initState();

    // If we already have coordinates from a
    // previous selection, use them.
    if (widget.initialLatitude != null && widget.initialLongitude != null) {
      _selectedPosition = LatLng(
        widget.initialLatitude!,
        widget.initialLongitude!,
      );
    }

    // Resolve the selected city so the map
    // initially opens around that city.
    WidgetsBinding.instance.addPostFrameCallback(
      (_) {
        _initializeMap();
      },
    );
  }

  @override
  void dispose() {
    _searchDebounce?.cancel();
    _searchController.dispose();

    super.dispose();
  }

  // ==========================================================
  // INITIALIZE MAP
  // ==========================================================

  Future<void> _initializeMap() async {
    if (_selectedPosition != null) {
      _moveCamera(
        _selectedPosition!,
        zoom: 17,
      );

      return;
    }

    if (!mounted) return;

    setState(() {
      _loadingCity = true;
    });

    try {
      final cityCoordinates = await widget.resolveCityCoordinates();

      if (!mounted) return;

      if (cityCoordinates != null) {
        _cityCenter = cityCoordinates;

        await _moveCamera(
          cityCoordinates,
          zoom: 13,
        );
      }
    } catch (e) {
      debugPrint(
        'MAP CITY INITIALIZATION ERROR: $e',
      );
    } finally {
      if (mounted) {
        setState(() {
          _loadingCity = false;
        });
      }
    }
  }

  // ==========================================================
  // MOVE CAMERA
  // ==========================================================

  Future<void> _moveCamera(
    LatLng position, {
    double zoom = 15,
  }) async {
    final controller = _mapController;

    if (controller == null) {
      return;
    }

    try {
      await controller.animateCamera(
        CameraUpdate.newCameraPosition(
          CameraPosition(
            target: position,
            zoom: zoom,
          ),
        ),
      );
    } catch (e) {
      debugPrint(
        'MAP CAMERA ERROR: $e',
      );
    }
  }

  // ==========================================================
  // SEARCH CHANGE
  // ==========================================================

  void _onSearchChanged(
    String value,
  ) {
    _searchDebounce?.cancel();

    final query = value.trim();

    if (query.length < 3) {
      setState(() {
        _suggestions = [];
        _loadingSuggestions = false;
      });

      return;
    }

    _searchDebounce = Timer(
      const Duration(
        milliseconds: 400,
      ),
      () async {
        if (!mounted) return;

        setState(() {
          _loadingSuggestions = true;
        });

        try {
          final results = await widget.fetchSuggestions(
            query,
          );

          if (!mounted) return;

          setState(() {
            _suggestions = results;
            _loadingSuggestions = false;
          });
        } catch (e) {
          debugPrint(
            'VENDOR MAP SEARCH ERROR: $e',
          );

          if (!mounted) return;

          setState(() {
            _suggestions = [];
            _loadingSuggestions = false;
          });
        }
      },
    );
  }

  // ==========================================================
  // SELECT GOOGLE SEARCH RESULT
  //
  // IMPORTANT:
  //
  // We DO NOT save formattedAddress.
  //
  // We ONLY use Google's coordinates to move
  // the map and pin.
  // ==========================================================

  Future<void> _selectSuggestion(
    Map<String, dynamic> suggestion,
  ) async {
    final placeId = suggestion['placeId']?.toString() ?? '';

    if (placeId.isEmpty) {
      return;
    }

    FocusScope.of(context).unfocus();

    _searchDebounce?.cancel();

    setState(() {
      _suggestions = [];
      _loadingPlaceDetails = true;
    });

    try {
      final details = await widget.getPlaceDetails(
        placeId,
      );

      if (!mounted) return;

      final latitude = (details?['latitude'] as num?)?.toDouble();

      final longitude = (details?['longitude'] as num?)?.toDouble();

      if (latitude == null || longitude == null) {
        setState(() {
          _loadingPlaceDetails = false;
        });

        _showMessage(
          'Unable to locate this area on the map.',
        );

        return;
      }

      final position = LatLng(
        latitude,
        longitude,
      );

      // The Google result is ONLY used
      // as a coordinate helper.
      //
      // It does not become the saved
      // store address.
      setState(() {
        _selectedPosition = position;
        _loadingPlaceDetails = false;
      });

      await _moveCamera(
        position,
        zoom: 17,
      );
    } catch (e) {
      debugPrint(
        'VENDOR MAP PLACE DETAILS ERROR: $e',
      );

      if (!mounted) return;

      setState(() {
        _loadingPlaceDetails = false;
      });

      _showMessage(
        'Unable to locate this area.',
      );
    }
  }

  // ==========================================================
  // MAP TAP
  // ==========================================================

  void _selectPosition(
    LatLng position,
  ) {
    setState(() {
      _selectedPosition = position;
    });
  }

  // ==========================================================
  // MARKER DRAG
  // ==========================================================

  void _onMarkerDragEnd(
    LatLng position,
  ) {
    setState(() {
      _selectedPosition = position;
    });
  }

  // ==========================================================
  // CONFIRM
  // ==========================================================

  void _confirm() {
    if (_selectedPosition == null) {
      _showMessage(
        'Tap the map or search for an area to select your store location.',
      );

      return;
    }

    Navigator.pop(
      context,
      {
        'latitude': _selectedPosition!.latitude,
        'longitude': _selectedPosition!.longitude,
      },
    );
  }

  // ==========================================================
  // MESSAGE
  // ==========================================================

  void _showMessage(
    String message,
  ) {
    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
      ),
    );
  }

  // ==========================================================
  // BUILD
  // ==========================================================

  @override
  Widget build(
    BuildContext context,
  ) {
    final initialPosition = _selectedPosition ?? _cityCenter ?? _nigeriaCenter;

    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: Colors.white,
        foregroundColor: Colors.black,
        elevation: 0,
        title: const Text(
          'Select Store Location',
          style: TextStyle(
            fontSize: 17,
            fontWeight: FontWeight.bold,
          ),
        ),
      ),
      body: Stack(
        children: [
          // ========================================================
          // MAP
          // ========================================================

          GoogleMap(
            initialCameraPosition: CameraPosition(
              target: initialPosition,
              zoom: _selectedPosition != null ? 17 : 5.5,
            ),
            myLocationButtonEnabled: false,
            zoomControlsEnabled: false,
            compassEnabled: true,
            mapToolbarEnabled: false,
            onMapCreated: (controller) {
              _mapController = controller;

              // If city coordinates
              // have already been resolved,
              // center on them.
              if (_selectedPosition != null) {
                _moveCamera(
                  _selectedPosition!,
                  zoom: 17,
                );
              } else if (_cityCenter != null) {
                _moveCamera(
                  _cityCenter!,
                  zoom: 13,
                );
              }
            },
            onTap: _selectPosition,
            markers: _selectedPosition == null
                ? {}
                : {
                    Marker(
                      markerId: const MarkerId(
                        'vendor_store',
                      ),
                      position: _selectedPosition!,
                      draggable: true,
                      onDragEnd: _onMarkerDragEnd,
                    ),
                  },
          ),

          // ========================================================
          // TOP SEARCH AREA
          // ========================================================

          Positioned(
            top: 12,
            left: 12,
            right: 12,
            child: Column(
              children: [
                Container(
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(
                      13,
                    ),
                    boxShadow: const [
                      BoxShadow(
                        color: Colors.black12,
                        blurRadius: 14,
                        offset: Offset(
                          0,
                          4,
                        ),
                      ),
                    ],
                  ),
                  child: TextField(
                    controller: _searchController,
                    onChanged: _onSearchChanged,
                    textInputAction: TextInputAction.search,
                    decoration: InputDecoration(
                      hintText: 'Search an area to help locate your store',
                      hintStyle: const TextStyle(
                        fontSize: 11,
                      ),
                      prefixIcon: const Icon(
                        Icons.search,
                        size: 20,
                      ),
                      suffixIcon: _loadingSuggestions || _loadingPlaceDetails
                          ? const Padding(
                              padding: EdgeInsets.all(
                                12,
                              ),
                              child: SizedBox(
                                width: 16,
                                height: 16,
                                child: CircularProgressIndicator(
                                  strokeWidth: 2,
                                ),
                              ),
                            )
                          : null,
                      filled: true,
                      fillColor: Colors.white,
                      contentPadding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 14,
                      ),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(
                          13,
                        ),
                        borderSide: BorderSide.none,
                      ),
                    ),
                  ),
                ),

                // ====================================================
                // SEARCH SUGGESTIONS
                // ====================================================

                if (_suggestions.isNotEmpty)
                  Container(
                    margin: const EdgeInsets.only(
                      top: 6,
                    ),
                    constraints: const BoxConstraints(
                      maxHeight: 280,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(
                        12,
                      ),
                      boxShadow: const [
                        BoxShadow(
                          color: Colors.black12,
                          blurRadius: 14,
                          offset: Offset(
                            0,
                            4,
                          ),
                        ),
                      ],
                    ),
                    child: ListView.separated(
                      shrinkWrap: true,
                      padding: EdgeInsets.zero,
                      itemCount: _suggestions.length,
                      separatorBuilder: (_, __) => Divider(
                        height: 1,
                        color: Colors.grey.shade200,
                      ),
                      itemBuilder: (context, index) {
                        final suggestion = _suggestions[index];

                        return InkWell(
                          onTap: () => _selectSuggestion(
                            suggestion,
                          ),
                          child: Padding(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 12,
                              vertical: 11,
                            ),
                            child: Row(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Container(
                                  width: 34,
                                  height: 34,
                                  decoration: BoxDecoration(
                                    color: Colors.grey.shade100,
                                    borderRadius: BorderRadius.circular(
                                      9,
                                    ),
                                  ),
                                  child: const Icon(
                                    Icons.location_on_outlined,
                                    size: 18,
                                  ),
                                ),
                                const SizedBox(
                                  width: 10,
                                ),
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        suggestion['mainText']?.toString() ??
                                            '',
                                        maxLines: 1,
                                        overflow: TextOverflow.ellipsis,
                                        style: const TextStyle(
                                          fontSize: 12,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                      const SizedBox(
                                        height: 3,
                                      ),
                                      Text(
                                        suggestion['secondaryText']
                                                ?.toString() ??
                                            '',
                                        maxLines: 2,
                                        overflow: TextOverflow.ellipsis,
                                        style: TextStyle(
                                          fontSize: 10,
                                          color: Colors.grey.shade600,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
                  ),
              ],
            ),
          ),

          // ========================================================
          // INSTRUCTION
          // ========================================================

          Positioned(
            left: 12,
            right: 12,
            bottom: 140,
            child: IgnorePointer(
              child: Container(
                padding: const EdgeInsets.all(
                  11,
                ),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(
                    12,
                  ),
                  boxShadow: const [
                    BoxShadow(
                      color: Colors.black12,
                      blurRadius: 12,
                      offset: Offset(
                        0,
                        4,
                      ),
                    ),
                  ],
                ),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Icon(
                      Icons.location_on,
                      size: 19,
                    ),
                    const SizedBox(
                      width: 8,
                    ),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'Position your store pin exactly',
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.bold,
                            ),
                          ),
                          const SizedBox(
                            height: 3,
                          ),
                          Text(
                            'Search to move the map, tap the map, or drag the pin to the exact store location.',
                            style: TextStyle(
                              fontSize: 9,
                              height: 1.35,
                              color: Colors.grey.shade600,
                            ),
                          ),
                          const SizedBox(
                            height: 3,
                          ),
                          Text(
                            '${widget.city}, ${widget.state}',
                            style: TextStyle(
                              fontSize: 9,
                              fontWeight: FontWeight.w600,
                              color: Colors.grey.shade700,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),

          // ========================================================
          // CITY LOADING
          // ========================================================

          if (_loadingCity)
            Positioned(
              top: 82,
              right: 14,
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 10,
                  vertical: 7,
                ),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(
                    20,
                  ),
                  boxShadow: const [
                    BoxShadow(
                      color: Colors.black12,
                      blurRadius: 10,
                    ),
                  ],
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    const SizedBox(
                      width: 13,
                      height: 13,
                      child: CircularProgressIndicator(
                        strokeWidth: 2,
                      ),
                    ),
                    const SizedBox(
                      width: 7,
                    ),
                    Text(
                      'Locating city...',
                      style: TextStyle(
                        fontSize: 9,
                        color: Colors.grey.shade700,
                      ),
                    ),
                  ],
                ),
              ),
            ),

          // ========================================================
          // SELECTED COORDINATES
          // ========================================================

          if (_selectedPosition != null)
            Positioned(
              left: 12,
              right: 12,
              bottom: 78,
              child: Container(
                padding: const EdgeInsets.all(
                  10,
                ),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(
                    11,
                  ),
                  boxShadow: const [
                    BoxShadow(
                      color: Colors.black12,
                      blurRadius: 10,
                      offset: Offset(
                        0,
                        3,
                      ),
                    ),
                  ],
                ),
                child: Row(
                  children: [
                    const Icon(
                      Icons.check_circle,
                      color: Colors.green,
                      size: 18,
                    ),
                    const SizedBox(
                      width: 8,
                    ),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'Exact map location selected',
                            style: TextStyle(
                              fontSize: 10,
                              fontWeight: FontWeight.bold,
                              color: Colors.green,
                            ),
                          ),
                          const SizedBox(
                            height: 3,
                          ),
                          Text(
                            '${_selectedPosition!.latitude.toStringAsFixed(6)}, ${_selectedPosition!.longitude.toStringAsFixed(6)}',
                            style: TextStyle(
                              fontSize: 9,
                              color: Colors.grey.shade600,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ),
            ),

          // ========================================================
          // CONFIRM BUTTON
          // ========================================================

          Positioned(
            left: 12,
            right: 12,
            bottom: 14,
            child: SizedBox(
              height: 52,
              child: ElevatedButton(
                onPressed: _selectedPosition == null ? null : _confirm,
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.black,
                  disabledBackgroundColor: Colors.grey.shade400,
                  foregroundColor: Colors.white,
                  elevation: 2,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(
                      13,
                    ),
                  ),
                ),
                child: const Text(
                  'Confirm Store Location',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class VendorOrderDetailsPage extends StatefulWidget {
  final String orderId;
  final Map<String, dynamic> orderData;

  const VendorOrderDetailsPage({
    super.key,
    required this.orderId,
    required this.orderData,
  });

  @override
  State<VendorOrderDetailsPage> createState() => _VendorOrderDetailsPageState();
}

class _VendorOrderDetailsPageState extends State<VendorOrderDetailsPage> {
  late Map<String, dynamic> _order; // Local copy to update UI
  bool _isUpdating = false;

  @override
  void initState() {
    super.initState();
    _order = Map<String, dynamic>.from(widget.orderData);
  }

  Future<void> _acceptOrder() async {
    setState(() => _isUpdating = true);

    // Generate a 6-digit pickup code
    final pickupCode = Random().nextInt(900000) + 100000; // 100000 - 999999

    try {
      await FirebaseFirestore.instance
          .collection('orders')
          .doc(widget.orderId)
          .update({
        'status': 'accepted',
        'pickupCode': pickupCode,
      });

      // Update local copy to reflect UI immediately
      setState(() {
        _order['status'] = 'accepted';
        _order['pickupCode'] = pickupCode;
      });

      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text("Order accepted. Pickup code: $pickupCode"),
      ));
    } catch (e) {
      ScaffoldMessenger.of(context)
          .showSnackBar(SnackBar(content: Text("Error: $e")));
    } finally {
      setState(() => _isUpdating = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    final itemsMap = _order['items'] as Map<String, dynamic>? ?? {};
    double totalPrice = 0;
    itemsMap.forEach((key, value) {
      final price = value['price'] ?? 0;
      final qty = value['qty'] ?? 1;
      totalPrice += price * qty;
    });

    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        //automaticallyImplyLeading: false, // 👈 turn this off since we customize it
        backgroundColor: Colors.white,
        elevation: 0,
        scrolledUnderElevation: 0,

        leading: Padding(
          padding: const EdgeInsets.only(left: 10),
          child: GestureDetector(
            onTap: () => Navigator.pop(context),
            child: Container(
              width: 25,
              height: 25,
              decoration: BoxDecoration(
                color: Colors.grey[100], // ✅ grey 50 look
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.arrow_back_ios,
                size: 14,
                color: Colors.black,
              ),
            ),
          ),
        ),

        title: const Padding(
          padding: EdgeInsets.only(left: 8), // ✅ spacing from icon
          child: Text(
            'Order Details',
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.bold,
              color: Colors.black,
            ),
          ),
        ),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // User Info
            Text(
              "Order from: ${_order['userName'] ?? 'Anonymous'}",
              style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),

            // Pickup code (if exists)
            if (_order['pickupCode'] != null)
              Padding(
                padding: const EdgeInsets.only(bottom: 12),
                child: Text(
                  "Pickup Code: ${_order['pickupCode']}",
                  style: const TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                      color: Colors.deepPurple),
                ),
              ),

            // List of Items
            Expanded(
              child: ListView.builder(
                itemCount: itemsMap.length,
                itemBuilder: (context, index) {
                  final key = itemsMap.keys.elementAt(index);
                  final item = itemsMap[key];
                  final qty = item['qty'] ?? 1;
                  final name = item['name'] ?? 'Unnamed';
                  final price = item['price'] ?? 0;

                  return ListTile(
                    title: Text(name),
                    subtitle: Text("Quantity: $qty"),
                    trailing: Text("₦${(price * qty).toStringAsFixed(2)}"),
                  );
                },
              ),
            ),

            const Divider(thickness: 1.5),

            // Total & Status
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(
                  "Total: ₦${totalPrice.toStringAsFixed(2)}",
                  style: const TextStyle(
                      fontSize: 16, fontWeight: FontWeight.bold),
                ),
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  decoration: BoxDecoration(
                    color: Colors.deepPurple.withOpacity(0.1),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Text(
                    _order['status'] ?? 'New',
                    style: const TextStyle(
                        fontWeight: FontWeight.bold, color: Colors.deepPurple),
                  ),
                ),
              ],
            ),

            const SizedBox(height: 16),

            // Accept Order Button
            SizedBox(
              width: double.infinity,
              height: 50,
              child: ElevatedButton(
                onPressed: (_order['status'] == 'accepted' || _isUpdating)
                    ? null
                    : _acceptOrder,
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.deepPurple,
                ),
                child: _isUpdating
                    ? const CircularProgressIndicator(color: Colors.white)
                    : Text(
                        _order['status'] == 'accepted'
                            ? "Order Accepted"
                            : "Accept Order",
                        style: const TextStyle(fontSize: 18),
                      ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

class VendorDashboardPage extends StatefulWidget {
  final String vendorId;

  const VendorDashboardPage({super.key, required this.vendorId});

  @override
  State<VendorDashboardPage> createState() => _VendorDashboardPageState();
}

class _VendorDashboardPageState extends State<VendorDashboardPage> {
  String selectedTab = "pending"; // default = New Orders
  bool isFoodVendor = false; // ✅ Added: tracks if vendor is a food vendor

  // 🔹 Convert tab title to firestore status
  String _tabToStatus(String tab) {
    switch (tab) {
      case "New":
        return "pending";
      case "Pending":
        return "accepted";
      case "Completed":
        return "completed";
      default:
        return "pending";
    }
  }

  @override
  Widget build(BuildContext context) {
    final vendorId = widget.vendorId;

    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: SingleChildScrollView(
          padding: const EdgeInsets.all(16),
          child: Column(
            children: [
              /// 🔹 BACK BUTTON
              Row(
                children: [
                  GestureDetector(
                    onTap: () => Navigator.pop(context),
                    child: const Icon(Icons.arrow_back_ios),
                  ),
                  const Spacer(),
                ],
              ),

              const SizedBox(height: 16),

              /// 🔹 VENDOR CARD
              _vendorCard(vendorId),

              const SizedBox(height: 16),

              /// 🔹 MANAGE PRODUCTS
              _manageProducts(vendorId),

              const SizedBox(height: 16),

              /// 🔹 ORDERS HEADER
              Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  "Orders",
                  style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.bold,
                      color: Colors.grey[700]),
                ),
              ),

              const SizedBox(height: 10),

              /// 🔹 TABS WITH COUNTS
              Row(
                children: [
                  Expanded(child: _orderTab("New", vendorId)),
                  const SizedBox(width: 8),
                  Expanded(child: _orderTab("Pending", vendorId)),
                  const SizedBox(width: 8),
                  Expanded(child: _orderTab("Completed", vendorId)),
                ],
              ),

              const SizedBox(height: 20),

              /// 🔹 ORDERS LIST
              _ordersList(vendorId),
            ],
          ),
        ),
      ),
    );
  }

  // -------------------------------------------------------
  // 🔹 Vendor Card
  // -------------------------------------------------------

  Widget _vendorCard(String vendorId) {
    return Center(
      child: Container(
        height: 120,
        width: 350,
        padding: const EdgeInsets.all(12),
        decoration: _cardDecoration(),
        child: StreamBuilder<DocumentSnapshot>(
          stream: FirebaseFirestore.instance
              .collection('Vendors')
              .doc(vendorId)
              .snapshots(),
          builder: (context, snapshot) {
            if (!snapshot.hasData) {
              return const Center(child: CircularProgressIndicator());
            }

            final vendorData = snapshot.data!.data() as Map<String, dynamic>?;

            if (vendorData == null) {
              return const Center(child: Text("Vendor not found"));
            }

            // ✅ Set isFoodVendor based on Firebase category
            final category = vendorData['category'] ?? '';
            isFoodVendor = category == "Food Vendor";

            final imageUrl = vendorData['profileImageUrl'];

            return Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  children: [
                    CircleAvatar(
                      radius: 30,
                      backgroundImage:
                          imageUrl != null ? NetworkImage(imageUrl) : null,
                      child: imageUrl == null ? const Icon(Icons.person) : null,
                    ),
                    const SizedBox(width: 16),
                    Expanded(
                      child: Text(
                        vendorData['businessName'] ?? "Vendor",
                        style: const TextStyle(
                            fontSize: 18, fontWeight: FontWeight.bold),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                Text(
                  "Today's Sale: ₦${vendorData['todaysSale'] ?? 0}",
                  style: const TextStyle(fontWeight: FontWeight.bold),
                ),
              ],
            );
          },
        ),
      ),
    );
  }

  // -------------------------------------------------------
  // 🔹 Manage Products
  // -------------------------------------------------------

  Widget _manageProducts(String vendorId) {
    return GestureDetector(
      onTap: () {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => VendorProductsPage(
              vendorId: vendorId,
              isFoodVendor: isFoodVendor, // ✅ Pass isFoodVendor
            ),
          ),
        );
      },
      child: Container(
        height: 50,
        width: 350,
        padding: const EdgeInsets.symmetric(horizontal: 12),
        decoration: _cardDecoration(),
        child: const Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text("Manage Products",
                style: TextStyle(fontWeight: FontWeight.bold)),
            Icon(Icons.arrow_forward_ios),
          ],
        ),
      ),
    );
  }

  // -------------------------------------------------------
  // 🔹 ORDER TAB WITH LIVE COUNT
  // -------------------------------------------------------

  Widget _orderTab(String title, String vendorId) {
    final status = _tabToStatus(title);

    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection('orders')
          .where('vendorIds', arrayContains: vendorId)
          .where('status', isEqualTo: status)
          .snapshots(),
      builder: (context, snapshot) {
        int count = snapshot.data?.docs.length ?? 0;

        bool isSelected = selectedTab == status;

        return GestureDetector(
          onTap: () {
            setState(() {
              selectedTab = status;
            });
          },
          child: Container(
            height: 45,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: isSelected ? Colors.deepPurple : Colors.grey[200],
              borderRadius: BorderRadius.circular(12),
            ),
            child: Text(
              "$title ($count)",
              style: TextStyle(
                fontSize: 14,
                fontWeight: FontWeight.bold,
                color: isSelected ? Colors.white : Colors.black,
              ),
            ),
          ),
        );
      },
    );
  }

  // -------------------------------------------------------
  // 🔹 ORDERS LIST FILTERED BY TAB
  // -------------------------------------------------------

  Widget _ordersList(String vendorId) {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection('orders')
          .where('vendorIds', arrayContains: vendorId)
          .where('status', isEqualTo: selectedTab)
          .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData) {
          return const CircularProgressIndicator();
        }

        final orders = snapshot.data!.docs;

        if (orders.isEmpty) {
          return const Text("No orders found");
        }

        return ListView.builder(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          itemCount: orders.length,
          itemBuilder: (context, index) {
            final order = orders[index].data() as Map<String, dynamic>? ?? {};

            final userName = order['userName'] ?? "Anonymous";
            final itemsMap = order['items'] as Map<String, dynamic>? ?? {};

            final itemCount = itemsMap.length;

            double totalPrice = 0;
            itemsMap.forEach((key, value) {
              totalPrice += (value['price'] ?? 0) * (value['qty'] ?? 1);
            });

            final status = order['status'] ?? "";

            return GestureDetector(
              onTap: () {
                Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (_) => VendorOrderDetailsPage(
                      orderId: orders[index].id,
                      orderData: order,
                    ),
                  ),
                );
              },
              child: Container(
                height: 100,
                margin: const EdgeInsets.symmetric(vertical: 6),
                padding: const EdgeInsets.all(12),
                decoration: _cardDecoration(),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text("Order from: $userName",
                        style: const TextStyle(fontWeight: FontWeight.bold)),
                    Text("Items: $itemCount",
                        style: const TextStyle(color: Colors.grey)),
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Text("₦${totalPrice.toStringAsFixed(2)}",
                            style:
                                const TextStyle(fontWeight: FontWeight.bold)),
                        Text(status,
                            style: const TextStyle(
                                color: Colors.deepPurple,
                                fontWeight: FontWeight.bold)),
                      ],
                    )
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  // -------------------------------------------------------
  // 🔹 Shared Decoration
  // -------------------------------------------------------

  BoxDecoration _cardDecoration() {
    return BoxDecoration(
      color: Colors.white,
      borderRadius: BorderRadius.circular(16),
      boxShadow: [
        BoxShadow(
          color: Colors.black.withOpacity(0.05),
          blurRadius: 6,
          offset: const Offset(0, 3),
        ),
      ],
    );
  }
}

class AddProductPage extends StatefulWidget {
  final String vendorId;
  final bool isFoodVendor;

  const AddProductPage({
    required this.vendorId,
    required this.isFoodVendor,
    super.key,
  });

  @override
  State<AddProductPage> createState() => _AddProductPageState();
}

class _AddProductPageState extends State<AddProductPage> {
  File? _imageFile;
  Uint8List? _imageBytes;

  final ImagePicker picker = ImagePicker();

  final TextEditingController nameController = TextEditingController();
  final TextEditingController priceController = TextEditingController();
  final TextEditingController descController = TextEditingController();

  bool loading = false;

  /// Selected fallback image asset.
  String? fallbackAsset;

  /// Food fallback icons.
  final List<String> foodIcons = [
    "assets/images/bibimbap.png",
    "assets/images/coke.png",
    "assets/images/danwake.png",
    "assets/images/masa.png",
    "assets/images/party jollof rice.jpg",
    "assets/images/pizza.png",
    "assets/images/puff.png",
    "assets/images/shawarma.png",
  ];

  // ------------------------------------------------------------
  // FOOD FIELDS
  // ------------------------------------------------------------

  String? selectedCategory;

  final List<String> foodCategories = [
    'Drinks',
    'Spaghetti',
    'Rice',
    'Swallow',
    'Shawarma',
    'Pizza',
    'Small Chops',
    'Pastries',
  ];

  List<Map<String, dynamic>> addons = [];
  List<Map<String, dynamic>> sides = [];

  // ------------------------------------------------------------
  // PICK IMAGE
  // ------------------------------------------------------------

  Future<void> pickImage() async {
    try {
      final pickedFile = await picker.pickImage(
        source: ImageSource.gallery,
      );

      if (pickedFile == null) return;

      if (kIsWeb) {
        final bytes = await pickedFile.readAsBytes();

        if (!mounted) return;

        setState(() {
          _imageBytes = bytes;
          fallbackAsset = null;
        });
      } else {
        if (!mounted) return;

        setState(() {
          _imageFile = File(pickedFile.path);
          fallbackAsset = null;
        });
      }
    } catch (e) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text("Unable to select image: $e"),
        ),
      );
    }
  }

  // ------------------------------------------------------------
  // SELECT FALLBACK ICON
  // ------------------------------------------------------------

  void selectFallbackIcon() {
    showModalBottomSheet(
      context: context,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(25),
        ),
      ),
      builder: (_) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.all(15),
            child: GridView.builder(
              shrinkWrap: true,
              padding: const EdgeInsets.all(5),
              itemCount: foodIcons.length,
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 3,
                crossAxisSpacing: 10,
                mainAxisSpacing: 10,
              ),
              itemBuilder: (_, index) {
                final icon = foodIcons[index];

                return GestureDetector(
                  onTap: () {
                    setState(() {
                      fallbackAsset = icon;

                      // If fallback image is selected, remove
                      // uploaded image so only one is used.
                      _imageFile = null;
                      _imageBytes = null;
                    });

                    Navigator.pop(context);
                  },
                  child: Container(
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(12),
                      border: Border.all(
                        color: fallbackAsset == icon
                            ? Colors.deepPurple
                            : Colors.grey.shade300,
                        width: fallbackAsset == icon ? 2 : 1,
                      ),
                    ),
                    child: Padding(
                      padding: const EdgeInsets.all(8),
                      child: Image.asset(
                        icon,
                        fit: BoxFit.contain,
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        );
      },
    );
  }

  // ------------------------------------------------------------
  // ADD PRODUCT
  // ------------------------------------------------------------

  Future<void> addProduct() async {
    if (nameController.text.trim().isEmpty ||
        priceController.text.trim().isEmpty ||
        descController.text.trim().isEmpty ||
        (_imageFile == null && _imageBytes == null && fallbackAsset == null) ||
        (widget.isFoodVendor && selectedCategory == null)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            "Please fill all fields and add an image",
          ),
        ),
      );

      return;
    }

    final double? parsedPrice = double.tryParse(
      priceController.text.trim(),
    );

    if (parsedPrice == null || parsedPrice < 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text("Please enter a valid product price"),
        ),
      );

      return;
    }

    setState(() {
      loading = true;
    });

    try {
      // ----------------------------------------------------------
      // IMPORTANT:
      //
      // widget.vendorId is the Firebase Authentication UID.
      //
      // Vendors/{UID}
      //
      // contains:
      //
      // vendorId: "VN58321"
      //
      // This generated vendor number is what shopping pages use
      // to fetch the vendor's products.
      // ----------------------------------------------------------

      final String firebaseVendorId = widget.vendorId;

      final DocumentSnapshot<Map<String, dynamic>> vendorDoc =
          await FirebaseFirestore.instance
              .collection("Vendors")
              .doc(firebaseVendorId)
              .get();

      if (!vendorDoc.exists) {
        throw Exception(
          "Vendor profile not found. Please complete your vendor profile first.",
        );
      }

      final Map<String, dynamic>? vendorData = vendorDoc.data();

      final String? generatedVendorId =
          vendorData?["vendorId"]?.toString().trim();

      if (generatedVendorId == null || generatedVendorId.isEmpty) {
        throw Exception(
          "Vendor ID number not found in your vendor profile.",
        );
      }

      // ----------------------------------------------------------
      // IMAGE
      // ----------------------------------------------------------

      String imageUrl = "";

      // Upload image only when the vendor selected an actual image.
      if (_imageBytes != null || _imageFile != null) {
        final String fileName = "${DateTime.now().millisecondsSinceEpoch}.jpg";

        final Reference ref =
            FirebaseStorage.instance.ref().child("products/$fileName");

        if (kIsWeb) {
          if (_imageBytes == null) {
            throw Exception("Selected image data is unavailable.");
          }

          await ref.putData(_imageBytes!);
        } else {
          if (_imageFile == null) {
            throw Exception("Selected image file is unavailable.");
          }

          await ref.putFile(_imageFile!);
        }

        imageUrl = await ref.getDownloadURL();
      }

      // ----------------------------------------------------------
      // SAVE PRODUCT
      // ----------------------------------------------------------

      await FirebaseFirestore.instance.collection("products").add({
        // Firebase Auth UID.
        //
        // KEEPING THIS FIELD IS IMPORTANT because your existing
        // vendor-side product management can still use it.
        "vendorId": firebaseVendorId,

        // Generated public/vendor number.
        //
        // Example:
        // VN58321
        //
        // ShoppingSectionPage now uses this field.
        "vendorIdNo": generatedVendorId,

        "name": nameController.text.trim(),

        "price": parsedPrice,

        "description": descController.text.trim(),

        // Uploaded image URL.
        "image": imageUrl,

        // Local fallback image.
        "fallbackAsset": fallbackAsset ?? "assets/images/food.png",

        "createdAt": Timestamp.now(),

        // Food-specific information.
        "category": widget.isFoodVendor ? selectedCategory : null,

        "addons":
            widget.isFoodVendor ? List<Map<String, dynamic>>.from(addons) : [],

        "sides":
            widget.isFoodVendor ? List<Map<String, dynamic>>.from(sides) : [],
      });

      if (!mounted) return;

      setState(() {
        loading = false;
      });

      await showDialog(
        context: context,
        builder: (dialogContext) {
          return AlertDialog(
            title: const Text("Success"),
            content: const Text(
              "Product added successfully",
            ),
            actions: [
              TextButton(
                onPressed: () {
                  Navigator.pop(dialogContext);
                  Navigator.pop(context);
                },
                child: const Text("OK"),
              ),
            ],
          );
        },
      );
    } catch (e) {
      if (!mounted) return;

      setState(() {
        loading = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Error adding product: $e",
          ),
        ),
      );
    }
  }

  // ------------------------------------------------------------
  // BUILD
  // ------------------------------------------------------------

  @override
  Widget build(BuildContext context) {
    ImageProvider? preview;

    if (kIsWeb && _imageBytes != null) {
      preview = MemoryImage(_imageBytes!);
    } else if (!kIsWeb && _imageFile != null) {
      preview = FileImage(_imageFile!);
    } else if (fallbackAsset != null) {
      preview = AssetImage(fallbackAsset!);
    }

    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        centerTitle: false,
        leading: Padding(
          padding: const EdgeInsets.only(
            left: 10,
          ),
          child: GestureDetector(
            onTap: () {
              Navigator.pop(context);
            },
            child: Container(
              margin: const EdgeInsets.all(8),
              decoration: BoxDecoration(
                color: Colors.grey.shade100,
                shape: BoxShape.circle,
              ),
              child: const Center(
                child: Icon(
                  Icons.arrow_back_ios,
                  size: 14,
                  color: Colors.black,
                ),
              ),
            ),
          ),
        ),
        title: const Padding(
          padding: EdgeInsets.only(left: 8),
          child: Text(
            '',
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.bold,
              color: Colors.black,
            ),
          ),
        ),
      ),
      body: SingleChildScrollView(
        child: Center(
          child: Column(
            children: [
              const SizedBox(height: 30),

              // ------------------------------------------------
              // IMAGE PREVIEW
              // ------------------------------------------------

              CircleAvatar(
                radius: 55,
                backgroundColor: Colors.grey.shade300,
                backgroundImage: preview,
                child: preview == null
                    ? Icon(
                        Icons.add_photo_alternate,
                        size: 35,
                        color: Colors.grey[600],
                      )
                    : null,
              ),

              const SizedBox(height: 10),

              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  IconButton(
                    onPressed: loading ? null : pickImage,
                    icon: const Icon(Icons.image),
                  ),
                  IconButton(
                    onPressed: loading ? null : selectFallbackIcon,
                    icon: const Icon(Icons.fastfood),
                  ),
                ],
              ),

              const Text("Product Image"),

              const SizedBox(height: 20),

              // ------------------------------------------------
              // PRODUCT NAME
              // ------------------------------------------------

              buildInputField(
                nameController,
                "Product Name",
              ),

              labelText("Product Name"),

              // ------------------------------------------------
              // PRICE
              // ------------------------------------------------

              buildInputField(
                priceController,
                "Product Price",
                keyboardType: TextInputType.number,
              ),

              labelText("Price"),

              // ------------------------------------------------
              // DESCRIPTION
              // ------------------------------------------------

              buildInputField(
                descController,
                "Product Description",
                height: 100,
                maxLines: 4,
              ),

              labelText("Description"),

              // ------------------------------------------------
              // FOOD-SPECIFIC FIELDS
              // ------------------------------------------------

              if (widget.isFoodVendor) ...[
                const SizedBox(height: 20),
                Padding(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 20,
                  ),
                  child: DropdownButtonFormField<String>(
                    decoration: InputDecoration(
                      labelText: "Select Food Category",
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(8),
                      ),
                    ),
                    value: selectedCategory,
                    items: foodCategories
                        .map(
                          (cat) => DropdownMenuItem(
                            value: cat,
                            child: Text(cat),
                          ),
                        )
                        .toList(),
                    onChanged: loading
                        ? null
                        : (val) {
                            setState(() {
                              selectedCategory = val;
                            });
                          },
                  ),
                ),
                const SizedBox(height: 20),
                addonSideSection(
                  "Addons",
                  addons,
                ),
                const SizedBox(height: 10),
                addonSideSection(
                  "Sides",
                  sides,
                ),
              ],

              const SizedBox(height: 40),

              // ------------------------------------------------
              // ADD PRODUCT BUTTON
              // ------------------------------------------------

              SizedBox(
                width: 250,
                height: 45,
                child: ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.deepPurple,
                    disabledBackgroundColor: Colors.grey.shade400,
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  onPressed: loading ? null : addProduct,
                  child: loading
                      ? const SizedBox(
                          width: 20,
                          height: 20,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: Colors.white,
                          ),
                        )
                      : const Text(
                          "Add Product",
                          style: TextStyle(
                            color: Colors.white,
                          ),
                        ),
                ),
              ),

              const SizedBox(height: 30),
            ],
          ),
        ),
      ),
    );
  }

  // ------------------------------------------------------------
  // ADDONS / SIDES SECTION
  // ------------------------------------------------------------

  Widget addonSideSection(
    String title,
    List<Map<String, dynamic>> list,
  ) {
    final TextEditingController nameController = TextEditingController();

    final TextEditingController priceController = TextEditingController();

    return Padding(
      padding: const EdgeInsets.symmetric(
        horizontal: 20,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            title,
            style: const TextStyle(
              fontWeight: FontWeight.bold,
            ),
          ),

          const SizedBox(height: 5),

          ...list.asMap().entries.map(
            (entry) {
              final int idx = entry.key;
              final Map<String, dynamic> item = entry.value;

              return ListTile(
                contentPadding: EdgeInsets.zero,
                title: Text(
                  "${item['name']}",
                ),
                trailing: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      "₦${item['price']}",
                    ),

                    // EDIT
                    IconButton(
                      icon: const Icon(
                        Icons.edit,
                        color: Colors.orange,
                      ),
                      onPressed: loading
                          ? null
                          : () {
                              nameController.text = item['name'].toString();

                              priceController.text = item['price'].toString();

                              showDialog(
                                context: context,
                                builder: (_) => AlertDialog(
                                  title: Text(
                                    "Edit $title",
                                  ),
                                  content: Column(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      TextField(
                                        controller: nameController,
                                        decoration: InputDecoration(
                                          hintText: "$title Name",
                                        ),
                                      ),
                                      TextField(
                                        controller: priceController,
                                        keyboardType: TextInputType.number,
                                        decoration: InputDecoration(
                                          hintText: "$title Price",
                                        ),
                                      ),
                                    ],
                                  ),
                                  actions: [
                                    TextButton(
                                      onPressed: () => Navigator.pop(
                                        context,
                                      ),
                                      child: const Text(
                                        "Cancel",
                                      ),
                                    ),
                                    ElevatedButton(
                                      onPressed: () {
                                        if (nameController.text
                                                .trim()
                                                .isEmpty ||
                                            priceController.text
                                                .trim()
                                                .isEmpty) {
                                          return;
                                        }

                                        setState(() {
                                          list[idx] = {
                                            "name": nameController.text.trim(),
                                            "price": double.tryParse(
                                                  priceController.text.trim(),
                                                ) ??
                                                0,
                                          };
                                        });

                                        Navigator.pop(
                                          context,
                                        );
                                      },
                                      child: const Text(
                                        "Save",
                                      ),
                                    ),
                                  ],
                                ),
                              );
                            },
                    ),

                    // DELETE
                    IconButton(
                      onPressed: loading
                          ? null
                          : () {
                              setState(() {
                                list.removeAt(
                                  idx,
                                );
                              });
                            },
                      icon: const Icon(
                        Icons.delete,
                        color: Colors.red,
                      ),
                    ),
                  ],
                ),
              );
            },
          ),

          // ADD NEW ADDON/SIDE
          Row(
            children: [
              Expanded(
                child: TextField(
                  controller: nameController,
                  decoration: InputDecoration(
                    hintText: "$title Name",
                  ),
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: TextField(
                  controller: priceController,
                  keyboardType: TextInputType.number,
                  decoration: InputDecoration(
                    hintText: "$title Price",
                  ),
                ),
              ),
              IconButton(
                onPressed: loading
                    ? null
                    : () {
                        if (nameController.text.trim().isEmpty ||
                            priceController.text.trim().isEmpty) {
                          return;
                        }

                        setState(() {
                          list.add({
                            "name": nameController.text.trim(),
                            "price": double.tryParse(
                                  priceController.text.trim(),
                                ) ??
                                0,
                          });

                          nameController.clear();
                          priceController.clear();
                        });
                      },
                icon: const Icon(
                  Icons.add,
                  color: Colors.green,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  // ------------------------------------------------------------
  // INPUT FIELD
  // ------------------------------------------------------------

  Widget buildInputField(
    TextEditingController controller,
    String hint, {
    double height = 40,
    int maxLines = 1,
    TextInputType keyboardType = TextInputType.text,
  }) {
    return Container(
      width: 350,
      height: height,
      margin: const EdgeInsets.only(
        top: 10,
      ),
      padding: const EdgeInsets.symmetric(
        horizontal: 10,
      ),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(6),
        border: Border.all(
          color: Colors.grey.shade400,
        ),
      ),
      child: TextField(
        controller: controller,
        maxLines: maxLines,
        keyboardType: keyboardType,
        decoration: InputDecoration(
          hintText: hint,
          border: InputBorder.none,
        ),
      ),
    );
  }

  // ------------------------------------------------------------
  // LABEL
  // ------------------------------------------------------------

  Widget labelText(String text) {
    return Padding(
      padding: const EdgeInsets.only(
        top: 5,
        left: 10,
      ),
      child: Align(
        alignment: Alignment.centerLeft,
        child: Text(
          text,
          style: const TextStyle(
            fontSize: 13,
          ),
        ),
      ),
    );
  }

  // ------------------------------------------------------------
  // DISPOSE
  // ------------------------------------------------------------

  @override
  void dispose() {
    nameController.dispose();
    priceController.dispose();
    descController.dispose();

    super.dispose();
  }
}

class VendorProductsPage extends StatelessWidget {
