                    children: [
                      Icon(Icons.add, color: Colors.deepPurple),
                      SizedBox(width: 10),
                      Text("Add New Product",
                          style: TextStyle(
                              fontSize: 15, fontWeight: FontWeight.w600)),
                    ],
