class ManageVehiclesPage extends StatefulWidget {
  const ManageVehiclesPage({super.key});

  @override
  State<ManageVehiclesPage> createState() => _ManageVehiclesPageState();
}

class _ManageVehiclesPageState extends State<ManageVehiclesPage> {
  final FirebaseFirestore _firestore = FirebaseFirestore.instance;
  final FirebaseAuth _auth = FirebaseAuth.instance;
  final FirebaseStorage _storage = FirebaseStorage.instance;

  String? get providerId => _auth.currentUser?.uid;

  // ============================================================
  // TOP-LEVEL VEHICLES COLLECTION
  // ============================================================
  //
  // vehicles/{vehicleId}
  //
  // Each vehicle contains:
  //
  // providerId
  // vehicleId
  // vehicleImage
  // vehicleImagePath
  // driverName
  // driverCode
  // vehicleCapacity
  // boardedPassengers
  // status
  // active
  // departureTime
  // departureTimeMinutes
  // routeId
  // routeFrom
  // routeTo
  // routePrice
  //
  CollectionReference<Map<String, dynamic>> get _vehiclesRef {
    return _firestore.collection('vehicles');
  }

  // ============================================================
  // VEHICLE QUERY
  // ============================================================

  Query<Map<String, dynamic>> get _providerVehiclesQuery {
    final uid = providerId;

    return _vehiclesRef.where(
      'providerId',
      isEqualTo: uid,
    );
  }

  // ============================================================
  // ADD VEHICLE MODAL
  // ============================================================

  void _openAddVehicleModal() {
    final driverController = TextEditingController();
    final capacityController = TextEditingController();

    String? selectedRouteId;
    Map<String, dynamic>? selectedRoute;

    TimeOfDay? selectedDepartureTime;

    XFile? selectedImage;
    bool uploading = false;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(26),
        ),
      ),
      builder: (modalContext) {
        return StatefulBuilder(
          builder: (context, setModalState) {
            // ======================================================
            // PICK VEHICLE IMAGE
            // ======================================================

            Future<void> pickImage() async {
              if (uploading) return;

              try {
                final picker = ImagePicker();

                final image = await picker.pickImage(
                  source: ImageSource.gallery,
                  imageQuality: 80,
                  maxWidth: 1600,
                  maxHeight: 1600,
                );

                if (image != null) {
                  setModalState(() {
                    selectedImage = image;
                  });

                  debugPrint(
                    "VEHICLE IMAGE SELECTED: ${image.name}",
                  );
                }
              } catch (e, stackTrace) {
                debugPrint(
                  "PICK VEHICLE IMAGE ERROR: $e",
                );

                debugPrint(
                  "PICK VEHICLE IMAGE STACK TRACE:\n$stackTrace",
                );

                _showMessage(
                  "Unable to select image.",
                );
              }
            }

            // ======================================================
            // PICK DEPARTURE TIME
            // ======================================================

            Future<void> pickDepartureTime() async {
              if (uploading) return;

              final picked = await showTimePicker(
                context: context,
                initialTime: selectedDepartureTime ??
                    const TimeOfDay(
                      hour: 6,
                      minute: 0,
                    ),
                helpText: "SELECT DEPARTURE TIME",
                cancelText: "CANCEL",
                confirmText: "SELECT",
              );

              if (picked == null) {
                return;
              }

              final totalMinutes = picked.hour * 60 + picked.minute;

              const minimumMinutes = 6 * 60;
              const maximumMinutes = 18 * 60;

              if (totalMinutes < minimumMinutes ||
                  totalMinutes > maximumMinutes) {
                _showMessage(
                  "Departure time must be between 6:00 AM and 6:00 PM.",
                );
                return;
              }

              setModalState(() {
                selectedDepartureTime = picked;
              });
            }

            // ======================================================
            // SUBMIT VEHICLE
            // ======================================================

            Future<void> submitVehicle() async {
              final uid = providerId;

              // ----------------------------------------------------
              // AUTH CHECK
              // ----------------------------------------------------

              if (uid == null || uid.isEmpty) {
                _showMessage(
                  "You must be logged in to add a vehicle.",
                );
                return;
              }

              final driverName = driverController.text.trim();

              final capacityText = capacityController.text.trim();

              // ----------------------------------------------------
              // VALIDATE IMAGE
              // ----------------------------------------------------

              if (selectedImage == null) {
                _showMessage(
                  "Please select a vehicle image.",
                );
                return;
              }

              // ----------------------------------------------------
              // VALIDATE DRIVER
              // ----------------------------------------------------

              if (driverName.isEmpty) {
                _showMessage(
                  "Please enter the driver's name.",
                );
                return;
              }

              // ----------------------------------------------------
              // VALIDATE CAPACITY
              // ----------------------------------------------------

              if (capacityText.isEmpty) {
                _showMessage(
                  "Please enter the vehicle capacity.",
                );
                return;
              }

              final capacity = int.tryParse(capacityText);

              if (capacity == null || capacity <= 0) {
                _showMessage(
                  "Enter a valid vehicle capacity.",
                );
                return;
              }

              // ----------------------------------------------------
              // VALIDATE DEPARTURE TIME
              // ----------------------------------------------------

              if (selectedDepartureTime == null) {
                _showMessage(
                  "Please select a departure time.",
                );
                return;
              }

              final departureHour = selectedDepartureTime!.hour;

              final departureMinute = selectedDepartureTime!.minute;

              final departureTimeMinutes = departureHour * 60 + departureMinute;

              if (departureTimeMinutes < 360 || departureTimeMinutes > 1080) {
                _showMessage(
                  "Departure time must be between 6:00 AM and 6:00 PM.",
                );
                return;
              }

              final departureTimeLabel = selectedDepartureTime!.format(context);

              // ----------------------------------------------------
              // VALIDATE ROUTE
              // ----------------------------------------------------

              if (selectedRouteId == null || selectedRoute == null) {
                _showMessage(
                  "Please select a route.",
                );
                return;
              }

              setModalState(() {
                uploading = true;
              });

              String? uploadedImagePath;

              try {
                // ==================================================
                // CREATE TOP-LEVEL VEHICLE DOCUMENT
                // ==================================================
                //
                // vehicles/{vehicleId}
                //

                final vehicleRef = _vehiclesRef.doc();

                final vehicleId = vehicleRef.id;

                debugPrint(
                  "==============================================",
                );

                debugPrint(
                  "ADDING VEHICLE",
                );

                debugPrint(
                  "Provider ID: $uid",
                );

                debugPrint(
                  "Vehicle ID: $vehicleId",
                );

                debugPrint(
                  "Vehicle Path: ${vehicleRef.path}",
                );

                debugPrint(
                  "Departure Time: $departureTimeLabel",
                );

                debugPrint(
                  "Departure Minutes: $departureTimeMinutes",
                );

                debugPrint(
                  "==============================================",
                );

                // ==================================================
                // STORAGE PATH
                // ==================================================
                //
                // vehicles/{providerId}/{vehicleId}.jpg
                //

                final storageRef = _storage
                    .ref()
                    .child('vehicles')
                    .child(uid)
                    .child('$vehicleId.jpg');

                uploadedImagePath = storageRef.fullPath;

                debugPrint(
                  "Storage Path: $uploadedImagePath",
                );

                // ==================================================
                // READ IMAGE AS BYTES
                // ==================================================
                //
                // Works on:
                // - Flutter Web
                // - Android
                // - iOS
                //

                final imageBytes = await selectedImage!.readAsBytes();

                if (imageBytes.isEmpty) {
                  throw Exception(
                    "Selected image contains no data.",
                  );
                }

                debugPrint(
                  "IMAGE BYTES: ${imageBytes.length}",
                );

                // ==================================================
                // UPLOAD IMAGE
                // ==================================================

                final uploadMetadata = SettableMetadata(
                  contentType: 'image/jpeg',
                  customMetadata: {
                    'providerId': uid,
                    'vehicleId': vehicleId,
                  },
                );

                final uploadTask = await storageRef.putData(
                  imageBytes,
                  uploadMetadata,
                );

                debugPrint(
                  "IMAGE UPLOAD COMPLETE: "
                  "${uploadTask.state}",
                );

                // ==================================================
                // GET DOWNLOAD URL
                // ==================================================

                final imageUrl = await storageRef.getDownloadURL();

                debugPrint(
                  "IMAGE URL: $imageUrl",
                );

                // ==================================================
                // ROUTE DATA
                // ==================================================

                final routeData = Map<String, dynamic>.from(
                  selectedRoute!,
                );

                final routeFrom = routeData['from']?.toString() ?? '';

                final routeTo = routeData['to']?.toString() ?? '';

                final routePrice = routeData['price'] ?? 0;

                // ==================================================
                // DRIVER CODE
                // ==================================================

                final driverCode =
                    'DRV-${DateTime.now().millisecondsSinceEpoch}';

                // ==================================================
                // VEHICLE DATA
                // ==================================================

                final vehicleData = {
                  // ------------------------------------------------
                  // OWNERSHIP
                  // ------------------------------------------------

                  'providerId': uid,
                  'vehicleId': vehicleId,

                  // ------------------------------------------------
                  // IMAGE
                  // ------------------------------------------------

                  'vehicleImage': imageUrl,
                  'vehicleImagePath': uploadedImagePath,

                  // ------------------------------------------------
                  // DRIVER
                  // ------------------------------------------------

                  'driverName': driverName,
                  'driverCode': driverCode,

                  // ------------------------------------------------
                  // CAPACITY
                  // ------------------------------------------------

                  'vehicleCapacity': capacity,
                  'boardedPassengers': 0,

                  // ------------------------------------------------
                  // DEPARTURE TIME
                  // ------------------------------------------------
                  //
                  // departureTime:
                  // Human-readable value, e.g. "8:30 AM"
                  //
                  // departureTimeMinutes:
                  // Numeric value used for Firestore queries.
                  //
                  // 6:00 AM = 360
                  // 12:00 PM = 720
                  // 6:00 PM = 1080
                  //

                  'departureTime': departureTimeLabel,

                  'departureTimeMinutes': departureTimeMinutes,

                  // ------------------------------------------------
                  // STATUS
                  // ------------------------------------------------

                  'status': 'offline',
                  'active': false,

                  // ------------------------------------------------
                  // ROUTE
                  // ------------------------------------------------

                  'routeId': selectedRouteId,
                  'routeFrom': routeFrom,
                  'routeTo': routeTo,
                  'routePrice': routePrice,

                  // ------------------------------------------------
                  // TIMESTAMPS
                  // ------------------------------------------------

                  'createdAt': FieldValue.serverTimestamp(),

                  'updatedAt': FieldValue.serverTimestamp(),
                };

                debugPrint(
                  "==============================================",
                );

                debugPrint(
                  "CREATING FIRESTORE VEHICLE",
                );

                debugPrint(
                  "Path: ${vehicleRef.path}",
                );

                debugPrint(
                  "Provider: $uid",
                );

                debugPrint(
                  "Route: $selectedRouteId",
                );

                debugPrint(
                  "Departure: $departureTimeLabel",
                );

                debugPrint(
                  "Departure Minutes: "
                  "$departureTimeMinutes",
                );

                debugPrint(
                  "==============================================",
                );

                // ==================================================
                // SAVE VEHICLE
                // ==================================================

                await vehicleRef.set(
                  vehicleData,
                );

                debugPrint(
                  "==============================================",
                );

                debugPrint(
                  "VEHICLE CREATED SUCCESSFULLY",
                );

                debugPrint(
                  "Firestore Path: ${vehicleRef.path}",
                );

                debugPrint(
                  "==============================================",
                );

                if (modalContext.mounted) {
                  Navigator.pop(
                    modalContext,
                  );
                }

                _showMessage(
                  "Vehicle added successfully.",
                  success: true,
                );
              } catch (e, stackTrace) {
                debugPrint(
                  "==============================================",
                );

                debugPrint(
                  "ADD VEHICLE ERROR",
                );

                debugPrint(
                  "$e",
                );

                debugPrint(
                  "STACK TRACE",
                );

                debugPrint(
                  "$stackTrace",
                );

                debugPrint(
                  "==============================================",
                );

                // ==================================================
                // CLEAN UP UPLOADED IMAGE
                // ==================================================

                if (uploadedImagePath != null) {
                  try {
                    await _storage.ref(uploadedImagePath!).delete();

                    debugPrint(
                      "Uploaded image cleaned up.",
                    );
                  } catch (cleanupError) {
                    debugPrint(
                      "IMAGE CLEANUP ERROR: "
                      "$cleanupError",
                    );
                  }
                }

                if (context.mounted) {
                  setModalState(() {
                    uploading = false;
                  });
                }

                // ==================================================
                // FRIENDLY ERROR
                // ==================================================

                final error = e.toString().toLowerCase();

                String message = "Unable to add vehicle.";

                if (error.contains(
                  'permission-denied',
                )) {
                  message =
                      "Permission denied. Check your Firestore rules for the vehicles collection.";
                } else if (error.contains(
                  'unauthorized',
                )) {
                  message =
                      "Image upload was not authorized. Check your Firebase Storage rules.";
                } else if (error.contains(
                  'object-not-found',
                )) {
                  message =
                      "Firebase Storage could not find the upload location.";
                } else if (error.contains(
                  'network',
                )) {
                  message =
                      "Network error. Please check your internet connection.";
                } else if (error.contains(
                  'unauthenticated',
                )) {
                  message =
                      "Your login session has expired. Please sign in again.";
                } else if (error.contains(
                  'invalid-argument',
                )) {
                  message = "Some vehicle information is invalid.";
                }

                _showMessage(
                  message,
                );
              }
            }

            // ======================================================
            // MODAL UI
            // ======================================================

            return SafeArea(
              child: Padding(
                padding: EdgeInsets.only(
                  left: 20,
                  right: 20,
                  top: 14,
                  bottom: MediaQuery.of(context).viewInsets.bottom + 20,
                ),
                child: SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // ============================================
                      // HANDLE
                      // ============================================

                      Center(
                        child: Container(
                          width: 45,
                          height: 5,
                          decoration: BoxDecoration(
                            color: Colors.grey.shade300,
                            borderRadius: BorderRadius.circular(
                              20,
                            ),
                          ),
                        ),
                      ),

                      const SizedBox(height: 22),

                      // ============================================
                      // HEADER
                      // ============================================

                      Row(
                        children: [
                          Container(
                            width: 42,
                            height: 42,
                            decoration: BoxDecoration(
                              color: Colors.grey.shade100,
                              shape: BoxShape.circle,
                            ),
                            child: const Icon(
                              Icons.directions_bus_rounded,
                              size: 21,
                            ),
                          ),
                          const SizedBox(width: 12),
                          const Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  "Add New Vehicle",
                                  style: TextStyle(
                                    fontSize: 17,
                                    fontWeight: FontWeight.bold,
                                  ),
                                ),
                                SizedBox(height: 3),
                                Text(
                                  "Add a vehicle to one of your routes.",
                                  style: TextStyle(
                                    fontSize: 12,
                                    color: Colors.grey,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),

                      const SizedBox(height: 25),

                      // ============================================
                      // VEHICLE IMAGE
                      // ============================================

                      _fieldLabel(
                        "Vehicle Image",
                      ),

                      const SizedBox(height: 9),

                      GestureDetector(
                        onTap: uploading ? null : pickImage,
                        child: Container(
                          height: 150,
                          width: double.infinity,
                          decoration: BoxDecoration(
                            color: Colors.grey.shade50,
                            borderRadius: BorderRadius.circular(
                              16,
                            ),
                            border: Border.all(
                              color: Colors.grey.shade300,
                            ),
                          ),
                          child: selectedImage == null
                              ? Column(
                                  mainAxisAlignment: MainAxisAlignment.center,
                                  children: [
                                    Container(
                                      width: 48,
                                      height: 48,
                                      decoration: BoxDecoration(
                                        color: Colors.grey.shade100,
                                        shape: BoxShape.circle,
                                      ),
                                      child: const Icon(
                                        Icons.add_a_photo_outlined,
                                        size: 22,
                                      ),
                                    ),
                                    const SizedBox(
                                      height: 10,
                                    ),
                                    const Text(
                                      "Tap to select vehicle image",
                                      style: TextStyle(
                                        fontSize: 12,
                                        fontWeight: FontWeight.w600,
                                      ),
                                    ),
                                    const SizedBox(
                                      height: 4,
                                    ),
                                    Text(
                                      "JPG or PNG",
                                      style: TextStyle(
                                        fontSize: 10,
                                        color: Colors.grey.shade500,
                                      ),
                                    ),
                                  ],
                                )
                              : ClipRRect(
                                  borderRadius: BorderRadius.circular(
                                    15,
                                  ),
                                  child: FutureBuilder<List<int>>(
                                    future: selectedImage!.readAsBytes(),
                                    builder: (
                                      context,
                                      snapshot,
                                    ) {
                                      if (!snapshot.hasData) {
                                        return const Center(
                                          child: CircularProgressIndicator(
                                            strokeWidth: 2,
                                            color: Colors.black,
                                          ),
                                        );
                                      }

                                      return Image.memory(
                                        Uint8List.fromList(
                                          snapshot.data!,
                                        ),
                                        width: double.infinity,
                                        height: 150,
                                        fit: BoxFit.cover,
                                      );
                                    },
                                  ),
                                ),
                        ),
                      ),

                      const SizedBox(height: 20),

                      // ============================================
                      // DRIVER NAME
                      // ============================================

                      _fieldLabel(
                        "Driver Name",
                      ),

                      const SizedBox(height: 8),

                      TextField(
                        controller: driverController,
                        textCapitalization: TextCapitalization.words,
                        enabled: !uploading,
                        decoration: _inputDecoration(
                          hint: "Enter driver's name",
                          icon: Icons.person_outline,
                        ),
                      ),

                      const SizedBox(height: 18),

                      // ============================================
                      // CAPACITY
                      // ============================================

                      _fieldLabel(
                        "Total Capacity",
                      ),

                      const SizedBox(height: 8),

                      TextField(
                        controller: capacityController,
                        enabled: !uploading,
                        keyboardType: TextInputType.number,
                        decoration: _inputDecoration(
                          hint: "e.g. 18",
                          icon: Icons.event_seat_outlined,
                        ),
                      ),

                      const SizedBox(height: 18),

                      // ============================================
                      // DEPARTURE TIME
                      // ============================================

                      _fieldLabel(
                        "Departure Time",
                      ),

                      const SizedBox(height: 8),

                      GestureDetector(
                        onTap: uploading ? null : pickDepartureTime,
                        child: Container(
                          width: double.infinity,
                          padding: const EdgeInsets.symmetric(
                            horizontal: 14,
                            vertical: 10,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.white,
                            borderRadius: BorderRadius.circular(
                              14,
                            ),
                            border: Border.all(
                              color: selectedDepartureTime != null
                                  ? Colors.black
                                  : Colors.grey.shade300,
                            ),
                          ),
                          child: Row(
                            children: [
                              Container(
                                width: 36,
                                height: 36,
                                decoration: BoxDecoration(
                                  color: Colors.grey.shade100,
                                  shape: BoxShape.circle,
                                ),
                                child: const Icon(
                                  Icons.schedule_rounded,
                                  size: 18,
                                ),
                              ),
                              const SizedBox(width: 10),
                              Expanded(
                                child: selectedDepartureTime == null
                                    ? Column(
                                        crossAxisAlignment:
                                            CrossAxisAlignment.start,
                                        children: [
                                          Text(
                                            "Select departure time",
                                            style: TextStyle(
                                              color: Colors.grey.shade500,
                                              fontSize: 13,
                                            ),
                                          ),
                                          const SizedBox(
                                            height: 3,
                                          ),
                                          Text(
                                            "Available from 6:00 AM to 6:00 PM",
                                            style: TextStyle(
                                              color: Colors.grey.shade400,
                                              fontSize: 10,
                                            ),
                                          ),
                                        ],
                                      )
                                    : Column(
                                        crossAxisAlignment:
                                            CrossAxisAlignment.start,
                                        children: [
                                          Text(
                                            selectedDepartureTime!.format(
                                              context,
                                            ),
                                            style: const TextStyle(
                                              fontSize: 14,
                                              fontWeight: FontWeight.w600,
                                            ),
                                          ),
                                          const SizedBox(
                                            height: 3,
                                          ),
                                          Text(
                                            "Scheduled departure",
                                            style: TextStyle(
                                              color: Colors.grey.shade500,
                                              fontSize: 10,
                                            ),
                                          ),
                                        ],
                                      ),
                              ),
                              const Icon(
                                Icons.keyboard_arrow_down_rounded,
                              ),
                            ],
                          ),
                        ),
                      ),

                      const SizedBox(height: 18),

                      // ============================================
                      // ROUTE
                      // ============================================

                      _fieldLabel(
                        "Assign Route",
                      ),

                      const SizedBox(height: 8),

                      StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                        stream: _firestore
                            .collection(
                              'routes',
                            )
                            .where(
                              'providerId',
                              isEqualTo: providerId,
                            )
                            .snapshots(),
                        builder: (
                          context,
                          snapshot,
                        ) {
                          if (snapshot.connectionState ==
                              ConnectionState.waiting) {
                            return Container(
                              height: 56,
                              decoration: BoxDecoration(
                                color: Colors.grey.shade50,
                                borderRadius: BorderRadius.circular(
                                  14,
                                ),
                                border: Border.all(
                                  color: Colors.grey.shade200,
                                ),
                              ),
                              child: const Center(
                                child: SizedBox(
                                  width: 18,
                                  height: 18,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                    color: Colors.black,
                                  ),
                                ),
                              ),
                            );
                          }

                          if (snapshot.hasError) {
                            debugPrint(
                              "ROUTES ERROR: "
                              "${snapshot.error}",
                            );

                            return _errorBox(
                              "Unable to load your routes.",
                            );
                          }

                          final routes = snapshot.data?.docs ?? [];

                          if (routes.isEmpty) {
                            return _errorBox(
                              "No routes found. Add a route first.",
                            );
                          }

                          return GestureDetector(
                            onTap: uploading
                                ? null
                                : () async {
                                    final result = await _showRoutePicker(
                                      context,
                                      routes,
                                      selectedRouteId,
                                    );

                                    if (result != null) {
                                      setModalState(
                                        () {
                                          selectedRouteId = result['id'];

                                          selectedRoute = result['data'];
                                        },
                                      );
                                    }
                                  },
                            child: Container(
                              width: double.infinity,
                              padding: const EdgeInsets.symmetric(
                                horizontal: 14,
