  // ============================================================
  // VEHICLES
  // ============================================================

  Widget _buildVehicles() {
    if (providerId == null) {
      return const Center(
        child: Text(
          "Please sign in to manage vehicles.",
        ),
      );
    }

    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: _providerVehiclesQuery.snapshots(),
      builder: (
        context,
        snapshot,
      ) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return Column(
            children: List.generate(
              3,
              (_) => _vehicleShimmer(),
            ),
          );
        }

        if (snapshot.hasError) {
          debugPrint(
            "LOAD VEHICLES ERROR: "
            "${snapshot.error}",
          );

          return _emptyMessage(
            icon: Icons.error_outline,
            title: "Unable to load vehicles",
            subtitle: "Please check your Firestore rules.",
          );
        }

        final vehicles = snapshot.data?.docs ?? [];

        if (vehicles.isEmpty) {
          return _emptyMessage(
            icon: Icons.directions_bus_outlined,
            title: "No vehicles yet",
            subtitle: "Add your first vehicle to start managing your fleet.",
          );
        }

        return Column(
          children: vehicles.map((doc) {
            final data = doc.data();

            return _vehicleCard(
              docId: doc.id,
              data: data,
            );
          }).toList(),
        );
      },
    );
  }

  // ============================================================
  // TOGGLE VEHICLE STATUS
  // ============================================================

  Future<void> _toggleVehicleStatus({
    required String docId,
    required String currentStatus,
  }) async {
    final uid = providerId;

    if (uid == null || uid.isEmpty) {
      _showMessage(
        "You must be logged in.",
      );
      return;
    }

    final newStatus =
        currentStatus.toLowerCase() == 'online' ? 'offline' : 'online';

    try {
      final vehicleRef = _vehiclesRef.doc(docId);

      // ----------------------------------------------------------
      // SECURITY CHECK
      // ----------------------------------------------------------

      final snapshot = await vehicleRef.get();

      if (!snapshot.exists) {
        _showMessage(
          "Vehicle no longer exists.",
        );
        return;
      }

      final vehicleData = snapshot.data() ?? {};

      final ownerId = vehicleData['providerId']?.toString();

      if (ownerId != uid) {
        _showMessage(
          "You cannot change this vehicle.",
        );
        return;
      }

      // ----------------------------------------------------------
      // UPDATE STATUS
      // ----------------------------------------------------------

      await vehicleRef.update({
        'status': newStatus,
        'active': newStatus == 'online',
        'updatedAt': FieldValue.serverTimestamp(),
      });

      _showMessage(
        newStatus == 'online'
            ? "Vehicle is now online."
            : "Vehicle is now offline.",
        success: true,
      );
    } catch (e, stackTrace) {
      debugPrint(
        "TOGGLE VEHICLE STATUS ERROR: $e",
      );

      debugPrint(
        "STACK TRACE:\n$stackTrace",
      );

      final error = e.toString().toLowerCase();

      if (error.contains(
        'permission-denied',
      )) {
        _showMessage(
          "You do not have permission to change this vehicle.",
        );
      } else {
        _showMessage(
          "Unable to update vehicle status.",
        );
      }
    }
  }

