  // ============================================================
  // DELETE VEHICLE
  // ============================================================

  Future<void> _confirmDeleteVehicle(
    String docId,
  ) async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (context) {
        return AlertDialog(
          title: const Text(
            "Remove vehicle?",
            style: TextStyle(
              fontWeight: FontWeight.bold,
            ),
          ),
          content: const Text(
            "This vehicle will be removed from your fleet.",
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(
                context,
                false,
              ),
              child: const Text(
                "Cancel",
              ),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.red,
              ),
              onPressed: () => Navigator.pop(
                context,
                true,
              ),
              child: const Text(
                "Remove",
                style: TextStyle(
                  color: Colors.white,
                ),
              ),
            ),
          ],
        );
      },
    );

    if (confirmed != true) {
      return;
    }

    final uid = providerId;

    if (uid == null || uid.isEmpty) {
      _showMessage(
        "You must be logged in.",
      );
      return;
    }

    try {
      // ==========================================================
      // TOP-LEVEL VEHICLE DOCUMENT
      // ==========================================================

      final vehicleRef = _vehiclesRef.doc(docId);

      final snapshot = await vehicleRef.get();

      if (!snapshot.exists) {
        _showMessage(
          "Vehicle no longer exists.",
        );
        return;
      }

      final vehicleData = snapshot.data() ?? {};

      // ==========================================================
      // SECURITY CHECK
      // ==========================================================

      final ownerId = vehicleData['providerId']?.toString();

      if (ownerId != uid) {
        _showMessage(
          "You cannot remove this vehicle.",
        );
        return;
      }

      // ==========================================================
      // DELETE FIRESTORE DOCUMENT
      // ==========================================================

      await vehicleRef.delete();

      debugPrint(
        "VEHICLE DELETED: ${vehicleRef.path}",
      );

      // ==========================================================
      // DELETE IMAGE
      // ==========================================================

      final imagePath = vehicleData['vehicleImagePath'];

      if (imagePath != null && imagePath.toString().isNotEmpty) {
        try {
          await _storage
              .ref(
                imagePath.toString(),
              )
              .delete();

          debugPrint(
            "Vehicle image deleted.",
          );
        } catch (e) {
          debugPrint(
            "DELETE VEHICLE IMAGE ERROR: $e",
          );
        }
      }

      _showMessage(
        "Vehicle removed.",
        success: true,
      );
    } catch (e, stackTrace) {
      debugPrint(
        "DELETE VEHICLE ERROR: $e",
      );

      debugPrint(
        "DELETE VEHICLE STACK TRACE:\n$stackTrace",
      );

      final error = e.toString().toLowerCase();

      if (error.contains(
        'permission-denied',
      )) {
        _showMessage(
          "Permission denied. Check your vehicles Firestore rules.",
        );
      } else {
        _showMessage(
          "Unable to remove vehicle.",
        );
      }
    }
  }

