  // ============================================================
  // PROVIDER IMAGE
  // ============================================================

  Widget _providerImage(
    dynamic imageUrl, {
    double radius = 28,
  }) {
    final url = imageUrl?.toString() ?? '';

    if (url.isEmpty) {
      return CircleAvatar(
        radius: radius,
        backgroundColor: Colors.grey.shade100,
        child: Icon(
          Icons.business,
          size: radius,
          color: Colors.grey,
        ),
      );
    }

    return CircleAvatar(
      radius: radius,
      backgroundColor: Colors.grey.shade100,
      backgroundImage: NetworkImage(url),
      onBackgroundImageError: (_, __) {},
      child: null,
    );
  }

  // ============================================================
  // RECENT TICKET CARD
  // ============================================================

  Widget _recentTicketCard(
    Map<String, dynamic> data,
  ) {
    final from = data['from']?.toString() ?? 'Unknown';

    final to = data['to']?.toString() ?? 'Unknown';

    final status = data['status']?.toString() ?? 'pending';

    final ticketId = data['ticketId']?.toString() ?? '';

    final createdAt = data['createdAt'] as Timestamp?;

    final formattedDate = _formatRecentDate(
      createdAt,
    );

    final statusLower = status.toLowerCase();

    final isValid = statusLower == 'valid' ||
        statusLower == 'confirmed' ||
        statusLower == 'active';

    final statusColor = isValid
        ? Colors.green
        : statusLower == 'cancelled' || statusLower == 'expired'
            ? Colors.red
            : Colors.orange;

    return GestureDetector(
      onTap: () {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => TransportTicketPage(
              ticketData: data,
            ),
          ),
        );
      },
      child: Container(
        height: 82,
        margin: const EdgeInsets.only(
          bottom: 10,
        ),
        padding: const EdgeInsets.symmetric(
          horizontal: 12,
          vertical: 10,
        ),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(
            14,
          ),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.04),
              blurRadius: 8,
              offset: const Offset(0, 3),
            ),
          ],
        ),
        child: Row(
          children: [
            // ================================================
            // ICON
            // ================================================

            Container(
              width: 43,
              height: 43,
              decoration: const BoxDecoration(
                color: Colors.black,
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.directions_bus_rounded,
                color: Colors.white,
                size: 19,
              ),
            ),

            const SizedBox(width: 10),

            // ================================================
            // TICKET ID + ROUTE
            // ================================================

            Expanded(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    ticketId.isEmpty ? 'Ticket' : ticketId,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      fontSize: 12.5,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 5),
                  Text(
                    "$from → $to",
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      fontSize: 10.5,
                      color: Colors.grey.shade600,
                    ),
                  ),
                ],
              ),
            ),

            const SizedBox(width: 10),

            // ================================================
            // STATUS + DATE
            // ================================================

            Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 7,
                    vertical: 3,
                  ),
                  decoration: BoxDecoration(
                    color: statusColor.withOpacity(
                      .10,
                    ),
                    borderRadius: BorderRadius.circular(
                      7,
                    ),
                  ),
                  child: Text(
                    status.toUpperCase(),
                    style: TextStyle(
                      fontSize: 8,
                      fontWeight: FontWeight.bold,
                      color: statusColor,
                    ),
                  ),
                ),
                const SizedBox(height: 5),
                Text(
                  formattedDate,
                  style: TextStyle(
                    fontSize: 9.5,
                    color: Colors.grey.shade500,
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  // ============================================================
  // FORMAT RECENT DATE
  // ============================================================

  String _formatRecentDate(
    Timestamp? timestamp,
  ) {
    if (timestamp == null) {
      return '';
    }

    final date = timestamp.toDate();

    return DateFormat(
      'dd-MM-yy h:mma',
    ).format(date).toLowerCase();
  }

  // ============================================================
  // PROVIDER MODAL
  // ============================================================
  //
  // Flow:
  //
  // Provider
  //    ↓
  // Routes
  //    ↓
  // Vehicle modal
  //    ↓
  // Booking
  //

  Future<void> _openProviderModal(
    DocumentSnapshot<Map<String, dynamic>> provider,
  ) async {
    final providerId = provider.id;

    final providerData = provider.data() ?? {};

    final routesSnap = await FirebaseFirestore.instance
        .collection('routes')
        .where(
          'providerId',
          isEqualTo: providerId,
        )
        .get();

    final routes = routesSnap.docs;

    if (!mounted) return;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(
            25,
          ),
        ),
      ),
      builder: (_) => DraggableScrollableSheet(
        expand: false,
        initialChildSize: 0.7,
        minChildSize: 0.5,
        maxChildSize: 0.92,
        builder: (
          context,
          controller,
        ) {
          return Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _modalHandle(),

                const SizedBox(height: 20),

                // ==========================================
                // PROVIDER
                // ==========================================

                _providerHeader(
                  providerData,
                ),

                const SizedBox(height: 20),

                const Text(
                  "Routes",
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                    fontSize: 14,
                  ),
                ),

                const SizedBox(height: 12),

                Expanded(
                  child: routes.isEmpty
                      ? Center(
                          child: Text(
                            "No routes available",
                            style: TextStyle(
                              fontSize: 12,
                              color: Colors.grey.shade600,
                            ),
                          ),
                        )
                      : ListView.builder(
                          controller: controller,
                          itemCount: routes.length,
                          itemBuilder: (
                            context,
                            index,
                          ) {
                            final route = routes[index];

                            return _routeCard(
                              route,
                              onTap: () {
                                Navigator.pop(
                                  context,
                                );

                                _openVehicleModal(
                                  providerData: providerData,
                                  providerId: providerId,
                                  route: route,
                                );
                              },
                            );
                          },
                        ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

