  // ============================================================
  // MASS TRANSIT MODAL
  // ============================================================

  void _openMassTransitModal() {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(
            20,
          ),
        ),
      ),
      builder: (_) => StatefulBuilder(
        builder: (
          context,
          modalSetState,
        ) {
          return Padding(
            padding: EdgeInsets.only(
              left: 16,
              right: 16,
              top: 20,
              bottom: MediaQuery.of(context).viewInsets.bottom + 20,
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                _modalHandle(),
                const SizedBox(height: 20),
                const Text(
                  "Select Route",
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                    fontSize: 16,
                  ),
                ),
                const SizedBox(height: 20),
                _stateSelector(
                  label: "From :",
                  value: fromState,
                  onTap: () async {
                    final result = await _openStatePicker(
                      states,
                      selectedState: fromState,
                    );

                    if (result != null) {
                      modalSetState(
                        () {
                          fromState = result;

                          toState = null;
                        },
                      );
                    }
                  },
                ),
                const SizedBox(height: 12),
                _stateSelector(
                  label: "To :",
                  value: toState,
                  onTap: () async {
                    final filtered = states
                        .where(
                          (s) => s != fromState,
                        )
                        .toList();

                    final result = await _openStatePicker(
                      filtered,
                      selectedState: toState,
                    );

                    if (result != null) {
                      modalSetState(
                        () {
                          toState = result;
                        },
                      );
                    }
                  },
                ),
                const SizedBox(height: 20),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.black,
                      padding: const EdgeInsets.all(
                        14,
                      ),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(
                          12,
                        ),
                      ),
                    ),
                    onPressed: fromState == null || toState == null
                        ? null
                        : () {
                            Navigator.pop(
                              context,
                            );

                            _openResultsModal();
                          },
                    child: const Text(
                      "Search Providers",
                      style: TextStyle(
                        color: Colors.white,
                      ),
                    ),
                  ),
                ),
                const SizedBox(height: 10),
              ],
            ),
          );
        },
      ),
    );
  }

  // ============================================================
  // MASS TRANSIT RESULTS
  // ============================================================
  //
  // Search:
  //
  // From → To
  //     ↓
  // Providers
  //     ↓
  // Click provider
  //     ↓
  // Vehicles
  //

  void _openResultsModal() {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(25),
        ),
      ),
      builder: (_) => DraggableScrollableSheet(
        expand: false,
        initialChildSize: 0.65,
        minChildSize: 0.4,
        maxChildSize: 0.92,
        builder: (
          context,
          scrollController,
        ) {
          return Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _modalHandle(),
                const SizedBox(height: 14),
                Text(
                  "$fromState → $toState",
                  style: const TextStyle(
                    fontWeight: FontWeight.bold,
                    fontSize: 18,
                  ),
                ),
                const SizedBox(height: 5),
                Text(
                  "Available Providers",
                  style: TextStyle(
                    fontSize: 11,
                    color: Colors.grey.shade600,
                  ),
                ),
                const SizedBox(height: 14),
                Expanded(
                  child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                    stream: FirebaseFirestore.instance
                        .collection('routes')
                        .where(
                          'from',
                          isEqualTo: fromState,
                        )
                        .where(
                          'to',
                          isEqualTo: toState,
                        )
                        .snapshots(),
                    builder: (
                      context,
                      snapshot,
                    ) {
                      if (snapshot.connectionState == ConnectionState.waiting) {
                        return _providerResultShimmer();
                      }

                      if (snapshot.hasError) {
                        return Center(
                          child: Text(
                            "Unable to find providers.",
                            style: TextStyle(
                              fontSize: 12,
                              color: Colors.grey.shade600,
                            ),
                          ),
                        );
                      }

                      final routes = snapshot.data?.docs ?? [];

                      if (routes.isEmpty) {
                        return const Center(
                          child: Text(
                            "No providers available for this route.",
                            style: TextStyle(
                              fontSize: 12,
                            ),
                          ),
                        );
                      }

                      // --------------------------------------------------
                      // GROUP ROUTES BY PROVIDER
                      // --------------------------------------------------

                      final Map<String,
                              List<QueryDocumentSnapshot<Map<String, dynamic>>>>
                          providerRoutes = {};

                      for (final route in routes) {
                        final data = route.data();

                        final providerId = data['providerId']?.toString();

                        if (providerId == null || providerId.isEmpty) {
                          continue;
                        }

                        providerRoutes.putIfAbsent(
                          providerId,
                          () => [],
                        );

                        providerRoutes[providerId]!.add(route);
                      }

                      final providerIds = providerRoutes.keys.toList();

                      if (providerIds.isEmpty) {
                        return const Center(
                          child: Text(
                            "No providers available.",
                          ),
                        );
                      }

                      // --------------------------------------------------
                      // FIRESTORE WHERE-IN LIMIT
                      // --------------------------------------------------
                      //
                      // Firestore has a limit on the number of values
                      // allowed in a whereIn query.
                      //
                      // We only need the first 30 providers here.
                      // --------------------------------------------------

                      final idsToFetch = providerIds.take(30).toList();

                      return FutureBuilder<QuerySnapshot<Map<String, dynamic>>>(
                        future: FirebaseFirestore.instance
                            .collection('providers')
                            .where(
                              FieldPath.documentId,
                              whereIn: idsToFetch,
                            )
                            .get(),
                        builder: (
                          context,
                          providerSnapshot,
                        ) {
                          if (providerSnapshot.connectionState ==
                              ConnectionState.waiting) {
                            return _providerResultShimmer();
                          }

                          if (providerSnapshot.hasError) {
                            return Center(
                              child: Text(
                                "Unable to load provider information.",
                                style: TextStyle(
                                  fontSize: 12,
                                  color: Colors.grey.shade600,
                                ),
                              ),
                            );
                          }

                          final providerDocs =
                              providerSnapshot.data?.docs ?? [];

                          if (providerDocs.isEmpty) {
                            return const Center(
                              child: Text(
                                "No providers available.",
                              ),
                            );
                          }

                          final Map<String,
                                  QueryDocumentSnapshot<Map<String, dynamic>>>
                              providerMap = {
                            for (final doc in providerDocs) doc.id: doc,
                          };

                          final availableProviders = providerIds
                              .where(
                                (id) => providerMap.containsKey(id),
                              )
                              .toList();

                          if (availableProviders.isEmpty) {
                            return const Center(
                              child: Text(
                                "No providers available.",
                              ),
                            );
                          }

                          return ListView.builder(
                            controller: scrollController,
                            itemCount: availableProviders.length,
                            itemBuilder: (
                              context,
                              index,
                            ) {
                              final providerId = availableProviders[index];

                              final provider = providerMap[providerId]!;

                              final providerData = provider.data();

                              // Get the first matching route for
                              // this provider.
                              final providerRoute =
                                  providerRoutes[providerId]!.first;

                              final routeData = providerRoute.data();

                              return _searchProviderCard(
                                provider: providerData,
                                route: routeData,
                                onTap: () {
                                  Navigator.pop(context);

                                  // Open the vehicle modal after
                                  // the provider modal closes.
                                  WidgetsBinding.instance
                                      .addPostFrameCallback((_) {
                                    if (!mounted) return;

                                    _openVehicleModal(
                                      providerData: providerData,
                                      providerId: providerId,
                                      route: providerRoute,
                                    );
                                  });
                                },
                              );
                            },
                          );
                        },
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  // ============================================================
  // SEARCH PROVIDER CARD
  // ============================================================

