  // ============================================================
  // VEHICLES MODAL
  // ============================================================
  //
  // Query:
  //
  // providerId == selected provider
  // routeId == selected route
  // status == online
  //
  // If no vehicles:
  //
  // "No vehicle online right now"
  // "Try other providers"
  //

  Future<void> _openVehicleModal({
    required Map<String, dynamic> providerData,
    required String providerId,
    required DocumentSnapshot<Map<String, dynamic>> route,
  }) async {
    final routeData = route.data() ?? {};

    final routeId = route.id;

    final from = routeData['from']?.toString() ?? '';

    final to = routeData['to']?.toString() ?? '';

    final price = routeData['price'] ?? 0;

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(
            25,
          ),
        ),
      ),
      builder: (_) => DraggableScrollableSheet(
        expand: false,
        initialChildSize: 0.65,
        minChildSize: 0.4,
        maxChildSize: 0.92,
        builder: (
          context,
          controller,
        ) {
          return Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _modalHandle(),

                const SizedBox(height: 16),

                // ==============================================
                // PROVIDER + ROUTE HEADER
                // ==============================================

                Row(
                  children: [
                    _providerImage(
                      providerData['imageUrl'],
                      radius: 25,
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            providerData['name']?.toString() ?? 'Provider',
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              fontWeight: FontWeight.bold,
                              fontSize: 15,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Text(
                            "$from → $to",
                            style: TextStyle(
                              fontSize: 11,
                              color: Colors.grey.shade600,
                            ),
                          ),
                        ],
                      ),
                    ),
                    Text(
                      "₦$price",
                      style: const TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.bold,
                        color: Colors.green,
                      ),
                    ),
                  ],
                ),

                const SizedBox(height: 20),

                const Text(
                  "Available Vehicles",
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                    fontSize: 14,
                  ),
                ),

                const SizedBox(height: 5),

                Text(
                  "Select a vehicle to continue booking.",
                  style: TextStyle(
                    fontSize: 11,
                    color: Colors.grey.shade600,
                  ),
                ),

                const SizedBox(height: 14),

                Expanded(
                  child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
                    stream: FirebaseFirestore.instance
                        .collection('vehicles')
                        .where(
                          'providerId',
                          isEqualTo: providerId,
                        )
                        .where(
                          'routeId',
                          isEqualTo: routeId,
                        )
                        .where(
                          'status',
                          isEqualTo: 'online',
                        )
                        .snapshots(),
                    builder: (
                      context,
                      snapshot,
                    ) {
                      if (snapshot.connectionState == ConnectionState.waiting) {
                        return ListView.builder(
                          controller: controller,
                          itemCount: 3,
                          itemBuilder: (
                            _,
                            __,
                          ) =>
                              _vehicleCardShimmer(),
                        );
                      }

                      if (snapshot.hasError) {
                        debugPrint(
                          "VEHICLES ERROR: "
                          "${snapshot.error}",
                        );

                        return _vehicleEmptyState(
                          title: "Unable to load vehicles",
                          subtitle: "Please try again.",
                          showTryOther: true,
                        );
                      }

                      final vehicles = snapshot.data?.docs ?? [];

                      if (vehicles.isEmpty) {
                        return _vehicleEmptyState(
                          title: "No vehicle online right now",
                          subtitle: "Try other providers for this route.",
                          showTryOther: true,
                        );
                      }

                      // Sort by departure time.
                      final sortedVehicles = [
                        ...vehicles,
                      ];

                      sortedVehicles.sort(
                        (
                          a,
                          b,
                        ) {
                          final aMinutes = _departureMinutes(
                            a.data(),
                          );

                          final bMinutes = _departureMinutes(
                            b.data(),
                          );

                          return aMinutes.compareTo(
                            bMinutes,
                          );
                        },
                      );

                      return ListView.builder(
                        controller: controller,
                        itemCount: sortedVehicles.length,
                        itemBuilder: (
                          context,
                          index,
                        ) {
                          final vehicle = sortedVehicles[index];

                          return _vehicleCard(
                            vehicle: vehicle,
                            onTap: () {
                              Navigator.pop(
                                context,
                              );

                              _openBooking(
                                route: route,
                                providerData: providerData,
                                vehicleData: vehicle.data(),
                                vehicleId: vehicle.id,
                              );
                            },
                          );
                        },
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

