  // ============================================================
  // MODAL HANDLE
  // ============================================================

  Widget _modalHandle() {
    return Center(
      child: Container(
        width: 50,
        height: 5,
        decoration: BoxDecoration(
          color: Colors.grey.shade300,
          borderRadius: BorderRadius.circular(
            20,
          ),
        ),
      ),
    );
  }

  // ============================================================
  // INTEGER HELPER
  // ============================================================

  int _intValue(
    dynamic value,
  ) {
    if (value is int) {
      return value;
    }

    if (value is double) {
      return value.toInt();
    }

    return int.tryParse(
          value?.toString() ?? '',
        ) ??
        0;
  }

  // ============================================================
  // DEPARTURE MINUTES
  // ============================================================

  int _departureMinutes(
    Map<String, dynamic> data,
  ) {
    final stored = data['departureTimeMinutes'];

    if (stored != null) {
      return _intValue(stored);
    }

    // Fallback for older vehicle
    // documents which may only have
    // departureTime.

    final label = data['departureTime']?.toString() ?? '';

    if (label.isEmpty) {
      return 9999;
    }

    try {
      final parsed = DateFormat(
        'h:mm a',
      ).parse(
        label.toUpperCase(),
      );

      return parsed.hour * 60 + parsed.minute;
    } catch (_) {
      try {
        final parsed = DateFormat(
          'h a',
        ).parse(
          label.toUpperCase(),
        );

        return parsed.hour * 60 + parsed.minute;
      } catch (_) {
        return 9999;
      }
    }
  }

  // ============================================================
  // DEPARTURE REMAINING
  // ============================================================

  String _departureRemainingText(
    int departureMinutes,
  ) {
    if (departureMinutes == 9999) {
      return "Departure time unavailable";
    }

    final now = TimeOfDay.now();

    final nowMinutes = now.hour * 60 + now.minute;

    final difference = departureMinutes - nowMinutes;

    if (difference <= 0) {
      return "Departing soon";
    }

    final hours = difference ~/ 60;

    final minutes = difference % 60;

    if (hours > 0) {
      if (minutes > 0) {
        return "$hours hr $minutes min";
      }

      return "$hours hr away";
    }

    return "$minutes min away";
  }
}

class TransportTicketsPage extends StatefulWidget {
  const TransportTicketsPage({super.key});

  @override
  State<TransportTicketsPage> createState() => _TransportTicketsPageState();
}

class _TransportTicketsPageState extends State<TransportTicketsPage> {
  final user = FirebaseAuth.instance.currentUser;

  @override
  Widget build(BuildContext context) {
    if (user == null) {
      return const Scaffold(
        body: Center(child: Text("Please log in to view your tickets.")),
      );
    }

    return Scaffold(
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        scrolledUnderElevation: 0,
        iconTheme: const IconThemeData(color: Colors.black),
        title: const Text(
          'Transport Tickets',
          style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold),
        ),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: StreamBuilder(
          stream: FirebaseFirestore.instance
              .collection("transport_tickets")
              .where("userId", isEqualTo: user!.uid)
              //.orderBy("createdAt", descending: true)
              .snapshots(),
          builder: (context, AsyncSnapshot snapshot) {
            if (!snapshot.hasData) {
              return const Center(child: CircularProgressIndicator());
            }

            final tickets = snapshot.data.docs;

            if (tickets.isEmpty) {
              return const Center(child: Text("No tickets booked yet."));
            }

            return ListView.builder(
              itemCount: tickets.length,
              itemBuilder: (context, index) {
                final ticket = tickets[index];
                final departure = ticket['departure'] != null
                    ? (ticket['departure'] as Timestamp).toDate()
                    : null;

                return Container(
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(14),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(0.05),
                        blurRadius: 6,
                        offset: const Offset(0, 3),
                      )
                    ],
                    border: Border.all(color: Colors.grey.shade200),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      /// PROVIDER
                      Row(
                        children: [
                          const SizedBox(width: 12),
                          Expanded(
                            child: Text(
                              ticket['providerName'] ?? "Provider",
                              style: const TextStyle(
                                  fontWeight: FontWeight.bold, fontSize: 16),
                            ),
                          ),
                          Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 10, vertical: 6),
                            decoration: BoxDecoration(
                              color: Colors.green.shade50,
                              borderRadius: BorderRadius.circular(12),
                            ),
                            child: Text(
                              "₦${ticket['price']}",
                              style: const TextStyle(
                                  fontWeight: FontWeight.bold,
                                  color: Colors.green),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),

                      /// ROUTE
                      Text(
                        "${ticket['from']} → ${ticket['to']}",
                        style: TextStyle(
                            fontWeight: FontWeight.w500,
                            color: Colors.grey.shade700),
                      ),

                      if (departure != null)
                        Text(
                          "Departure: ${departure.toLocal()}",
                          style: const TextStyle(color: Colors.black87),
                        ),
                      const SizedBox(height: 6),

                      /// TICKET COUNT
                      Text("Tickets: ${ticket['ticketCount']}"),

                      /// STATUS
                      const SizedBox(height: 6),
                      Container(
                        padding: const EdgeInsets.symmetric(
                            horizontal: 8, vertical: 4),
                        decoration: BoxDecoration(
                          color: ticket['status'] == "valid"
                              ? Colors.green.shade100
                              : Colors.red.shade100,
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: Text(
                          ticket['status'] ?? "Unknown",
                          style: TextStyle(
                              color: ticket['status'] == "valid"
                                  ? Colors.green
                                  : Colors.red,
                              fontWeight: FontWeight.bold),
                        ),
                      ),
                    ],
                  ),
                );
              },
            );
          },
        ),
      ),
    );
  }
}

class TicketBookingPage extends StatefulWidget {
  final dynamic routeData;
  final dynamic providerData;
  final dynamic vehicleData;

  const TicketBookingPage({
    required this.routeData,
    required this.providerData,
    required this.vehicleData,
    super.key,
  });

  @override
  _TicketBookingPageState createState() => _TicketBookingPageState();
}

class _TicketBookingPageState extends State<TicketBookingPage> {
  int ticketCount = 1;
  bool loading = false;

  double get totalPrice =>
      ticketCount * double.parse(widget.routeData['price'].toString());

  // ============================================================
  // VEHICLE HELPERS
  // ============================================================

  String get vehicleName {
    final data = widget.vehicleData;

    if (data == null) {
      return "Vehicle";
    }

    final name =
        data['driverName'] ?? data['name'] ?? data['vehicle'] ?? "Vehicle";

    return name.toString();
  }

  String get vehicleDepartureTime {
    final data = widget.vehicleData;

    if (data == null) {
      return "Not specified";
    }

    final time = data['departureTime'];

    if (time != null && time.toString().isNotEmpty) {
      return time.toString();
    }

    return "Not specified";
  }

  String get vehicleImageUrl {
    final data = widget.vehicleData;

    if (data == null) {
      return "";
    }

    final image =
        data['vehicleImage'] ?? data['imageUrl'] ?? data['image'] ?? "";

    return image.toString();
  }

  // ============================================================
  // PAYMENT
  // ============================================================

  Future<void> _payWithPaystack() async {
    final user = FirebaseAuth.instance.currentUser;

    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text("Please sign in to continue."),
        ),
      );
      return;
    }

    setState(() {
      loading = true;
    });

    try {
      const String paystackSecretKey =
          'sk_test_661490bf9dc0914e122c2c043ab3aaf3a307d658';

      final int amount = (totalPrice * 100).toInt();

      final String reference =
          "transport_${DateTime.now().millisecondsSinceEpoch}";

      final response = await http.post(
        Uri.parse(
          'https://api.paystack.co/transaction/initialize',
        ),
        headers: {
          'Authorization': 'Bearer $paystackSecretKey',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'email': user.email,
          'amount': amount,
          'reference': reference,
        }),
      );

      if (response.statusCode != 200) {
        throw "Unable to initialize payment";
      }

      final data = jsonDecode(response.body);

      final checkoutUrl = data['data']['authorization_url'];

      await launchUrl(
        Uri.parse(checkoutUrl),
        mode: LaunchMode.externalApplication,
      );

      // ========================================================
      // SAVE TICKET
      // ========================================================

      final ticketDoc = await _saveTicket(reference);

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text("Payment successful"),
        ),
      );

      Navigator.pushAndRemoveUntil(
        context,
        MaterialPageRoute(
          builder: (_) => TransportTicketPage(
            ticketData: ticketDoc,
          ),
        ),
        (route) => false,
      );
    } catch (e) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Payment failed: $e",
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() {
          loading = false;
        });
      }
    }
  }

  // ============================================================
  // SAVE TICKET
  // ============================================================

  Future<DocumentSnapshot> _saveTicket(
    String reference,
  ) async {
    final user = FirebaseAuth.instance.currentUser;

    if (user == null) {
      throw Exception("User not logged in.");
    }

    // ------------------------------------------------------------
    // Convert either DocumentSnapshot or Map into a normal Map
    // ------------------------------------------------------------

    Map<String, dynamic> getData(dynamic value) {
      if (value is DocumentSnapshot) {
        final data = value.data();

        if (data is Map<String, dynamic>) {
          return data;
        }

        if (data is Map) {
          return Map<String, dynamic>.from(data);
        }

        return {};
      }

      if (value is Map) {
        return Map<String, dynamic>.from(value);
      }

      return {};
    }

    // ------------------------------------------------------------
    // Safely get a document ID.
    //
    // Supports:
    // DocumentSnapshot.id
    // Map["id"]
    // Map["documentId"]
    // Map["vehicleId"]
    // ------------------------------------------------------------

    String getId(
      dynamic value, {
      String? fallbackField,
    }) {
      if (value is DocumentSnapshot) {
        return value.id;
      }

      if (value is Map) {
        final map = Map<String, dynamic>.from(value);

        final id = map["id"];

        if (id != null && id.toString().trim().isNotEmpty) {
          return id.toString();
        }

        final documentId = map["documentId"];

        if (documentId != null && documentId.toString().trim().isNotEmpty) {
          return documentId.toString();
        }

        if (fallbackField != null) {
          final fallback = map[fallbackField];

          if (fallback != null && fallback.toString().trim().isNotEmpty) {
            return fallback.toString();
          }
        }
      }

      return "";
    }

    // ------------------------------------------------------------
    // Extract data from the three objects
    // ------------------------------------------------------------

    final provider = getData(widget.providerData);
    final route = getData(widget.routeData);
    final vehicle = getData(widget.vehicleData);

    // ------------------------------------------------------------
    // IDs
    // ------------------------------------------------------------

    final providerId = getId(widget.providerData);

    final routeId = getId(widget.routeData);

    final vehicleId = getId(
      widget.vehicleData,
      fallbackField: "vehicleId",
    );

    // ------------------------------------------------------------
    // Vehicle provider ID
    //
    // This is important because vehicles now live in their own
    // collection and contain providerId.
    // ------------------------------------------------------------

    final vehicleProviderId = vehicle["providerId"]?.toString() ?? "";

    // ------------------------------------------------------------
    // Vehicle fields
    // ------------------------------------------------------------

    final vehicleNameValue = vehicle["driverName"] ??
        vehicle["name"] ??
        vehicle["vehicle"] ??
        vehicle["vehicleName"] ??
        "Vehicle";

    final vehicleImageValue = vehicle["vehicleImage"] ??
        vehicle["imageUrl"] ??
        vehicle["image"] ??
        "";

    final departureTimeValue = vehicle["departureTime"] ?? "";

    // ------------------------------------------------------------
    // Create ticket
    // ------------------------------------------------------------

    final docRef =
        await FirebaseFirestore.instance.collection("transport_tickets").add({
      "ticketId": "TR${Random().nextInt(90000) + 10000}",

      // PROVIDER
      "providerId": providerId,
      "providerName": provider["name"]?.toString() ?? "",
      "providerLocation": provider["location"]?.toString() ?? "",
      "providerImage": provider["imageUrl"]?.toString() ?? "",

      // ROUTE
      "from": route["from"]?.toString() ?? "",
      "to": route["to"]?.toString() ?? "",
      "routeId": routeId,

      // VEHICLE
      "vehicleId": vehicleId,
      "vehicleName": vehicleNameValue.toString(),
      "vehicleImage": vehicleImageValue.toString(),
      "departureTime": departureTimeValue.toString(),
      "vehicleProviderId": vehicleProviderId,

      // BOOKING
      "ticketCount": ticketCount,
      "price": totalPrice,

      // STATUS
      "status": "valid",

      // USER
      "userId": user.uid,

      // PAYMENT
      "paymentReference": reference,

      // TIMESTAMP
      "createdAt": FieldValue.serverTimestamp(),
    });

    // ------------------------------------------------------------
    // Return the newly created ticket document
    // ------------------------------------------------------------

    return await docRef.get();
  }

