class TicketClipper extends CustomClipper<Path> {
  @override
  Path getClip(Size size) {
    const double cornerRadius = 20;
    const double cutoutRadius = 12;

    // Put the cutouts around the middle of the ticket.
    final double cutoutY = size.height * 0.55;

    final Path path = Path();

    // ================= TOP =================
    path.moveTo(cornerRadius, 0);

    path.lineTo(size.width - cornerRadius, 0);

    // Top-right rounded corner
    path.quadraticBezierTo(
      size.width,
      0,
      size.width,
      cornerRadius,
    );

    // ================= RIGHT SIDE =================

    path.lineTo(
      size.width,
      cutoutY - cutoutRadius,
    );

    // Right semicircle cutout
    path.arcToPoint(
      Offset(
        size.width,
        cutoutY + cutoutRadius,
      ),
      radius: const Radius.circular(cutoutRadius),
      clockwise: false,
    );

    // Continue down
    path.lineTo(
      size.width,
      size.height - cornerRadius,
    );

    // Bottom-right rounded corner
    path.quadraticBezierTo(
      size.width,
      size.height,
      size.width - cornerRadius,
      size.height,
    );

    // ================= BOTTOM =================

    path.lineTo(cornerRadius, size.height);

    // Bottom-left rounded corner
    path.quadraticBezierTo(
      0,
      size.height,
      0,
      size.height - cornerRadius,
    );

    // ================= LEFT SIDE =================

    path.lineTo(
      0,
      cutoutY + cutoutRadius,
    );

    // Left semicircle cutout
    path.arcToPoint(
      Offset(
        0,
        cutoutY - cutoutRadius,
      ),
      radius: const Radius.circular(cutoutRadius),
      clockwise: false,
    );

    // Continue up
    path.lineTo(0, cornerRadius);

    // Top-left rounded corner
    path.quadraticBezierTo(
      0,
      0,
      cornerRadius,
      0,
    );

    path.close();

    return path;
  }

  @override
  bool shouldReclip(covariant CustomClipper<Path> oldClipper) {
    return false;
  }
}

class TransportTicketPage extends StatefulWidget {
  final dynamic ticketData;

  const TransportTicketPage({
    super.key,
    required this.ticketData,
  });

  @override
  State<TransportTicketPage> createState() => _TransportTicketPageState();
}

class _TransportTicketPageState extends State<TransportTicketPage> {
  final GlobalKey _ticketKey = GlobalKey();

  bool loadingCancel = false;

  // Keep the current status locally instead of trying to modify
  // a Firestore DocumentSnapshot.
  String? localStatus;

  @override
  void initState() {
    super.initState();

    final ticket = widget.ticketData;

    try {
      localStatus = ticket["status"]?.toString();
    } catch (_) {
      localStatus = null;
    }
  }

  // ------------------------------------------------------------
  // SAFE VALUE HELPERS
  // ------------------------------------------------------------

  String _stringValue(dynamic value) {
    if (value == null) return "";
    return value.toString();
  }

  String _ticketId() {
    try {
      return _stringValue(widget.ticketData["ticketId"]);
    } catch (_) {
      return "";
    }
  }

  String _status() {
    if (localStatus != null && localStatus!.isNotEmpty) {
      return localStatus!;
    }

    try {
      return _stringValue(widget.ticketData["status"]);
    } catch (_) {
      return "";
    }
  }

  String _createdDate() {
    try {
      final createdAt = widget.ticketData["createdAt"];

      if (createdAt == null) {
        return "";
      }

      if (createdAt is Timestamp) {
        return createdAt.toDate().toString().split(".").first;
      }

      return createdAt.toString();
    } catch (_) {
      return "";
    }
  }

  // ------------------------------------------------------------
  // CANCEL TICKET
  // ------------------------------------------------------------

  Future<void> _cancelTicket() async {
    if (loadingCancel) return;

    try {
      setState(() {
        loadingCancel = true;
      });

      final ticket = widget.ticketData;

      String ticketDocumentId = "";

      // DocumentSnapshot
      if (ticket is DocumentSnapshot) {
        ticketDocumentId = ticket.id;
      }

      // If ticketData was passed as a map containing its Firestore ID
      if (ticketDocumentId.isEmpty && ticket is Map) {
        ticketDocumentId =
            ticket["id"]?.toString() ?? ticket["documentId"]?.toString() ?? "";
      }

      if (ticketDocumentId.isEmpty) {
        throw Exception("Ticket document ID is missing.");
      }

      await FirebaseFirestore.instance
          .collection("transport_tickets")
          .doc(ticketDocumentId)
          .update({
        "status": "cancelled",
      });

      if (!mounted) return;

      setState(() {
        localStatus = "cancelled";
      });

      await showDialog(
        context: context,
        builder: (_) => const AlertDialog(
          title: Text("Success"),
          content: Text("Ticket cancelled successfully"),
        ),
      );
    } catch (e) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            "Unable to cancel ticket: $e",
          ),
        ),
      );
    } finally {
      if (mounted) {
        setState(() {
          loadingCancel = false;
        });
      }
    }
  }

  // ------------------------------------------------------------
  // TICKET DETAIL ROW
  // ------------------------------------------------------------

  Widget _ticketDetailRow(
    String title,
    String value, {
    Color valueColor = Colors.white,
  }) {
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Expanded(
          flex: 2,
          child: Text(
            title,
            style: const TextStyle(
              color: Colors.white70,
              fontSize: 13,
              fontWeight: FontWeight.w500,
            ),
          ),
        ),
        Expanded(
          flex: 3,
          child: Text(
            value,
            textAlign: TextAlign.right,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(
              color: valueColor,
              fontSize: 14,
              fontWeight: FontWeight.w600,
            ),
          ),
        ),
      ],
    );
  }

  // ------------------------------------------------------------
  // VEHICLE IMAGE
  // ------------------------------------------------------------

  Widget _vehicleImage(String imageUrl) {
    if (imageUrl.trim().isEmpty) {
      return Container(
        width: 58,
        height: 58,
        decoration: BoxDecoration(
          color: Colors.white.withOpacity(0.08),
          borderRadius: BorderRadius.circular(30),
        ),
        child: const Icon(
          Icons.directions_bus,
          color: Colors.white70,
          size: 28,
        ),
      );
    }

    return ClipRRect(
      borderRadius: BorderRadius.circular(12),
      child: Image.network(
        imageUrl,
        width: 58,
        height: 58,
        fit: BoxFit.cover,
        errorBuilder: (_, __, ___) {
          return Container(
            width: 58,
            height: 58,
            decoration: BoxDecoration(
              color: Colors.white.withOpacity(0.08),
              borderRadius: BorderRadius.circular(12),
            ),
            child: const Icon(
              Icons.directions_bus,
              color: Colors.white70,
              size: 28,
            ),
          );
        },
      ),
    );
  }

  // ------------------------------------------------------------
  // PDF
  // ------------------------------------------------------------

  Future<void> _downloadTicketPdf() async {
    try {
      final pdf = pw.Document();

      final ticket = widget.ticketData;

      final ticketId = _stringValue(ticket["ticketId"]);

      final status = _stringValue(ticket["status"]);

      final providerName = _stringValue(ticket["providerName"]);

      final from = _stringValue(ticket["from"]);

      final to = _stringValue(ticket["to"]);

      final price = _stringValue(ticket["price"]);

      final vehicleName = _stringValue(ticket["vehicleName"]);

      final departureTime = _stringValue(ticket["departureTime"]);

      final createdAt = ticket["createdAt"];

      String date = "";

      if (createdAt is Timestamp) {
        date = createdAt.toDate().toString().split(".").first;
      }

      pdf.addPage(
        pw.Page(
          pageFormat: PdfPageFormat.a5,
          margin: const pw.EdgeInsets.all(24),
          build: (context) {
            return pw.Column(
              crossAxisAlignment: pw.CrossAxisAlignment.start,
              children: [
                pw.Center(
                  child: pw.Text(
                    "ZONE TRANSPORT",
                    style: pw.TextStyle(
                      fontSize: 22,
                      fontWeight: pw.FontWeight.bold,
                    ),
                  ),
                ),

                pw.SizedBox(height: 6),

                pw.Center(
                  child: pw.Text(
                    "Transport Ticket",
                    style: const pw.TextStyle(
                      fontSize: 14,
                    ),
                  ),
                ),

                pw.Divider(height: 30),

                _pdfRow(
                  "Ticket ID",
                  ticketId,
                ),

                _pdfRow(
                  "Status",
                  status,
                ),

                _pdfRow(
                  "Provider",
                  providerName,
                ),

                _pdfRow(
                  "From",
                  from,
                ),

                _pdfRow(
                  "To",
                  to,
                ),

                // NEW VEHICLE DETAILS
                if (vehicleName.isNotEmpty)
                  _pdfRow(
                    "Vehicle",
                    vehicleName,
                  ),

                if (departureTime.isNotEmpty)
                  _pdfRow(
                    "Departure",
                    departureTime,
                  ),

                _pdfRow(
                  "Price",
                  "₦$price",
                ),

                if (date.isNotEmpty)
                  _pdfRow(
                    "Date",
                    date,
                  ),

                pw.SizedBox(height: 30),

                pw.Center(
                  child: pw.BarcodeWidget(
                    barcode: pw.Barcode.qrCode(),
                    data: ticketId,
                    width: 120,
                    height: 120,
                  ),
                ),

                pw.SizedBox(height: 25),

                pw.Center(
                  child: pw.Text(
                    "Please present this ticket before boarding.",
                    style: const pw.TextStyle(
                      fontSize: 11,
                    ),
                  ),
                ),
              ],
            );
          },
        ),
      );

      await Printing.sharePdf(
        bytes: await pdf.save(),
        filename: "$ticketId.pdf",
      );
    } catch (e) {
      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            e.toString(),
          ),
        ),
      );
    }
  }

  pw.Widget _pdfRow(
    String title,
    String value,
  ) {
    return pw.Padding(
      padding: const pw.EdgeInsets.only(
        bottom: 10,
      ),
      child: pw.Row(
        children: [
          pw.Expanded(
            flex: 2,
            child: pw.Text(
              title,
              style: pw.TextStyle(
                color: PdfColors.grey700,
              ),
            ),
          ),
          pw.Expanded(
            flex: 3,
            child: pw.Text(
              value,
              style: pw.TextStyle(
                fontWeight: pw.FontWeight.bold,
              ),
            ),
          ),
        ],
      ),
    );
  }

