  // ─────────────────────────────────────────────
  //  DRIVERS MODAL
  // ─────────────────────────────────────────────
  void _openDriversModal(String institutionName) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      builder: (context) {
        return DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.75,
          minChildSize: 0.5,
          maxChildSize: 0.95,
          builder: (context, scrollController) {
            return Column(
              children: [
                const SizedBox(height: 12),

                Container(
                  width: 40,
                  height: 4,
                  decoration: BoxDecoration(
                    color: Colors.grey[300],
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),

                const SizedBox(height: 16),

                /// HEADER
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 20),
                  child: Row(
                    children: [
                      GestureDetector(
                        onTap: () {
                          Navigator.pop(context);
                          _openInstitutionsModal();
                        },
                        child: const Icon(CupertinoIcons.back, size: 22),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          institutionName,
                          style: const TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.bold,
                          ),
                          overflow: TextOverflow.ellipsis,
                        ),
                      ),
                    ],
                  ),
                ),

                const SizedBox(height: 6),

                Padding(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 20, vertical: 4),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text(
                      "Available Drivers",
                      style: TextStyle(fontSize: 12, color: Colors.grey[500]),
                    ),
                  ),
                ),

                const SizedBox(height: 8),

                /// 🔥 STREAM BUILDER (FIXED)
                Expanded(
                  child: StreamBuilder<QuerySnapshot>(
                    stream: FirebaseFirestore.instance
                        .collection('shuttle_drivers')
                        .where('activeInstitution', isEqualTo: institutionName)
                        .where('status', isEqualTo: 'online')
                        .snapshots(),
                    builder: (context, snapshot) {
                      if (snapshot.connectionState == ConnectionState.waiting) {
                        return _driverShimmer();
                      }

                      if (snapshot.hasError) {
                        debugPrint("========== FIRESTORE ERROR ==========");
                        debugPrint(snapshot.error.toString());

                        if (snapshot.error is FirebaseException) {
                          final e = snapshot.error as FirebaseException;
                          debugPrint("Code: ${e.code}");
                          debugPrint("Message: ${e.message}");
                        }

                        return SingleChildScrollView(
                          padding: const EdgeInsets.all(20),
                          child: SelectableText(
                            snapshot.error.toString(),
                            style: const TextStyle(
                              color: Colors.red,
                              fontSize: 12,
                            ),
                          ),
                        );
                      }

                      if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                        return Center(
                          child: Text(
                            "No active shuttles",
                            style: TextStyle(color: Colors.grey[400]),
                          ),
                        );
                      }

                      final drivers = snapshot.data!.docs;

                      return ListView.builder(
                        controller: scrollController,
                        padding: const EdgeInsets.symmetric(horizontal: 20),
                        itemCount: drivers.length,
                        itemBuilder: (context, index) {
                          final doc = drivers[index];
                          final data = doc.data() as Map<String, dynamic>;

                          /// 🔥 IMPORTANT: attach doc ID
                          data['id'] = doc.id;

                          final vehicleImage = data['vehicleImage'] ?? '';
                          final vehicleName = data['vehicleName'] ?? '';
                          final driverCode = data['driverCode'] ?? '';
                          final vehicleCapacity = data['vehicleCapacity'] ?? 0;
                          final boardedPassengers =
                              data['boardedPassengers'] ?? 0;

                          final seatsLeft = vehicleCapacity - boardedPassengers;
                          final safeSeats = seatsLeft < 0 ? 0 : seatsLeft;
                          final isFull = safeSeats <= 0;

                          return _driverCard(
                            data: data,
                            vehicleImage: vehicleImage,
                            vehicleName: vehicleName,
                            driverCode: driverCode,
                            vehicleCapacity: vehicleCapacity,
                            boardedPassengers: boardedPassengers,
                            seatsLeft: safeSeats,
                            isFull: isFull,
                          );
                        },
                      );
                    },
                  ),
                ),
              ],
            );
          },
        );
      },
    );
  }

  final List<String> _searchSuggestions = [
    "shuttles",
    "routes",
    "institutions",
    "campuses",
    "cities",
  ];

  int _currentSuggestion = 0;

  Timer? _searchHintTimer;

  Widget _avatarFallback() {
    return Container(
      width: 52,
      height: 52,
      color: Colors.grey[200],
      child: const Icon(Icons.person, color: Colors.grey),
    );
  }

  @override
  void initState() {
    super.initState();

    _searchHintTimer = Timer.periodic(
      const Duration(seconds: 2),
      (_) {
        if (!mounted) return;

        setState(() {
          _currentSuggestion =
              (_currentSuggestion + 1) % _searchSuggestions.length;
        });
      },
    );
  }

