  Widget _driverCard({
    required Map<String, dynamic> data,
    required String vehicleImage,
    required String vehicleName,
    required String driverCode,
    required int vehicleCapacity,
    required int boardedPassengers,
    required int seatsLeft,
    required bool isFull,
  }) {
    return GestureDetector(
      onTap: (!isFull)
          ? () {
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) => ShuttlePaymentPage(driverData: data),
                ),
              );
            }
          : null,
      child: Container(
        height: 70,
        margin: const EdgeInsets.only(bottom: 10),
        padding: const EdgeInsets.symmetric(horizontal: 10),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(14),
          border: Border.all(color: Colors.grey.shade200),
        ),
        child: Row(
          children: [
            /// 🚐 Vehicle Image
            ClipOval(
              child: vehicleImage.isNotEmpty
                  ? Image.network(
                      vehicleImage,
                      width: 48,
                      height: 48,
                      fit: BoxFit.cover,
                      errorBuilder: (context, error, stackTrace) {
                        debugPrint("IMAGE ERROR: $error");
                        debugPrint("URL: $vehicleImage");

                        return Container(
                          width: 48,
                          height: 48,
                          color: Colors.grey[200],
                          child: const Icon(Icons.directions_bus),
                        );
                      },
                      loadingBuilder: (context, child, progress) {
                        if (progress == null) return child;

                        return Container(
                          width: 48,
                          height: 48,
                          color: Colors.green[50],
                          child: const Center(
                            child: SizedBox(
                              width: 18,
                              height: 18,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            ),
                          ),
                        );
                      },
                    )
                  : Container(
                      width: 48,
                      height: 48,
                      color: Colors.green[50],
                      //child: const Icon(Icons.directions_bus),
                    ),
            ),
            const SizedBox(width: 10),

            /// INFO
            Expanded(
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    "$driverCode • $vehicleName",
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 4),
                  Row(
                    children: [
                      Text(
                        "$boardedPassengers/$vehicleCapacity",
                        style: TextStyle(
                          fontSize: 11,
                          color: Colors.grey[600],
                        ),
                      ),
                      const SizedBox(width: 8),
                      Text(
                        isFull ? "Full" : "Seats: $seatsLeft",
                        style: TextStyle(
                          fontSize: 11,
                          color: isFull ? Colors.red : Colors.green,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            ),

            /// PRICE / FULL
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
              decoration: BoxDecoration(
                color: isFull ? Colors.grey : Colors.black,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                isFull ? "Full" : "₦${data['price'] ?? 0}",
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 12,
                  fontWeight: FontWeight.bold,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

