  Widget _buildOnlineDrivers() {
    return SizedBox(
      height: 150,
      child: StreamBuilder<QuerySnapshot>(
        stream: FirebaseFirestore.instance
            .collection("shuttle_drivers")
            .where("status", isEqualTo: "online")
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) {
            return Center(
              child: Text(
                "Something went wrong.",
                style: TextStyle(
                  color: Colors.grey.shade600,
                ),
              ),
            );
          }

          if (!snapshot.hasData) {
            return ListView.builder(
              scrollDirection: Axis.horizontal,
              itemCount: 3,
              itemBuilder: (_, __) => _onlineProviderShimmer(),
            );
          }

          final drivers = snapshot.data!.docs;

          if (drivers.isEmpty) {
            return Center(
              child: Text(
                "No shuttles available at the moment.",
                style: TextStyle(
                  color: Colors.grey.shade600,
                ),
              ),
            );
          }

          return ListView.builder(
            scrollDirection: Axis.horizontal,
            itemCount: drivers.length,
            itemBuilder: (context, index) {
              final doc = drivers[index];

              final data = doc.data() as Map<String, dynamic>;

              data["id"] = doc.id;

              final image = data["vehicleImage"] ?? "";
              final vehicle = data["vehicleName"] ?? "";
              final institution = data["activeInstitution"] ?? "";
              final capacity = data["vehicleCapacity"] ?? 0;
              final boarded = data["boardedPassengers"] ?? 0;
              final seatsLeft = capacity - boarded;
              final isFull = seatsLeft <= 0;

              return GestureDetector(
                onTap: isFull
                    ? null
                    : () {
                        Navigator.push(
                          context,
                          MaterialPageRoute(
                            builder: (_) =>
                                ShuttlePaymentPage(driverData: data),
                          ),
                        );
                      },
                child: Container(
                  width: 300,
                  height: 100,
                  margin: const EdgeInsets.only(bottom: 14),
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(
                      color: Colors.grey.shade200,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(.05),
                        blurRadius: 12,
                        offset: const Offset(0, 5),
                      ),
                    ],
                  ),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: [
                      /// ==========================
                      /// COLUMN 1 - IMAGE
                      /// ==========================
                      SizedBox(
                        width: 70,
                        child: Center(
                          child: ClipOval(
                            child: image.toString().isNotEmpty
                                ? Image.network(
                                    image,
                                    width: 60,
                                    height: 60,
                                    fit: BoxFit.cover,
                                    errorBuilder: (_, __, ___) => Container(
                                      width: 60,
                                      height: 60,
                                      decoration: BoxDecoration(
                                        color: Colors.grey.shade100,
                                        shape: BoxShape.circle,
                                      ),
                                      child: const Icon(
                                        Icons.directions_bus,
                                        color: Colors.black,
                                      ),
                                    ),
                                  )
                                : Container(
                                    width: 60,
                                    height: 60,
                                    decoration: BoxDecoration(
                                      color: Colors.grey.shade100,
                                      shape: BoxShape.circle,
                                    ),
                                    child: const Icon(
                                      Icons.directions_bus,
                                      color: Colors.black,
                                    ),
                                  ),
                          ),
                        ),
                      ),

                      const SizedBox(width: 12),

                      /// ==========================
                      /// COLUMN 2 - DETAILS
                      /// ==========================
                      Expanded(
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              vehicle,
                              // maxLines: 1,
                              // overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            const SizedBox(height: 10),
                            Text(
                              institution,
                              //maxLines: 2,
                              // overflow: TextOverflow.ellipsis,
                              style: TextStyle(
                                fontSize: 12,
                                color: Colors.grey.shade600,
                              ),
                            ),
                          ],
                        ),
                      ),

                      const SizedBox(width: 14),

                      /// ==========================
                      /// COLUMN 3 - PRICE & SEATS
                      /// ==========================
                      SizedBox(
                        width: 80,
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.center,
                          crossAxisAlignment: CrossAxisAlignment.end,
                          children: [
                            Text(
                              "₦${data["price"] ?? 0}",
                              style: const TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                            const SizedBox(height: 10),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 8,
                                vertical: 3,
                              ),
                              decoration: BoxDecoration(
                                color: isFull
                                    ? Colors.red.shade50
                                    : Colors.green.shade50,
                                borderRadius: BorderRadius.circular(20),
                              ),
                              child: Text(
                                isFull ? "Full" : "$seatsLeft Seats Left",
                                style: TextStyle(
                                  color:
                                      isFull ? Colors.red : Color(0xff388e3c),
                                  fontSize: 8,
                                  //fontWeight: FontWeight.w600,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        },
      ),
    );
  }

  Widget _onlineProviderShimmer() {
    return Container(
      width: 300,
      height: 100,
      margin: const EdgeInsets.only(right: 15),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: Colors.grey.shade200,
        ),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(.05),
            blurRadius: 12,
            offset: const Offset(0, 5),
          ),
        ],
      ),
      child: Shimmer.fromColors(
        baseColor: Colors.grey.shade300,
        highlightColor: Colors.grey.shade100,
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16),
          child: Row(
            children: [
              /// VEHICLE IMAGE
              Container(
                width: 60,
                height: 60,
                decoration: const BoxDecoration(
                  color: Colors.white,
                  shape: BoxShape.circle,
                ),
              ),

              const SizedBox(width: 12),

              /// VEHICLE + INSTITUTION
              Expanded(
