  Widget _buildRecentTickets() {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection("shuttle_tickets")
          .where(
            "userId",
            isEqualTo: FirebaseAuth.instance.currentUser!.uid,
          )
          .limit(10)
          .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData) {
          return _recentTicketsShimmer();
        }
        if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
          return Container(
            width: double.infinity,
            padding: const EdgeInsets.all(24),
            decoration: BoxDecoration(
              color: Colors.grey.shade100,
              borderRadius: BorderRadius.circular(16),
            ),
            child: const Column(
              children: [
                Icon(
                  Icons.history,
                  size: 40,
                  color: Colors.grey,
                ),
                SizedBox(height: 10),
                Text(
                  "No recent shuttle bookings.",
                  style: TextStyle(
                    fontWeight: FontWeight.w500,
                  ),
                ),
              ],
            ),
          );
        }

        return Column(
          children: snapshot.data!.docs.map((doc) {
            final data = doc.data() as Map<String, dynamic>;

            final pickup = data["pickup"] ?? "";
            final destination = data["destination"] ?? "";
            final status = (data["status"] ?? "Booked").toString();
            final price = data["price"] ?? 0;

            Color statusColor;

            switch (status.toLowerCase()) {
              case "completed":
                statusColor = Colors.green;
                break;

              case "cancelled":
                statusColor = Colors.red;
                break;

              case "ongoing":
                statusColor = Colors.orange;
                break;

              case "pending":
                statusColor = Colors.blue;
                break;

              default:
                statusColor = Colors.black;
            }

            return Center(
              child: GestureDetector(
                onTap: () {
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => ShuttleTicketDetailsPage(
                        // ticketData: data,
                        ticketDoc: doc,
                      ),
                    ),
                  );
                },
                child: Container(
                  width: 350,
                  height: 85,
                  margin: const EdgeInsets.only(bottom: 12),
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(18),
                    border: Border.all(color: Colors.grey.shade200),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(.05),
                        blurRadius: 12,
                        offset: const Offset(0, 5),
                      ),
                    ],
                  ),
                  child: FutureBuilder<QuerySnapshot>(
                    future: FirebaseFirestore.instance
                        .collection("shuttle_drivers")
                        .where("driverCode", isEqualTo: data["driverCode"])
                        .limit(1)
                        .get(),
                    builder: (context, driverSnapshot) {
                      String vehicleName = "Unknown Vehicle";

                      if (driverSnapshot.hasData &&
                          driverSnapshot.data!.docs.isNotEmpty) {
                        final driverData = driverSnapshot.data!.docs.first
                            .data() as Map<String, dynamic>;

                        vehicleName =
                            driverData["vehicleName"] ?? "Unknown Vehicle";
                      }

                      final ticketId = data["ticketId"] ?? "N/A";
                      final price = data["price"] ?? 0;

                      final rawStatus =
                          (data["status"] ?? "").toString().toLowerCase();

                      String displayStatus;
                      Color statusColor;

                      switch (rawStatus) {
                        case "paid":
                          displayStatus = "UNUSED";
                          statusColor = Colors.green;
                          break;

                        case "used":
                          displayStatus = "USED";
                          statusColor = Colors.grey;
                          break;

                        case "cancelled":
                          displayStatus = "CANCELLED";
                          statusColor = Colors.red;
                          break;

                        case "pending":
                          displayStatus = "PENDING";
                          statusColor = Colors.orange;
                          break;

                        case "completed":
                          displayStatus = "COMPLETED";
                          statusColor = Colors.green;
                          break;

                        default:
                          displayStatus = rawStatus.toUpperCase();
                          statusColor = Colors.black;
                      }

                      return Row(
                        children: [
                          /// Bus Icon
                          Container(
                            width: 42,
                            height: 42,
                            decoration: const BoxDecoration(
                              color: Colors.black,
                              shape: BoxShape.circle,
                            ),
                            child: const Icon(
                              Icons.directions_bus_rounded,
                              color: Colors.white,
                              size: 20,
                            ),
                          ),

                          const SizedBox(width: 14),

                          /// Ticket ID & Vehicle Name
                          Expanded(
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.center,
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  ticketId.toString(),
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: const TextStyle(
                                    fontWeight: FontWeight.bold,
                                    fontSize: 14,
                                  ),
                                ),
                                const SizedBox(height: 4),
                                Text(
                                  vehicleName,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                    color: Colors.grey.shade600,
                                    fontSize: 12,
                                  ),
                                ),
                              ],
                            ),
                          ),

                          const SizedBox(width: 10),

                          /// Price & Status
                          Column(
                            mainAxisAlignment: MainAxisAlignment.center,
                            crossAxisAlignment: CrossAxisAlignment.end,
                            children: [
                              Text(
                                "₦$price",
                                style: const TextStyle(
                                  fontWeight: FontWeight.bold,
                                  fontSize: 15,
                                ),
                              ),
                              const SizedBox(height: 5),
                              Text(
                                displayStatus,
                                style: TextStyle(
                                  color: statusColor,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                            ],
                          ),
                        ],
                      );
                    },
                  ),
                ),
              ),
            );
          }).toList(),
        );
      },
    );
  }

