  Widget _infoBox(String text, {bool highlight = false}) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: highlight ? Colors.white : Colors.white,
        borderRadius: BorderRadius.circular(10),
        boxShadow: [
          BoxShadow(
            color: Colors.grey.withOpacity(0.1),
            blurRadius: 6,
          )
        ],
      ),
      child: Text(
        text,
        style: TextStyle(
          fontWeight: highlight ? FontWeight.bold : FontWeight.normal,
        ),
      ),
    );
  }

  /// 🚀 UPDATED BOARDING DIALOG

  Future<void> _handleBoarding() async {
    final controller = TextEditingController();

    final enteredCode = await showDialog<String>(
      context: context,
      builder: (_) => Dialog(
        backgroundColor: Colors.white,
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(20),
        ),
        child: Padding(
          padding: const EdgeInsets.all(20),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Text(
                "Enter Shuttle Code",
                style: TextStyle(
                  fontWeight: FontWeight.bold,
                  fontSize: 18,
                ),
              ),
              const SizedBox(height: 20),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 12),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.grey.withOpacity(.2),
                      blurRadius: 8,
                    )
                  ],
                ),
                child: TextField(
                  controller: controller,
                  decoration: const InputDecoration(
                    border: InputBorder.none,
                    hintText: "Enter shuttle code",
                  ),
                ),
              ),
              const SizedBox(height: 15),
              Container(
                width: double.infinity,
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: Colors.grey.shade100,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: const Center(
                  child: Text(
                    "Scan QR",
                    style: TextStyle(fontWeight: FontWeight.bold),
                  ),
                ),
              ),
              const SizedBox(height: 20),
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  style: ElevatedButton.styleFrom(
                    backgroundColor: Colors.black,
                    padding: const EdgeInsets.symmetric(vertical: 14),
                  ),
                  onPressed: () =>
                      Navigator.pop(context, controller.text.trim()),
                  child: const Text(
                    "Confirm",
                    style: TextStyle(color: Colors.white),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );

    if (enteredCode == null || enteredCode.isEmpty) return;

    final ticketData = widget.ticketDoc.data() as Map<String, dynamic>;
    final correctCode = ticketData["driverCode"] ?? "";

    if (enteredCode != correctCode) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text("Incorrect shuttle code"),
          backgroundColor: Colors.red,
        ),
      );
      return;
    }

    setState(() => boarding = true);

    try {
      await widget.ticketDoc.reference.update({
        "status": "used",
        "boardedAt": FieldValue.serverTimestamp(),
      });

      if (!mounted) return;

      setState(() => boarding = false);

      showDialog(
        context: context,
        barrierDismissible: false,
        builder: (context) {
          Future.delayed(const Duration(seconds: 2), () {
            if (context.mounted) {
              Navigator.pop(context);
            }
          });

          return AlertDialog(
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(20),
            ),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: const [
                Icon(
                  Icons.check_circle,
                  color: Colors.green,
                  size: 70,
                ),
                SizedBox(height: 16),
                Text(
                  "Bus Boarded Successfully",
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: 18,
                    fontWeight: FontWeight.bold,
                  ),
                ),
              ],
            ),
          );
        },
      );

      // Navigator.pop(context);
    } catch (e) {
      setState(() => boarding = false);

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text("Verification failed: $e"),
          backgroundColor: Colors.red,
        ),
      );
    }
  }
}

class ShuttlePaymentPage extends StatefulWidget {
  final Map<String, dynamic> driverData;

  const ShuttlePaymentPage({
    super.key,
    required this.driverData,
  });

  @override
  State<ShuttlePaymentPage> createState() => _ShuttlePaymentPageState();
}

class _ShuttlePaymentPageState extends State<ShuttlePaymentPage> {
  bool loading = false;

  late String institution;
  late String pickup;
  late String destination;
  late int price;
  late String driverId;
  late String driverCode;

  @override
  void initState() {
    super.initState();

    final data = widget.driverData;

    institution = data['activeInstitution'] ?? '';
    pickup = data['pickupLocation'] ?? '';
    destination = data['destinationLocation'] ?? '';
    price = (data['price'] ?? 0);
    driverId = data['id'] ?? '';
    driverCode = data['driverCode'] ?? '';
  }

  Future<void> _payWithPaystack() async {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;

    setState(() => loading = true);

    try {
      const String paystackSecretKey =
          'sk_test_661490bf9dc0914e122c2c043ab3aaf3a307d658';

      final int amount = (price * 100).toInt();
      final String reference =
          "shuttle_${DateTime.now().millisecondsSinceEpoch}";

      final response = await http.post(
        Uri.parse('https://api.paystack.co/transaction/initialize'),
        headers: {
          'Authorization': 'Bearer $paystackSecretKey',
          'Content-Type': 'application/json',
        },
        body: jsonEncode({
          'email': user.email,
          'amount': amount,
          'reference': reference,
        }),
      );

      if (response.statusCode != 200) {
        throw "Unable to initialize payment";
      }

      final data = jsonDecode(response.body);
      final String checkoutUrl = data['data']['authorization_url'];

      await launchUrl(
        Uri.parse(checkoutUrl),
        mode: LaunchMode.externalApplication,
      );

      final ticketDoc = await _completeBooking(reference);

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Payment successful! Ticket booked.")),
      );

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) => ShuttleTicketDetailsPage(
            ticketDoc: ticketDoc,
          ),
        ),
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Payment failed: $e")),
      );
    } finally {
      setState(() => loading = false);
    }
  }

  Future<DocumentSnapshot> _completeBooking(String paymentReference) async {
    final user = FirebaseAuth.instance.currentUser!;
    final driverRef =
        FirebaseFirestore.instance.collection("shuttle_drivers").doc(driverId);

    final ticketRef =
        FirebaseFirestore.instance.collection("shuttle_tickets").doc();

    await FirebaseFirestore.instance.runTransaction((transaction) async {
      final snapshot = await transaction.get(driverRef);

      if (!snapshot.exists) {
        throw Exception("Driver not found");
      }

      final data = snapshot.data()!;
      int boarded = data['boardedPassengers'] ?? 0;
      int capacity = data['vehicleCapacity'] ?? 0;
      int currentEarnings = data['amountCollected'] ?? 0;

      if (boarded >= capacity) {
        throw Exception("Bus is full");
      }

      transaction.update(driverRef, {
        "boardedPassengers": boarded + 1,
        "amountCollected": currentEarnings + price,
      });

      String ticketId = "ST${Random().nextInt(90000) + 10000}";

      transaction.set(ticketRef, {
        "ticketId": ticketId,
        "driverId": driverId,
        "institution": institution,
        "pickup": pickup,
        "destination": destination,
        "price": price,
        "status": "paid",
        "userId": user.uid,
        "userName": user.displayName ?? "User",
        "paymentReference": paymentReference,
        "createdAt": FieldValue.serverTimestamp(),
        "driverCode": driverCode,
      });
    });
    final ticketDoc = await ticketRef.get();
    return ticketDoc;
  }

