class ExploreAutoScrollCards extends StatefulWidget {
  const ExploreAutoScrollCards({super.key});

  @override
  State<ExploreAutoScrollCards> createState() => _ExploreAutoScrollCardsState();
}

class _ExploreAutoScrollCardsState extends State<ExploreAutoScrollCards> {
  final PageController _pageController = PageController(viewportFraction: 0.45);
  int _currentPage = 0;

  @override
  void initState() {
    super.initState();

    // Auto scroll every 5 seconds
    WidgetsBinding.instance.addPostFrameCallback((_) {
      Timer.periodic(const Duration(seconds: 5), (timer) {
        if (!mounted) return;

        _currentPage++;
        if (_currentPage > 4) _currentPage = 0;

        _pageController.animateToPage(
          _currentPage,
          duration: const Duration(milliseconds: 500),
          curve: Curves.easeInOut,
        );
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    return PageView.builder(
      controller: _pageController,
      itemCount: 5,
      scrollDirection: Axis.horizontal,
      itemBuilder: (context, index) {
        return Container(
          margin: const EdgeInsets.symmetric(horizontal: 8),
          width: 50,
          height: 50,
          decoration: BoxDecoration(
            color: Colors.grey[200],
            borderRadius: BorderRadius.circular(14),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withOpacity(0.08),
                blurRadius: 6,
                offset: const Offset(0, 3),
              )
            ],
          ),
          child: Center(
            child: Text(
              "Card ${index + 1}",
              style: const TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w600,
              ),
            ),
          ),
        );
      },
    );
  }
}

class OrdersPage extends StatefulWidget {
  const OrdersPage({super.key});

  @override
  State<OrdersPage> createState() => _OrdersPageState();
}

class _OrdersPageState extends State<OrdersPage> {
  // ------------------- FETCH MOCK ACTIVITIES -------------------
  Future<List<Map<String, dynamic>>> _fetchRecentActivities() async {
    await Future.delayed(const Duration(seconds: 1)); // simulate load

    return [
      {
        "type": "Ride",
        "pickup": "Airport Road",
        "destination": "Wuse 2",
        "status": "Completed",
        "time": DateTime.now().subtract(const Duration(hours: 1)),
      },
      {
        "type": "Logistics",
        "pickup": "Garki",
        "destination": "Lugbe",
        "status": "Pending",
        "time": DateTime.now().subtract(const Duration(hours: 3)),
      },
      {
        "type": "Transport",
        "pickup": "Abuja",
        "destination": "Lagos",
        "status": "In Transit",
        "time": DateTime.now().subtract(const Duration(days: 1)),
      },
    ];
  }

  // ------------------- STATUS COLOR -------------------
  Color _statusColor(String status) {
    switch (status) {
      case "Completed":
        return Colors.green;
      case "Pending":
        return Colors.orange;
      case "In Transit":
        return Colors.blue;
      default:
        return Colors.grey;
    }
  }

  // ------------------- FORMAT TIME -------------------
  String _formatTime(dynamic time) {
    if (time is DateTime) {
      return "${time.hour}:${time.minute.toString().padLeft(2, '0')}  ·  ${time.day}/${time.month}/${time.year}";
    }
    return time.toString();
  }

  // ------------------- BUILD UI -------------------
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        //automaticallyImplyLeading: false, // 👈 turn this off since we customize it
        backgroundColor: Colors.white,
        elevation: 0,

        leading: Padding(
          padding: const EdgeInsets.only(left: 10),
          child: GestureDetector(
            onTap: () => Navigator.pop(context),
            child: Container(
              width: 25,
              height: 25,
              decoration: BoxDecoration(
                color: Colors.grey[100], // ✅ grey 50 look
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.arrow_back_ios,
                size: 14,
                color: Colors.black,
              ),
            ),
          ),
        ),

        title: const Padding(
          padding: EdgeInsets.only(left: 8), // ✅ spacing from icon
          child: Text(
            'Orders',
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.bold,
              color: Colors.black,
            ),
          ),
        ),
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: FutureBuilder<List<Map<String, dynamic>>>(
          future: _fetchRecentActivities(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Center(child: CircularProgressIndicator());
            }
            if (!snapshot.hasData || snapshot.data!.isEmpty) {
              return const Center(child: Text("No recent activities."));
            }

            final activities = snapshot.data!;

            return ListView.builder(
              itemCount: activities.length,
              itemBuilder: (context, index) {
                final activity = activities[index];

                return Container(
                  margin: const EdgeInsets.symmetric(vertical: 10),
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(18),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(0.05),
                        blurRadius: 10,
                        offset: const Offset(0, 3),
                      ),
                    ],
                  ),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.center,
                    children: [
                      // LEFT — ICON
                      Container(
                        width: 48,
                        height: 48,
                        decoration: BoxDecoration(
                          color: Colors.grey[200],
                          shape: BoxShape.circle,
                        ),
                        child: Icon(
                          activity["type"] == "Ride"
                              ? Icons.directions_bike
                              : activity["type"] == "Logistics"
                                  ? Icons.local_shipping
                                  : Icons.directions_bus,
                          size: 22,
                          color: Colors.deepPurple,
                        ),
                      ),

                      const SizedBox(width: 16),

                      // MIDDLE COLUMN — PICKUP → DESTINATION + DATE
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              "${activity["pickup"]} → ${activity["destination"]}",
                              style: const TextStyle(
                                fontSize: 15,
                                fontWeight: FontWeight.w600,
                                color: Colors.black87,
                              ),
                            ),
                            const SizedBox(height: 6),
                            Row(
                              children: [
                                const Icon(Icons.access_time,
                                    size: 12, color: Colors.grey),
                                const SizedBox(width: 4),
                                Text(
                                  _formatTime(activity["time"]),
                                  style: TextStyle(
                                    fontSize: 12,
                                    color: Colors.grey[600],
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),

                      // RIGHT COLUMN — TYPE + STATUS BADGE
                      Column(
                        crossAxisAlignment: CrossAxisAlignment.end,
                        children: [
                          Text(
                            activity["type"],
                            style: const TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          const SizedBox(height: 8),
                          Container(
                            padding: const EdgeInsets.symmetric(
                                horizontal: 10, vertical: 5),
                            decoration: BoxDecoration(
                              color: _statusColor(activity["status"])
                                  .withOpacity(0.15),
                              borderRadius: BorderRadius.circular(14),
                            ),
                            child: Text(
                              activity["status"],
                              style: TextStyle(
                                fontSize: 11,
                                color: _statusColor(activity["status"]),
                                fontWeight: FontWeight.w600,
                              ),
                            ),
                          ),
                        ],
                      ),
                    ],
                  ),
                );
              },
            );
          },
        ),
      ),
    );
  }
}

class ShoppingSectionPage extends StatefulWidget {
  const ShoppingSectionPage({super.key});

  @override
  State<ShoppingSectionPage> createState() => _ShoppingSectionPageState();
}

class _ShoppingSectionPageState extends State<ShoppingSectionPage>
    with SingleTickerProviderStateMixin {
  // ============================================================
  // CART
  // ============================================================

  final Map<String, int> _selectedItems = {};
  final Map<String, Map<String, dynamic>> _productDetails = {};

  final GlobalKey _cartKey = GlobalKey();

  late AnimationController _animationController;
  OverlayEntry? _overlayEntry;

  late Offset _startPosition;
  late Offset _endPosition;
  late Offset _controlPoint;

  // ============================================================
  // SHOPPING VENDORS
  // ============================================================

  List<Map<String, dynamic>> _shoppingVendors = [];
  bool _isLoadingShoppingVendors = true;
  String? _userCity;
  String? _locationError;
  Timer? _vendorStatusTimer;

  String? selectedVendorId;

  // ============================================================
  // FILTERS
  // ============================================================

  String selectedCategory = "All";

  final TextEditingController _searchController = TextEditingController();

  String _searchQuery = "";

  // ============================================================
  // INIT
  // ============================================================

  @override
  void initState() {
    super.initState();

    _animationController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 600),
    );

    _searchController.addListener(() {
      setState(() {
        _searchQuery = _searchController.text.trim().toLowerCase();
      });
    });

    _fetchShoppingVendors();

    // Keep open/closed product availability in sync while this page remains open.
    _vendorStatusTimer = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _searchController.dispose();
    _animationController.dispose();
    _overlayEntry?.remove();
    _vendorStatusTimer?.cancel();
    super.dispose();
  }

  // ============================================================
  // TOTAL CART ITEMS
  // ============================================================

  int get _totalItems {
    return _selectedItems.values.fold(
      0,
      (sum, quantity) => sum + quantity,
    );
  }

  // ============================================================
  // PRICE PARSER
  // ============================================================

  double _parsePrice(dynamic price) {
    if (price == null) return 0;

    if (price is num) {
      return price.toDouble();
    }

    if (price is String) {
      return double.tryParse(
            price.replaceAll(',', '').replaceAll('₦', '').trim(),
          ) ??
          0;
    }

    return 0;
  }

  // ============================================================
  // FETCH SHOPPING VENDORS
  // ============================================================

  Future<void> _fetchShoppingVendors() async {
    if (mounted) {
      setState(() {
        _isLoadingShoppingVendors = true;
        _locationError = null;
      });
    }

    try {
      final user = FirebaseAuth.instance.currentUser;
      if (user == null) {
        if (!mounted) return;
        setState(() {
          _shoppingVendors = [];
          _userCity = null;
          _isLoadingShoppingVendors = false;
          _locationError = 'Please sign in to view vendors near you.';
        });
        return;
      }

      // The user's current address is the source of truth for this page.
      final userDoc = await FirebaseFirestore.instance
          .collection('users')
          .doc(user.uid)
          .get();

      final userData = userDoc.data() ?? <String, dynamic>{};
      final currentAddress = userData['currentAddress'];
      final city = currentAddress is Map
          ? (currentAddress['city'] ?? '').toString().trim()
          : '';

      if (city.isEmpty) {
        if (!mounted) return;
        setState(() {
          _shoppingVendors = [];
          _userCity = null;
          _isLoadingShoppingVendors = false;
          _locationError = 'Set your current location to see vendors near you.';
        });
        return;
      }

      _userCity = city;

      // Query by the actual vendor location structure. Category is filtered
      // locally so this only needs the city index and avoids a compound query.
      final snapshot = await FirebaseFirestore.instance
          .collection('Vendors')
          .where('storeLocation.city', isEqualTo: city)
          .get();

      final vendors = snapshot.docs.map((doc) {
        final data = doc.data();
        final storeLocation = data['storeLocation'];
        final locationMap = storeLocation is Map
            ? Map<String, dynamic>.from(storeLocation)
            : <String, dynamic>{};

        return <String, dynamic>{
          ...data,
          'id': doc.id,
          // Firebase UID remains available as id/uid, while vendorId is the
          // public generated vendor number used by products.vendorIdNo.
          'uid': (data['uid'] ?? doc.id).toString(),
          'vendorId': (data['vendorId'] ?? '').toString(),
          'state': (data['state'] ?? locationMap['state'] ?? '').toString(),
          'city': (data['city'] ?? locationMap['city'] ?? '').toString(),
          'address':
              (data['address'] ?? locationMap['address'] ?? '').toString(),
        };
      }).where((vendor) {
        final category =
            (vendor['category'] ?? '').toString().trim().toLowerCase();
        return category == 'grocery vendor' ||
            category == 'grocery' ||
            category == 'pharmacy';
      }).where((vendor) {
        return (vendor['vendorId'] ?? '').toString().trim().isNotEmpty;
      }).toList();

      if (!mounted) return;
      setState(() {
        _shoppingVendors = vendors;
        _isLoadingShoppingVendors = false;
      });
    } catch (e) {
      debugPrint('Error fetching shopping vendors: $e');
      if (!mounted) return;
      setState(() {
        _shoppingVendors = [];
        _isLoadingShoppingVendors = false;
        _locationError = 'Unable to load vendors right now.';
      });
    }
  }

  String _vendorCity(Map<String, dynamic> vendor) {
    final direct = (vendor['city'] ?? '').toString().trim();
    if (direct.isNotEmpty) return direct;
    final location = vendor['storeLocation'];
    if (location is Map) return (location['city'] ?? '').toString().trim();
    return '';
  }

  String _vendorAddress(Map<String, dynamic> vendor) {
    final direct = (vendor['address'] ?? '').toString().trim();
    if (direct.isNotEmpty) return direct;
    final location = vendor['storeLocation'];
    if (location is Map) return (location['address'] ?? '').toString().trim();
    return '';
  }

  Map<String, dynamic> _vendorHours(Map<String, dynamic> vendor) {
    final raw = vendor['operatingHours'];
    if (raw is Map) return Map<String, dynamic>.from(raw);
    return <String, dynamic>{};
  }

  bool _isVendorOpen(Map<String, dynamic> vendor, [DateTime? now]) {
    final hours = _vendorHours(vendor);
    if (hours.isEmpty) return false;

    final current = now ?? DateTime.now();
    const dayNames = [
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
      'Sunday',
    ];
    final today = hours[dayNames[current.weekday - 1]];
    if (today is! Map) return false;

    final enabled = today['enabled'] == true;
    final opening = (today['openingTime'] ?? '').toString();
    final closing = (today['closingTime'] ?? '').toString();
    if (!enabled || opening.isEmpty || closing.isEmpty) return false;

    final openMinutes = _timeToMinutes(opening);
    final closeMinutes = _timeToMinutes(closing);
    if (openMinutes == null || closeMinutes == null) return false;

    final currentMinutes = current.hour * 60 + current.minute;

    // Supports both normal schedules and overnight schedules.
    if (closeMinutes > openMinutes) {
      return currentMinutes >= openMinutes && currentMinutes < closeMinutes;
    }
    if (closeMinutes < openMinutes) {
      return currentMinutes >= openMinutes || currentMinutes < closeMinutes;
    }

    // Equal opening/closing times are treated as closed rather than 24 hours.
    return false;
  }

  int? _timeToMinutes(String value) {
    final parts = value.split(':');
    if (parts.length != 2) return null;
    final hour = int.tryParse(parts[0]);
    final minute = int.tryParse(parts[1]);
    if (hour == null ||
        minute == null ||
        hour < 0 ||
        hour > 23 ||
        minute < 0 ||
        minute > 59) {
      return null;
    }
    return hour * 60 + minute;
  }

  String _operatingStatusText(Map<String, dynamic> vendor) {
    if (_isVendorOpen(vendor)) return 'Open now';
    return 'Closed now';
  }

  String _operatingHoursText(Map<String, dynamic> vendor) {
    final hours = _vendorHours(vendor);
    final now = DateTime.now();
    const dayNames = [
      'Monday',
      'Tuesday',
      'Wednesday',
      'Thursday',
      'Friday',
      'Saturday',
      'Sunday',
    ];
    final today = hours[dayNames[now.weekday - 1]];
    if (today is! Map || today['enabled'] != true) return 'Closed today';
    final open = (today['openingTime'] ?? '').toString();
    final close = (today['closingTime'] ?? '').toString();
    if (open.isEmpty || close.isEmpty) return 'Closed today';
    return '$open – $close';
  }

  Future<bool> _confirmDifferentVendor({
    required Map<String, dynamic> product,
    required Map<String, dynamic> vendor,
  }) async {
    final productVendorIdNo = (product['vendorIdNo'] ?? '').toString().trim();
    final existingVendorIds = <String>{};
    for (final item in _productDetails.values) {
      final id = (item['vendorIdNo'] ?? '').toString().trim();
      if (id.isNotEmpty) existingVendorIds.add(id);
    }

    if (existingVendorIds.isEmpty ||
        existingVendorIds.contains(productVendorIdNo)) {
      return true;
    }

    final newVendorName =
        (vendor['businessName'] ?? vendor['name'] ?? 'another vendor')
            .toString();

    final confirmed = await showDialog<bool>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) => AlertDialog(
        backgroundColor: Colors.white,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
        title: const Text(
          'Different vendor',
          style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700),
        ),
        content: Text(
          'You are adding a product from $newVendorName. Products from different vendors may incur an additional delivery fee. Do you want to continue?',
          style: TextStyle(fontSize: 13, color: Colors.grey[700], height: 1.45),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext, false),
            child: Text('Cancel',
                style: TextStyle(
                    color: Colors.grey[700], fontWeight: FontWeight.w600)),
          ),
          ElevatedButton(
            onPressed: () => Navigator.pop(dialogContext, true),
            style: ElevatedButton.styleFrom(
              backgroundColor: Colors.black,
              foregroundColor: Colors.white,
              elevation: 0,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(10)),
            ),
            child: const Text('Continue',
                style: TextStyle(fontWeight: FontWeight.w700)),
          ),
        ],
      ),
    );

    return confirmed == true;
  }

  // ============================================================
  // VENDOR FALLBACK IMAGE
  // ============================================================

  String _getVendorFallbackImage(
    Map<String, dynamic> vendor,
  ) {
    final vendorCategory =
        (vendor['category'] ?? '').toString().trim().toLowerCase();

    // ----------------------------------------------------------
    // PHARMACY
    // ----------------------------------------------------------

    if (vendorCategory == 'pharmacy') {
      return 'assets/images/p1.png';
    }

    // ----------------------------------------------------------
    // GROCERY
    // ----------------------------------------------------------

    if (vendorCategory == 'grocery vendor' || vendorCategory == 'grocery') {
      const groceryImages = [
        'assets/images/gr1.jpg',
        'assets/images/gr2.jpg',
      ];

      final vendorKey =
          (vendor['id'] ?? vendor['uid'] ?? vendor['businessName'] ?? 'grocery')
              .toString();

      final index = vendorKey.codeUnits.fold<int>(
            0,
            (sum, code) => sum + code,
          ) %
          groceryImages.length;

      return groceryImages[index];
    }

    // ----------------------------------------------------------
    // GENERIC SHOPPING FALLBACK
    // ----------------------------------------------------------

    return 'assets/images/gr1.jpg';
  }

  // ============================================================
  // SHOPPING PRODUCT FALLBACK
  // ============================================================

  String _getProductFallbackImage(
    Map<String, dynamic> product,
  ) {
    final productName =
        (product['name'] ?? product['productName'] ?? product['title'] ?? '')
            .toString()
            .trim()
            .toLowerCase();

    // ----------------------------------------------------------
    // BREAD
    // ----------------------------------------------------------

    if (productName.contains('bread')) {
      const images = [
        'assets/images/bread.jpg',
        'assets/images/bread2.jpg',
      ];

      final key = (product['id'] ??
              product['name'] ??
              product['productName'] ??
              'bread')
          .toString();

      final index = key.codeUnits.fold<int>(
            0,
            (sum, code) => sum + code,
          ) %
          images.length;

      return images[index];
    }

    // ----------------------------------------------------------
    // TATTASHE
    // ----------------------------------------------------------

    if (productName.contains('tattashe') ||
        productName.contains('tatashe') ||
        productName.contains('tatashe pepper')) {
      return 'assets/images/tss1.jpg';
    }

    // ----------------------------------------------------------
    // TOMATO
    // ----------------------------------------------------------

    if (productName.contains('tomato') || productName.contains('tomatoes')) {
      return 'assets/images/tm.jpg';
    }

    // ----------------------------------------------------------
    // ONION
    // ----------------------------------------------------------

    if (productName.contains('onion') || productName.contains('onions')) {
      return 'assets/images/on.jpg';
    }

    // ----------------------------------------------------------
    // OIL
    // ----------------------------------------------------------

    if (productName.contains('oil')) {
      const images = [
        'assets/images/oil.jpg',
        'assets/images/oil1.jpg',
      ];

      final key =
          (product['id'] ?? product['name'] ?? product['productName'] ?? 'oil')
              .toString();

      final index = key.codeUnits.fold<int>(
            0,
            (sum, code) => sum + code,
          ) %
          images.length;

      return images[index];
    }

    // ----------------------------------------------------------
    // GENERIC SHOPPING FALLBACK
    // ----------------------------------------------------------

    const allShoppingImages = [
      'assets/images/gr1.jpg',
      'assets/images/gr2.jpg',
      'assets/images/p1.png',
      'assets/images/oil.jpg',
      'assets/images/oil1.jpg',
      'assets/images/bread.jpg',
      'assets/images/bread2.jpg',
      'assets/images/tss1.jpg',
      'assets/images/on.jpg',
      'assets/images/tm.jpg',
    ];

    final productKey = (product['id'] ??
            product['productId'] ??
            product['name'] ??
            product['productName'] ??
            'product')
        .toString();

    final index = productKey.codeUnits.fold<int>(
          0,
          (sum, code) => sum + code,
        ) %
        allShoppingImages.length;

    return allShoppingImages[index];
  }

  // ============================================================
  // CLEAN IMAGE URL
  // ============================================================

  String _cleanImageUrl(dynamic raw) {
    return (raw ?? '').toString().trim().replaceAll('"', '');
  }

  // ============================================================
  // VENDOR IMAGE
  // ============================================================

  Widget _buildVendorImage(
    Map<String, dynamic> vendor, {
    double size = 78,
  }) {
    final imageUrl = _cleanImageUrl(
      vendor['profileImageUrl'] ?? vendor['image'] ?? vendor['imageUrl'],
    );

    final fallbackImage = _getVendorFallbackImage(vendor);

    if (imageUrl.isEmpty) {
      return Image.asset(
        fallbackImage,
        width: size,
        height: size,
        fit: BoxFit.cover,
      );
    }

    return Image.network(
      imageUrl,
      width: size,
      height: size,
      fit: BoxFit.cover,
      errorBuilder: (_, __, ___) {
        return Image.asset(
          fallbackImage,
          width: size,
          height: size,
          fit: BoxFit.cover,
        );
      },
    );
  }

  // ============================================================
  // PRODUCT IMAGE
  // ============================================================

  Widget _buildProductImage(
    Map<String, dynamic> product, {
    double size = 75,
    bool showLoader = false,
  }) {
    final imageUrl = _cleanImageUrl(
      product['image'] ?? product['imageUrl'] ?? product['productImage'],
    );

    final fallbackImage = _getProductFallbackImage(product);

    if (imageUrl.isEmpty) {
      return Image.asset(
        fallbackImage,
        width: size,
        height: size,
        fit: BoxFit.cover,
      );
    }

    return Image.network(
      imageUrl,
      width: size,
      height: size,
      fit: BoxFit.cover,
      loadingBuilder: (
        context,
        child,
        loadingProgress,
      ) {
        if (loadingProgress == null) {
          return child;
        }

        if (!showLoader) {
          return Image.asset(
            fallbackImage,
            width: size,
            height: size,
            fit: BoxFit.cover,
          );
        }

        return _shimmerBox(
          width: size,
          height: size,
          shape: const CircleBorder(),
        );
      },
      errorBuilder: (_, __, ___) {
        return Image.asset(
          fallbackImage,
          width: size,
          height: size,
          fit: BoxFit.cover,
        );
      },
    );
  }

  // ============================================================
  // SHIMMER
  // ============================================================

  Widget _shimmerBox({
    double? width,
    double? height,
    ShapeBorder? shape,
  }) {
    return Shimmer.fromColors(
      baseColor: Colors.grey[300]!,
      highlightColor: Colors.grey[100]!,
      child: Container(
        width: width,
        height: height,
        decoration: ShapeDecoration(
          color: Colors.grey[300]!,
          shape: shape ??
              RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(8),
              ),
        ),
      ),
    );
  }

  Widget _shimmerProductCard() {
    return Container(
      width: double.infinity,
      height: 92,
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(9),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(16),
        color: Colors.white,
      ),
      child: Row(
        children: [
          _shimmerBox(
            width: 68,
            height: 68,
            shape: const CircleBorder(),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                _shimmerBox(
                  width: 125,
                  height: 14,
                ),
                const SizedBox(height: 8),
                _shimmerBox(
                  width: 170,
                  height: 10,
                ),
                const SizedBox(height: 8),
                _shimmerBox(
                  width: 70,
                  height: 12,
                ),
              ],
            ),
          ),
          _shimmerBox(
            width: 34,
            height: 34,
            shape: const CircleBorder(),
          ),
        ],
      ),
    );
  }

  Widget _shimmerVendorCard() {
    return Container(
      width: 285,
      height: 112,
      margin: const EdgeInsets.only(right: 10),
      padding: const EdgeInsets.symmetric(horizontal: 11),
      decoration: BoxDecoration(
          color: Colors.grey[100], borderRadius: BorderRadius.circular(16)),
      child: Row(children: [
        _shimmerBox(width: 72, height: 72, shape: const CircleBorder()),
        const SizedBox(width: 11),
        Expanded(
            child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
              _shimmerBox(width: 130, height: 13),
              const SizedBox(height: 8),
              _shimmerBox(width: 150, height: 9),
              const SizedBox(height: 8),
              _shimmerBox(width: 80, height: 16),
            ])),
      ]),
    );
  }

  Widget _buildShimmerList() {
    return ListView.builder(
      padding: EdgeInsets.zero,
      itemCount: 7,
      itemBuilder: (_, __) => _shimmerProductCard(),
    );
  }

  // ============================================================
  // FILTER PRODUCT
  // ============================================================

  bool _shouldShowProduct(Map<String, dynamic> data) {
    final vendorIdNo = (data['vendorIdNo'] ?? '').toString().trim();
    if (vendorIdNo.isEmpty) return false;

    Map<String, dynamic>? vendor;
    for (final candidate in _shoppingVendors) {
      if ((candidate['vendorId'] ?? '').toString().trim() == vendorIdNo) {
        vendor = candidate;
        break;
      }
    }
    if (vendor == null) return false;

    final vendorCity = _vendorCity(vendor).toLowerCase();
    if (_userCity == null || vendorCity != _userCity!.trim().toLowerCase())
      return false;

    final vendorType =
        (vendor['category'] ?? '').toString().trim().toLowerCase();
    if (selectedCategory == 'Groceries' &&
        vendorType != 'grocery vendor' &&
        vendorType != 'grocery') return false;
    if (selectedCategory == 'Pharma' && vendorType != 'pharmacy') return false;

    if (_searchQuery.isNotEmpty) {
      final name =
          (data['name'] ?? data['productName'] ?? '').toString().toLowerCase();
      final description = (data['description'] ?? '').toString().toLowerCase();
      final category = (data['category'] ?? '').toString().toLowerCase();
      if (!name.contains(_searchQuery) &&
          !description.contains(_searchQuery) &&
          !category.contains(_searchQuery)) return false;
    }

    if (selectedVendorId != null && vendorIdNo != selectedVendorId)
      return false;
    return true;
  }

  Map<String, dynamic>? _findVendorForProduct(Map<String, dynamic> product) {
    final vendorIdNo = (product['vendorIdNo'] ?? '').toString().trim();
    if (vendorIdNo.isEmpty) return null;
    for (final vendor in _shoppingVendors) {
      if ((vendor['vendorId'] ?? '').toString().trim() == vendorIdNo)
        return vendor;
    }
    return null;
  }

  // ============================================================
  // GET PRODUCTS FOR VENDOR
  // ============================================================

  Future<List<Map<String, dynamic>>> _getVendorProducts(
      Map<String, dynamic> vendor) async {
    final publicVendorId = (vendor['vendorId'] ?? '').toString().trim();
    if (publicVendorId.isEmpty) return [];

    final snapshot = await FirebaseFirestore.instance
        .collection('products')
        .where('vendorIdNo', isEqualTo: publicVendorId)
        .get();

    return snapshot.docs.map((doc) {
      final data = doc.data();
      return <String, dynamic>{...data, 'id': doc.id};
    }).toList();
  }

