  Widget _emptyState(IconData icon, String message) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(35),
      decoration: BoxDecoration(
          color: Colors.white, borderRadius: BorderRadius.circular(18)),
      child: Column(children: [
        Icon(icon, size: 45, color: Colors.grey[400]),
        const SizedBox(height: 10),
        Text(message, style: TextStyle(fontSize: 14, color: Colors.grey[600]))
      ]),
    );
  }

  // ============================================================
  // CONFIRM OPTION
  // ============================================================

  Future<void> _confirmAddOption({
    required BuildContext context,
    required Map<String, dynamic> item,
    required List<Map<String, dynamic>> selectedList,
    required StateSetter setModalState,
  }) async {
    final itemName = (item['name'] ?? 'This option').toString();

    final itemPrice = _parsePrice(item['price']);

    final confirmed = await showDialog<bool>(
      context: context,
      barrierDismissible: true,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: Colors.white,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(20),
          ),
          title: Row(
            children: [
              Container(
                width: 40,
                height: 40,
                decoration: BoxDecoration(
                  color: Colors.black,
                  borderRadius: BorderRadius.circular(12),
                ),
                child: const Icon(
                  Icons.add_shopping_cart_rounded,
                  color: Colors.white,
                  size: 20,
                ),
              ),
              const SizedBox(width: 12),
              const Expanded(
                child: Text(
                  "Add to order?",
                  style: TextStyle(
                    fontSize: 17,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          ),
          content: Text(
            'Add "$itemName" to your order for '
            '₦${itemPrice.toStringAsFixed(0)}?',
            style: TextStyle(
              fontSize: 14,
              color: Colors.grey[700],
              height: 1.4,
            ),
          ),
          actionsPadding: const EdgeInsets.fromLTRB(
            16,
            0,
            16,
            14,
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(
                  dialogContext,
                  false,
                );
              },
              child: Text(
                "Cancel",
                style: TextStyle(
                  color: Colors.grey[700],
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.black,
                foregroundColor: Colors.white,
                elevation: 0,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
              onPressed: () {
                Navigator.pop(
                  dialogContext,
                  true,
                );
              },
              child: const Text(
                "Add",
                style: TextStyle(
                  fontWeight: FontWeight.w700,
                ),
              ),
            ),
          ],
        );
      },
    );

    if (confirmed == true) {
      setModalState(() {
        if (!selectedList.contains(item)) {
          selectedList.add(item);
        }
      });
    }
  }

  // ============================================================
  // SHOPPING PRODUCT MODAL
  // ============================================================

  void _openShoppingProductModal(
    Map<String, dynamic> product,
    GlobalKey imageKey,
  ) {
    int quantity = 1;

    final List<Map<String, dynamic>> selectedAddons = [];

    final List<Map<String, dynamic>> selectedSides = [];

    final noteController = TextEditingController();

    final basePrice = _parsePrice(product['price']);
    final productVendor = _findVendorForProduct(product);
    final vendorOpen = productVendor != null && _isVendorOpen(productVendor);
    final vendorName = productVendor == null
        ? 'this vendor'
        : (productVendor['businessName'] ??
                productVendor['name'] ??
                'this vendor')
            .toString();

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withOpacity(.55),
      builder: (modalContext) {
        return StatefulBuilder(
          builder: (
            modalContext,
            setModalState,
          ) {
            double total = basePrice;

            for (final addon in selectedAddons) {
              total += _parsePrice(
                addon['price'],
              );
            }

            for (final side in selectedSides) {
              total += _parsePrice(
                side['price'],
              );
            }

            total *= quantity;

            Widget buildOptionCard({
              required String title,
              required String subtitle,
              required dynamic items,
              required List<Map<String, dynamic>> selectedList,
            }) {
              if (items is! List || items.isEmpty) {
                return const SizedBox();
              }

              return Container(
                margin: const EdgeInsets.only(top: 12),
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(
                    color: Colors.grey[200]!,
                  ),
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                title,
                                style: const TextStyle(
                                  fontSize: 15,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                              const SizedBox(height: 3),
                              Text(
                                subtitle,
                                style: TextStyle(
                                  fontSize: 11,
                                  color: Colors.grey[600],
                                ),
                              ),
                            ],
                          ),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.grey[100],
                            borderRadius: BorderRadius.circular(20),
                          ),
                          child: Text(
                            "${items.length} options",
                            style: TextStyle(
                              fontSize: 10,
                              color: Colors.grey[700],
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    Divider(
                      height: 1,
                      color: Colors.grey[200],
                    ),
                    const SizedBox(height: 8),
                    ...List.generate(
                      items.length,
                      (index) {
                        final item = Map<String, dynamic>.from(
                          items[index] as Map,
                        );

                        final isSelected = selectedList.contains(item);

                        final name = (item['name'] ?? 'Option').toString();

                        final price = _parsePrice(
                          item['price'],
                        );

                        return GestureDetector(
                          onTap: () async {
                            if (isSelected) {
                              setModalState(() {
                                selectedList.remove(item);
                              });
                            } else {
                              await _confirmAddOption(
                                context: modalContext,
                                item: item,
                                selectedList: selectedList,
                                setModalState: setModalState,
                              );
                            }
                          },
                          child: AnimatedContainer(
                            duration: const Duration(
                              milliseconds: 180,
                            ),
                            margin: const EdgeInsets.only(
                              bottom: 8,
                            ),
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 10,
                            ),
                            decoration: BoxDecoration(
                              color:
                                  isSelected ? Colors.grey[100] : Colors.white,
                              borderRadius: BorderRadius.circular(12),
                              border: Border.all(
                                color: isSelected
                                    ? Colors.black
                                    : Colors.grey[200]!,
                              ),
                            ),
                            child: Row(
                              children: [
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        name,
                                        style: const TextStyle(
                                          fontSize: 13,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                      const SizedBox(height: 3),
                                      Text(
                                        "+ ₦${price.toStringAsFixed(0)}",
                                        style: TextStyle(
                                          fontSize: 11,
                                          color: Colors.grey[700],
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                Container(
                                  width: 32,
                                  height: 32,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: isSelected
                                        ? Colors.black
                                        : Colors.grey[100],
                                  ),
                                  child: Icon(
                                    isSelected ? Icons.check : Icons.add,
                                    size: 18,
                                    color: isSelected
                                        ? Colors.white
                                        : Colors.black,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
                  ],
                ),
              );
            }

            return Container(
              height: MediaQuery.of(context).size.height * .90,
              decoration: const BoxDecoration(
                color: Colors.grey,
                borderRadius: BorderRadius.vertical(
                  top: Radius.circular(28),
