  // CHECKOUT
  // ============================================================

  void _goToCart() async {
    await Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => CheckoutPage(
          cartItems: _selectedItems,
          productDetails: _productDetails,
        ),
      ),
    );

    if (mounted) {
      setState(() {});
    }
  }

