                      color: const Color(
                        0xFF181818,
                      ),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withOpacity(
                            0.15,
                          ),
                          blurRadius: 20,
                          spreadRadius: 2,
                          offset: const Offset(
                            0,
                            8,
                          ),
                        ),
                      ],
                    ),
                  ),

                  // ==========================================
                  // AMBER DOODLES
                  // ==========================================

                  Positioned.fill(
                    child: IgnorePointer(
                      child: CustomPaint(
                        painter: HeaderDoodlePainter(),
                      ),
                    ),
                  ),

                  SafeArea(
                    bottom: false,
                    child: Padding(
                      padding: const EdgeInsets.fromLTRB(
                        16,
                        20,
                        16,
                        24,
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            "Orders",
                            style: TextStyle(
                              color: Colors.white,
                              fontSize: 22,
                              fontWeight: FontWeight.bold,
                            ),
                          ),

                          const SizedBox(
                            height: 24,
                          ),

                          // ====================================
                          // SEGMENTED CONTROL
                          // ====================================

                          Container(
                            decoration: BoxDecoration(
                              color: Colors.white.withOpacity(
                                .12,
                              ),
                              borderRadius: BorderRadius.circular(
                                25,
                              ),
                            ),
                            padding: const EdgeInsets.all(
                              4,
                            ),
                            child: Row(
                              children: [
                                _segmentItem(
                                  label: "Ongoing",
                                  value: "ongoing",
                                  count: ongoingOrders.length,
                                ),

                                // EXTRA SPACE BETWEEN
                                // ONGOING AND COMPLETED
                                const SizedBox(
                                  width: 8,
                                ),

                                _segmentItem(
                                  label: "Completed",
                                  value: "completed",
                                  count: completedOrders.length,
                                ),
                              ],
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                ],
              ),

              const SizedBox(
                height: 20,
              ),

              // =================================================
              // ORDERS LIST
              // =================================================

              ...ordersToShow.map(
                (doc) {
                  final order = doc.data() as Map<String, dynamic>? ?? {};

                  final status = (order['status'] ?? 'pending').toString();

                  // =============================================
                  // ITEMS
                  // =============================================

                  List<Map<String, dynamic>> items = [];

                  final itemsData = order['items'];

                  if (itemsData is List) {
                    items = itemsData
                        .whereType<Map>()
                        .map<Map<String, dynamic>>(
                          (item) => Map<String, dynamic>.from(
                            item,
                          ),
                        )
                        .toList();
                  }

                  // =============================================
                  // TOTAL PRICE
                  // =============================================

                  final grandTotal = order['grandTotal'];

                  double totalPrice = 0;

                  if (grandTotal is num) {
                    totalPrice = grandTotal.toDouble();
                  } else if (grandTotal != null) {
                    totalPrice = double.tryParse(grandTotal.toString()) ?? 0;
