  /// ================= CUSTOMIZATION MODAL =================

  void _openCustomizationModal(
      Map<String, dynamic> product, GlobalKey imageKey) {
    int quantity = 1;

    final List<Map<String, dynamic>> selectedAddons = [];
    final List<Map<String, dynamic>> selectedSides = [];

    final TextEditingController noteController = TextEditingController();

    final double basePrice = _parsePrice(product['price']);
    final Map<String, dynamic>? productVendor = _findVendorForProduct(product);
    final bool vendorIsOpen =
        _isVendorOpen(productVendor ?? <String, dynamic>{});

    // ============================================================
    // PRODUCT FALLBACK IMAGE
    // ============================================================

    String getProductFallbackImage(Map<String, dynamic> product) {
      final category = (product['category'] ??
              product['productCategory'] ??
              product['type'] ??
              '')
          .toString()
          .trim()
          .toLowerCase();

      final Map<String, List<String>> categoryImages = {
        'drinks': [
          'assets/images/coke1.jpg',
          'assets/images/zobo.jpg',
          'assets/images/tigernut.jpg',
        ],
        'drink': [
          'assets/images/coke1.jpg',
          'assets/images/zobo.jpg',
          'assets/images/tigernut.jpg',
        ],
        'pizza': [
          'assets/images/pz1.jpg',
          'assets/images/pz2.jpg',
        ],
        'phagetti': [
          'assets/images/sp1.jpg',
          'assets/images/sp2.jpg',
          'assets/images/sp4.jpg',
        ],
        'spaghetti': [
          'assets/images/sp1.jpg',
          'assets/images/sp2.jpg',
          'assets/images/sp4.jpg',
        ],
        'shawarma': [
          'assets/images/sh1.jpg',
          'assets/images/sh2.jpg',
          'assets/images/sh3.jpg',
        ],
        'rice': [
          'assets/images/rice1.jpg',
          'assets/images/rice2.jpg',
          'assets/images/rice3.jpg',
          'assets/images/rice4.jpg',
        ],
        'poundo': [
          'assets/images/poundo.jpg',
        ],
      };

      final allFallbackImages = [
        'assets/images/sh1.jpg',
        'assets/images/sh2.jpg',
        'assets/images/sh3.jpg',
        'assets/images/pz1.jpg',
        'assets/images/pz2.jpg',
        'assets/images/rice1.jpg',
        'assets/images/rice2.jpg',
        'assets/images/rice3.jpg',
        'assets/images/rice4.jpg',
        'assets/images/poundo.jpg',
        'assets/images/sp1.jpg',
        'assets/images/sp2.jpg',
        'assets/images/sp4.jpg',
        'assets/images/sc.jpg',
        'assets/images/sc1.jpg',
        'assets/images/sc13.jpg',
        'assets/images/sc2.jpg',
        'assets/images/coke1.jpg',
        'assets/images/zobo.jpg',
        'assets/images/tigernut.jpg',
      ];

      final availableImages = categoryImages[category] ?? allFallbackImages;

      final productKey = (product['id'] ??
              product['productId'] ??
              product['name'] ??
              product['productName'] ??
              'product')
          .toString();

      final index = productKey.codeUnits.fold<int>(
            0,
            (sum, code) => sum + code,
          ) %
          availableImages.length;

      return availableImages[index];
    }

    // ============================================================
    // CONFIRM ADD-ON / SIDE
    // ============================================================

    Future<void> confirmAddOption({
      required Map<String, dynamic> item,
      required List<Map<String, dynamic>> selectedList,
      required StateSetter setModalState,
    }) async {
      final itemName = (item['name'] ?? 'This option').toString();

      final itemPrice = _parsePrice(item['price']);

      final bool? confirmed = await showDialog<bool>(
        context: context,
        barrierDismissible: true,
        builder: (dialogContext) {
          return AlertDialog(
            backgroundColor: Colors.white,
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(20),
            ),
            title: Row(
              children: [
                Container(
                  width: 40,
                  height: 40,
                  decoration: BoxDecoration(
                    color: Colors.black,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: const Icon(
                    Icons.add_shopping_cart_rounded,
                    color: Colors.white,
                    size: 20,
                  ),
                ),
                const SizedBox(width: 12),
                const Expanded(
                  child: Text(
                    'Add to order?',
                    style: TextStyle(
                      fontSize: 17,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
              ],
            ),
            content: Text(
              'Add "$itemName" to your order for '
              '₦${itemPrice.toStringAsFixed(0)}?',
              style: TextStyle(
                fontSize: 14,
                color: Colors.grey[700],
                height: 1.4,
              ),
            ),
            actionsPadding: const EdgeInsets.fromLTRB(16, 0, 16, 14),
            actions: [
              TextButton(
                onPressed: () {
                  Navigator.pop(dialogContext, false);
                },
                child: Text(
                  'Cancel',
                  style: TextStyle(
                    color: Colors.grey[700],
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ),
              ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.black,
                  foregroundColor: Colors.white,
                  elevation: 0,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
                onPressed: () {
                  Navigator.pop(dialogContext, true);
                },
                child: const Text(
                  'Add',
                  style: TextStyle(
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          );
        },
      );

      if (confirmed == true) {
        setModalState(() {
          if (!selectedList.contains(item)) {
            selectedList.add(item);
          }
        });
      }
    }

    // ============================================================
    // PRODUCT IMAGE
    // ============================================================

    Widget buildProductImage() {
      final rawImage = product['image'];

      final imageUrl = (rawImage ?? '').toString().trim().replaceAll('"', '');

      final fallbackImage = getProductFallbackImage(product);

      if (imageUrl.isEmpty) {
        return Image.asset(
          fallbackImage,
          width: 82,
          height: 82,
          fit: BoxFit.cover,
        );
      }

      return Image.network(
        imageUrl,
        width: 82,
        height: 82,
        fit: BoxFit.cover,
        loadingBuilder: (context, child, loadingProgress) {
          if (loadingProgress == null) {
            return child;
          }

          return Container(
            width: 82,
            height: 82,
            color: Colors.grey[200],
            child: _skeletonImage(),
          );
        },
        errorBuilder: (_, __, ___) {
          return Image.asset(
            fallbackImage,
            width: 82,
            height: 82,
            fit: BoxFit.cover,
          );
        },
      );
    }

    // ============================================================
    // MODAL
    // ============================================================

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withOpacity(0.55),
      builder: (_) {
        return StatefulBuilder(
          builder: (context, setModalState) {
            double total = basePrice;

            for (final addon in selectedAddons) {
              total += _parsePrice(addon['price']);
            }

            for (final side in selectedSides) {
              total += _parsePrice(side['price']);
            }

            total *= quantity;

            // ======================================================
            // OPTION CARD
            // ======================================================

            Widget buildOptionCard({
              required String title,
              required String subtitle,
              required List items,
              required List<Map<String, dynamic>> selectedList,
            }) {
              if (items.isEmpty) {
                return const SizedBox();
              }

              return Container(
                margin: const EdgeInsets.only(top: 12),
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(
                    color: Colors.grey[200]!,
                  ),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withOpacity(0.035),
                      blurRadius: 8,
                      offset: const Offset(0, 3),
                    ),
                  ],
                ),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                title,
                                style: const TextStyle(
                                  fontSize: 15,
                                  fontWeight: FontWeight.w700,
                                ),
                              ),
                              const SizedBox(height: 3),
                              Text(
                                subtitle,
                                style: TextStyle(
                                  fontSize: 11,
                                  color: Colors.grey[600],
                                ),
                              ),
                            ],
                          ),
                        ),
                        Container(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 8,
                            vertical: 4,
                          ),
                          decoration: BoxDecoration(
                            color: Colors.grey[100],
                            borderRadius: BorderRadius.circular(20),
                          ),
                          child: Text(
                            '${items.length} options',
                            style: TextStyle(
                              fontSize: 10,
                              color: Colors.grey[700],
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    Divider(
                      height: 1,
                      color: Colors.grey[200],
                    ),
                    const SizedBox(height: 8),
                    ...List.generate(
                      items.length,
                      (index) {
                        final item = items[index] as Map<String, dynamic>;

                        final isSelected = selectedList.contains(item);

                        final itemName = (item['name'] ?? 'Option').toString();

                        final itemPrice = _parsePrice(item['price']);

                        return GestureDetector(
                          onTap: () async {
                            if (isSelected) {
                              // Removing doesn't need confirmation.
                              setModalState(() {
                                selectedList.remove(item);
                              });
                            } else {
                              await confirmAddOption(
                                item: item,
                                selectedList: selectedList,
                                setModalState: setModalState,
                              );
                            }
                          },
                          child: AnimatedContainer(
                            duration: const Duration(milliseconds: 180),
                            margin: const EdgeInsets.only(bottom: 8),
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 10,
                            ),
                            decoration: BoxDecoration(
                              color:
                                  isSelected ? Colors.grey[100] : Colors.white,
                              borderRadius: BorderRadius.circular(12),
                              border: Border.all(
                                color: isSelected
                                    ? Colors.black
                                    : Colors.grey[200]!,
                              ),
                            ),
                            child: Row(
                              children: [
                                Expanded(
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        itemName,
                                        style: const TextStyle(
                                          fontSize: 13,
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                      const SizedBox(height: 3),
                                      Text(
                                        '+ ₦${itemPrice.toStringAsFixed(0)}',
                                        style: TextStyle(
                                          fontSize: 11,
                                          color: Colors.grey[700],
                                          fontWeight: FontWeight.w600,
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                                AnimatedContainer(
                                  duration: const Duration(milliseconds: 180),
                                  width: 32,
                                  height: 32,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: isSelected
                                        ? Colors.black
                                        : Colors.grey[100],
                                  ),
                                  child: Icon(
                                    isSelected ? Icons.check : Icons.add,
                                    size: 18,
                                    color: isSelected
                                        ? Colors.white
                                        : Colors.black,
                                  ),
                                ),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
                  ],
                ),
              );
            }

            // ======================================================
            // MODAL UI
            // ======================================================

            return Container(
              height: MediaQuery.of(context).size.height * 0.90,
              decoration: const BoxDecoration(
                color: Colors.grey,
                borderRadius: BorderRadius.vertical(
                  top: Radius.circular(28),
