class SearchingScreen extends StatefulWidget {
  final String rideType;
  final String pickupLocation;
  final String destination;

  // Exact coordinates passed from HomePage.
  final double pickupLat;
  final double pickupLng;
  final double destinationLat;
  final double destinationLng;

  final String userName;
  final VoidCallback onCancel;

  const SearchingScreen({
    Key? key,
    required this.rideType,
    required this.pickupLocation,
    required this.destination,
    required this.pickupLat,
    required this.pickupLng,
    required this.destinationLat,
    required this.destinationLng,
    required this.userName,
    required this.onCancel,
  }) : super(key: key);

  @override
  State<SearchingScreen> createState() => _SearchingScreenState();
}

class _SearchingScreenState extends State<SearchingScreen> {
  // ============================================================
  // RIDE REQUEST
  // ============================================================

  String? rideId;

  Stream<DocumentSnapshot>? rideStream;

  StreamSubscription<DocumentSnapshot>? _rideSubscription;

  // ============================================================
  // SEARCH TIMER
  // ============================================================

  Timer? timer;

  static const int searchDuration = 60;

  int remainingSeconds = searchDuration;

  int cycleCount = 0;

  // ============================================================
  // MAP
  // ============================================================

  GoogleMapController? _mapController;

  Set<Marker> _markers = {};

  bool _mapReady = false;

  // ============================================================
  // ROUTE LINE
  // ============================================================

  List<LatLng> _routePoints = [];

  Set<Polyline> _polylines = {};

  Timer? _routeAnimationTimer;

  bool _isLoadingRoute = false;

  // ============================================================
  // DESTINATION ICON
  // ============================================================

  BitmapDescriptor? _destinationIcon;

  // ============================================================
  // GOOGLE MAPS API KEY
  // ============================================================

  static const String _googlePlacesApiKey =
      "AIzaSyAxD8Gvtn1KGomBFy3pWXgvw0c4a-48";

  // ============================================================
  // RIDE TYPE IMAGE
  // ============================================================

  String getRideTypeImage(String rideType) {
    switch (rideType.toLowerCase()) {
      case 'cab':
        return 'assets/images/taxi.png';

      case 'bike':
        return 'assets/images/man.png';

      case 'tricycle':
        return 'assets/images/tricycle.png';

      default:
        return 'assets/images/man.png';
    }
  }

  // ============================================================
  // PICKUP COORDINATE
  // ============================================================

  LatLng get pickupLatLng {
    return LatLng(
      widget.pickupLat,
      widget.pickupLng,
    );
  }

  // ============================================================
  // DESTINATION COORDINATE
  // ============================================================

  LatLng get destinationLatLng {
    return LatLng(
      widget.destinationLat,
      widget.destinationLng,
    );
  }

  // ============================================================
  // CREATE SMALL ROUNDED RADIO DESTINATION ICON
  // ============================================================

  Future<BitmapDescriptor> _createDestinationIcon() async {
    const double size = 42;

    final ui.PictureRecorder recorder = ui.PictureRecorder();

    final Canvas canvas = Canvas(recorder);

    // ==========================================================
    // OUTER WHITE CIRCLE
    // ==========================================================

    final Paint outerPaint = Paint()
      ..color = Colors.white
      ..style = PaintingStyle.fill;

    canvas.drawCircle(
      const Offset(
        size / 2,
        size / 2,
      ),
      14,
      outerPaint,
    );

    // ==========================================================
    // GREEN BORDER
    // ==========================================================

    final Paint borderPaint = Paint()
      ..color = Colors.green.shade700
      ..style = PaintingStyle.stroke
      ..strokeWidth = 3;

    canvas.drawCircle(
      const Offset(
        size / 2,
        size / 2,
      ),
      12,
      borderPaint,
    );

    // ==========================================================
    // SMALL GREEN CENTER
    // ==========================================================

    final Paint centerPaint = Paint()
      ..color = Colors.green.shade700
      ..style = PaintingStyle.fill;

    canvas.drawCircle(
      const Offset(
        size / 2,
        size / 2,
      ),
      5,
      centerPaint,
    );

    final ui.Image image = await recorder.endRecording().toImage(
          size.toInt(),
          size.toInt(),
        );

    final ByteData? byteData = await image.toByteData(
      format: ui.ImageByteFormat.png,
    );

    if (byteData == null) {
      return BitmapDescriptor.defaultMarkerWithHue(
        BitmapDescriptor.hueGreen,
      );
    }

    return BitmapDescriptor.fromBytes(
      byteData.buffer.asUint8List(),
    );
  }

  // ============================================================
  // GET GOOGLE ROAD ROUTE
  // ============================================================

  Future<List<LatLng>> _getRoutePoints(
    LatLng pickup,
    LatLng destination,
  ) async {
    try {
      final response = await http.post(
        Uri.parse(
          'https://routes.googleapis.com/directions/v2:computeRoutes',
        ),
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': _googlePlacesApiKey,
          'X-Goog-FieldMask': 'routes.polyline.geoJsonLinestring',
        },
        body: jsonEncode({
          'origin': {
            'location': {
              'latLng': {
                'latitude': pickup.latitude,
                'longitude': pickup.longitude,
              },
            },
          },
          'destination': {
            'location': {
              'latLng': {
                'latitude': destination.latitude,
                'longitude': destination.longitude,
              },
            },
          },
          'travelMode': 'DRIVE',
          'routingPreference': 'TRAFFIC_AWARE',
          'computeAlternativeRoutes': false,
          'polylineQuality': 'HIGH_QUALITY',
          'polylineEncoding': 'GEO_JSON_LINESTRING',
        }),
      );

      debugPrint(
        'SEARCHING ROUTES STATUS: ${response.statusCode}',
      );

      if (response.statusCode != 200) {
        debugPrint(
          'SEARCHING ROUTES ERROR: ${response.body}',
        );

        return [];
      }

      final Map<String, dynamic> data = jsonDecode(response.body);

      final List routes = data['routes'] ?? [];

      if (routes.isEmpty) {
        debugPrint(
          'SEARCHING SCREEN: NO ROUTE FOUND',
        );

        return [];
      }

      final dynamic geometry = routes.first['polyline']?['geoJsonLinestring'];

      if (geometry == null) {
        debugPrint(
          'SEARCHING SCREEN: NO GEOJSON ROUTE RETURNED',
        );

        return [];
      }

      final List coordinates = geometry['coordinates'] ?? [];

      if (coordinates.length < 2) {
        debugPrint(
          'SEARCHING SCREEN: ROUTE HAS TOO FEW POINTS',
        );

        return [];
      }

      final List<LatLng> points = [];

      for (final dynamic coordinate in coordinates) {
        if (coordinate is! List || coordinate.length < 2) {
          continue;
        }

        // ======================================================
        // IMPORTANT:
        //
        // GeoJSON:
        //
        // [longitude, latitude]
        //
        // Google Maps:
        //
        // LatLng(latitude, longitude)
        // ======================================================

        final double? longitude = (coordinate[0] as num?)?.toDouble();

        final double? latitude = (coordinate[1] as num?)?.toDouble();

        if (latitude == null || longitude == null) {
          continue;
        }

        points.add(
          LatLng(
            latitude,
            longitude,
          ),
        );
      }

      if (points.length < 2) {
        debugPrint(
          'SEARCHING SCREEN: DECODED ROUTE TOO SHORT',
        );

        return [];
      }

      // ======================================================
      // FORCE EXACT PICKUP + DESTINATION
      // ======================================================

      points[0] = pickup;

      points[points.length - 1] = destination;

      debugPrint(
        'SEARCHING SCREEN ROUTE POINTS: '
        '${points.length}',
      );

      debugPrint(
        'SEARCHING SCREEN ROUTE START: '
        '${points.first.latitude}, '
        '${points.first.longitude}',
      );

      debugPrint(
        'SEARCHING SCREEN ROUTE END: '
        '${points.last.latitude}, '
        '${points.last.longitude}',
      );

      return points;
    } catch (e) {
      debugPrint(
        'SEARCHING SCREEN GET ROUTE ERROR: $e',
      );

      return [];
    }
  }

  // ============================================================
  // DRAW ANIMATED GREEN ROUTE
  // ============================================================

  Future<void> _drawAnimatedRoute() async {
    final LatLng pickup = pickupLatLng;

    final LatLng destination = destinationLatLng;

    _routeAnimationTimer?.cancel();

    if (!mounted) return;

    setState(() {
      _isLoadingRoute = true;
      _routePoints = [];
      _polylines = {};
    });

    final List<LatLng> points = await _getRoutePoints(
      pickup,
      destination,
    );

    if (!mounted) return;

    if (points.length < 2) {
      setState(() {
        _isLoadingRoute = false;
      });

      return;
    }

    _routePoints = points;

    setState(() {
      _isLoadingRoute = false;
    });

    // ========================================================
    // FIT MAP TO ACTUAL ROAD ROUTE
    // ========================================================

    await _fitActualRouteOnMap();

    if (!mounted) return;

    // ========================================================
    // START ROUTE WITH FIRST TWO POINTS
    // ========================================================

    int visiblePoints = 2;

    setState(() {
      _polylines = {
        Polyline(
          polylineId: const PolylineId(
            'ride_route',
          ),
          points: _routePoints.take(visiblePoints).toList(),
          color: Colors.green,
          width: 5,
          geodesic: false,
          jointType: JointType.round,
          startCap: Cap.roundCap,
          endCap: Cap.roundCap,
        ),
      };
    });

    // ========================================================
    // ANIMATE ROUTE LINE
    // ========================================================

    _routeAnimationTimer = Timer.periodic(
      const Duration(
        milliseconds: 25,
      ),
      (timer) {
        if (!mounted) {
          timer.cancel();
          return;
        }

        if (visiblePoints >= _routePoints.length) {
          timer.cancel();

          setState(() {
            _polylines = {
              Polyline(
                polylineId: const PolylineId(
                  'ride_route',
                ),
                points: List<LatLng>.from(
                  _routePoints,
                ),
                color: Colors.green,
                width: 5,
                geodesic: false,
                jointType: JointType.round,
                startCap: Cap.roundCap,
                endCap: Cap.roundCap,
              ),
            };
          });

          return;
        }

        // ====================================================
        // CONTROL ANIMATION SPEED
        // ====================================================

        int step = (_routePoints.length / 100).ceil();

        if (step < 1) {
          step = 1;
        }

        if (step > 8) {
          step = 8;
        }

        visiblePoints += step;

        if (visiblePoints > _routePoints.length) {
          visiblePoints = _routePoints.length;
        }

        setState(() {
          _polylines = {
            Polyline(
              polylineId: const PolylineId(
                'ride_route',
              ),
              points: _routePoints.take(visiblePoints).toList(),
              color: Colors.green,
              width: 5,
              geodesic: false,
              jointType: JointType.round,
              startCap: Cap.roundCap,
              endCap: Cap.roundCap,
            ),
          };
        });
      },
    );
  }

  // ============================================================
  // FIT CAMERA TO ACTUAL ROAD ROUTE
  // ============================================================

  Future<void> _fitActualRouteOnMap() async {
    if (_mapController == null || _routePoints.isEmpty) {
      return;
    }

    double minLat = _routePoints.first.latitude;

    double maxLat = _routePoints.first.latitude;

    double minLng = _routePoints.first.longitude;

    double maxLng = _routePoints.first.longitude;

    for (final LatLng point in _routePoints) {
      if (point.latitude < minLat) {
        minLat = point.latitude;
      }

      if (point.latitude > maxLat) {
        maxLat = point.latitude;
      }

      if (point.longitude < minLng) {
        minLng = point.longitude;
      }

      if (point.longitude > maxLng) {
        maxLng = point.longitude;
      }
    }

    // ========================================================
    // PREVENT ZERO-SIZE BOUNDS
    // ========================================================

    if ((maxLat - minLat).abs() < 0.001) {
      minLat -= 0.001;
      maxLat += 0.001;
    }

    if ((maxLng - minLng).abs() < 0.001) {
      minLng -= 0.001;
      maxLng += 0.001;
    }

    try {
      await _mapController!.animateCamera(
        CameraUpdate.newLatLngBounds(
          LatLngBounds(
            southwest: LatLng(
              minLat,
              minLng,
            ),
            northeast: LatLng(
              maxLat,
              maxLng,
            ),
          ),
          70,
        ),
      );
    } catch (e) {
      debugPrint(
        'SEARCHING SCREEN FIT ROUTE ERROR: $e',
      );
    }
  }

  // ============================================================
  // CREATE FIRESTORE RIDE REQUEST
  // ============================================================

  Future<void> _createRideRequest() async {
    try {
      final requestDoc =
          await FirebaseFirestore.instance.collection('ride_requests').add({
        'RideType': widget.rideType,
        'Status': 'pending',
        'Time': FieldValue.serverTimestamp(),
        'Pickup Location': widget.pickupLocation,
        'Destination': widget.destination,
        'pickupLat': widget.pickupLat,
        'pickupLng': widget.pickupLng,
        'destinationLat': widget.destinationLat,
        'destinationLng': widget.destinationLng,
        'userName': widget.userName,
        'DriverStatus': "driver_booked",
        'Code': "8492",
      });

      if (!mounted) return;

      rideId = requestDoc.id;

      // ========================================================
      // START LISTENING ONLY AFTER DOCUMENT EXISTS
      // ========================================================

      rideStream = requestDoc.snapshots();

      _rideSubscription = rideStream!.listen(
        _handleRideUpdate,
      );

      debugPrint(
        "Ride request created: ${requestDoc.id}",
      );
    } catch (e) {
      debugPrint(
        "Error creating ride request: $e",
      );

      if (!mounted) return;

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            "Unable to start ride search. Please try again.",
          ),
        ),
      );
    }
  }

  // ============================================================
  // HANDLE FIRESTORE RIDE UPDATE
  // ============================================================

  void _handleRideUpdate(
    DocumentSnapshot snapshot,
  ) {
    final data = snapshot.data() as Map<String, dynamic>?;

    if (data == null) return;

    // ==========================================================
    // DRIVER ACCEPTED
    // ==========================================================

    if (data['Status'] == 'driver_accepted') {
      timer?.cancel();

      final currentRideId = rideId;

      if (currentRideId == null) {
        return;
      }

      _rideSubscription?.cancel();

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (_) => DriverOfferScreen(
            rideId: currentRideId,
            driverName: data['driverId'],
            price: (data['price'] as num).toDouble(),
            vehicleType: data['vehicleType'],
            vehicleDescription: data['vehicleType'],
            pickup: data['Pickup Location'],
            destination: data['Destination'],
            rideType: data['RideType'],

            // ==========================================================
            // PASS EXACT COORDINATES
            // ==========================================================

            pickupLat: widget.pickupLat,
            pickupLng: widget.pickupLng,
            destinationLat: widget.destinationLat,
            destinationLng: widget.destinationLng,
          ),
        ),
      );
    }
  }

  // ============================================================
  // SEARCH TIMER
  // ============================================================

  void startTimerLoop() {
    timer?.cancel();

    if (!mounted) return;

    setState(() {
      remainingSeconds = searchDuration;
    });

    timer = Timer.periodic(
      const Duration(seconds: 1),
      (timer) {
        if (!mounted) {
          timer.cancel();
          return;
        }

        setState(() {
          remainingSeconds--;

          // ====================================================
          // CURRENT SEARCH CYCLE FINISHED
          // ====================================================

          if (remainingSeconds <= 0) {
            timer.cancel();

            cycleCount++;

            // Keep original two-cycle behavior.
            if (cycleCount < 2) {
              startTimerLoop();
            } else {
              _handleSearchTimeout();
            }
          }
        });
      },
    );
  }

  // ============================================================
  // SEARCH TIMEOUT
  // ============================================================

  Future<void> _handleSearchTimeout() async {
    timer?.cancel();

    await _cancelRideRequest();

    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text(
          'Unable to find a driver. Please try again.',
        ),
      ),
    );

    widget.onCancel();
  }

  // ============================================================
  // CANCEL FIRESTORE REQUEST
  // ============================================================

  Future<void> _cancelRideRequest() async {
    timer?.cancel();

    final currentRideId = rideId;

    if (currentRideId == null) {
      return;
    }

    try {
      await FirebaseFirestore.instance
          .collection('ride_requests')
          .doc(currentRideId)
          .update({
        'Status': 'cancelled',
      });
    } catch (e) {
      debugPrint(
        "Error cancelling ride request: $e",
      );
    }

    _rideSubscription?.cancel();
  }

  // ============================================================
  // CREATE PICKUP + DESTINATION MARKERS
  // ============================================================

  Future<void> _setRouteMarkers() async {
    final pickup = pickupLatLng;

    final destination = destinationLatLng;

    // ==========================================================
    // CREATE DESTINATION RADIO ICON
    // ==========================================================

    _destinationIcon ??= await _createDestinationIcon();

    if (!mounted) return;

    final markers = <Marker>{};

    // ==========================================================
    // PICKUP MARKER
    // ==========================================================

    markers.add(
      Marker(
        markerId: const MarkerId(
          'pickup',
        ),
        position: pickup,
        icon: BitmapDescriptor.defaultMarkerWithHue(
          BitmapDescriptor.hueBlue,
        ),
        infoWindow: InfoWindow(
          title: 'Pickup',
          snippet: widget.pickupLocation,
        ),
      ),
    );

    // ==========================================================
    // DESTINATION RADIO MARKER
    // ==========================================================

    markers.add(
      Marker(
        markerId: const MarkerId(
          'destination',
        ),
        position: destination,
        icon: _destinationIcon!,
        infoWindow: InfoWindow(
          title: 'Destination',
          snippet: widget.destination,
        ),
        anchor: const Offset(
          0.5,
          0.5,
        ),
      ),
    );

    setState(() {
      _markers = markers;
    });
  }

  // ============================================================
  // FIT PICKUP + DESTINATION ON MAP
  // ============================================================

  Future<void> _fitRouteOnMap() async {
    if (_mapController == null) {
      return;
    }

    final pickup = pickupLatLng;

    final destination = destinationLatLng;

    final double southWestLat = pickup.latitude < destination.latitude
        ? pickup.latitude
        : destination.latitude;

    final double southWestLng = pickup.longitude < destination.longitude
        ? pickup.longitude
        : destination.longitude;

    final double northEastLat = pickup.latitude > destination.latitude
        ? pickup.latitude
        : destination.latitude;

    final double northEastLng = pickup.longitude > destination.longitude
        ? pickup.longitude
        : destination.longitude;

    // ==========================================================
    // IDENTICAL COORDINATES
    // ==========================================================

    if (southWestLat == northEastLat && southWestLng == northEastLng) {
      await _mapController!.animateCamera(
        CameraUpdate.newCameraPosition(
          CameraPosition(
            target: pickup,
            zoom: 16,
          ),
        ),
      );

      return;
    }

    final bounds = LatLngBounds(
      southwest: LatLng(
        southWestLat,
        southWestLng,
      ),
      northeast: LatLng(
        northEastLat,
        northEastLng,
      ),
    );

    try {
      await _mapController!.animateCamera(
        CameraUpdate.newLatLngBounds(
          bounds,
          80,
        ),
      );
    } catch (e) {
      debugPrint(
        "Error fitting route on map: $e",
      );
    }
  }

  // ============================================================
  // MAP CREATED
  // ============================================================

  void _onMapCreated(
    GoogleMapController controller,
  ) {
    _mapController = controller;

    _mapReady = true;

    // ==========================================================
    // SHOW BOTH LOCATIONS
    // ==========================================================

    _setRouteMarkers();

    // ==========================================================
    // DRAW ACTUAL ROAD ROUTE
    // ==========================================================

    _drawAnimatedRoute();
  }

  // ============================================================
  // FORMAT COUNTDOWN
  // ============================================================

  String _formatRemainingTime() {
    final int minutes = remainingSeconds ~/ 60;

    final int seconds = remainingSeconds % 60;

    return "$minutes:${seconds.toString().padLeft(2, '0')}";
  }

  // ============================================================
  // CIRCULAR SEARCH COUNTDOWN
  // ============================================================

  Widget _buildSearchCountdown() {
    final double progress = remainingSeconds / searchDuration;

    return SizedBox(
      width: 28,
      height: 28,
      child: Stack(
        alignment: Alignment.center,
        children: [
          // ======================================================
          // BACKGROUND RING
          // ======================================================

          SizedBox(
            width: 28,
            height: 28,
            child: CircularProgressIndicator(
              value: 1,
              strokeWidth: 3,
              backgroundColor: Colors.grey.shade200,
              valueColor: AlwaysStoppedAnimation<Color>(
                Colors.grey.shade200,
              ),
            ),
          ),

          // ======================================================
          // COUNTDOWN RING
          // ======================================================

          SizedBox(
            width: 28,
            height: 28,
            child: CircularProgressIndicator(
              value: progress,
              strokeWidth: 3,
              strokeCap: StrokeCap.round,
              valueColor: const AlwaysStoppedAnimation<Color>(
                Colors.black,
              ),
            ),
          ),

          // ======================================================
          // TIME
          // ======================================================

          Text(
            "$remainingSeconds",
            style: const TextStyle(
              fontSize: 7,
              fontWeight: FontWeight.bold,
              color: Colors.black,
            ),
          ),
        ],
      ),
    );
  }

  // ============================================================
  // INIT
  // ============================================================

  @override
  void initState() {
    super.initState();

    // ==========================================================
    // IMPORTANT:
    //
    // We already have pickup + destination coordinates.
    //
    // Do NOT fetch GPS again.
    // ==========================================================

    _setRouteMarkers();

    // ==========================================================
    // START VISUAL SEARCH TIMER
    // ==========================================================

    startTimerLoop();

    // ==========================================================
    // CREATE FIRESTORE REQUEST ASYNCHRONOUSLY
    //
    // The map does not wait for this.
    // ==========================================================

    _createRideRequest();
  }

  // ============================================================
  // DISPOSE
  // ============================================================

  @override
  void dispose() {
    timer?.cancel();

    _routeAnimationTimer?.cancel();

    _rideSubscription?.cancel();

    _mapController?.dispose();

    super.dispose();
  }

