  Widget _buildInfo(String label, String value) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 6),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text("$label: ", style: const TextStyle(fontWeight: FontWeight.bold)),
          Expanded(child: Text(value, softWrap: true)),
        ],
      ),
    );
  }
}

enum SenderCategory {
  business,
  personal,
}

class LogisticsEntryPage extends StatefulWidget {
  final String serviceType;

  const LogisticsEntryPage({
    Key? key,
    required this.serviceType,
  }) : super(key: key);

  @override
  State<LogisticsEntryPage> createState() => _LogisticsEntryPageState();
}

class _LogisticsEntryPageState extends State<LogisticsEntryPage>
    with SingleTickerProviderStateMixin {
  bool _checkingUser = true;

  SenderCategory? _selectedCategory;

  @override
  void initState() {
    super.initState();
    _checkUserStatus();
  }

  Future<void> _checkUserStatus() async {
    final uid = FirebaseAuth.instance.currentUser!.uid;

    try {
      final doc = await FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .collection('logistics')
          .doc('profile')
          .get();

      if (!mounted) return;

      if (doc.exists) {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (_) => PackageDetailsPage(
              serviceType: widget.serviceType,
            ),
          ),
        );

        return;
      }

      setState(() {
        _checkingUser = false;
      });
    } catch (e) {
      setState(() {
        _checkingUser = false;
      });
    }
  }

  Future<void> _continue() async {
    if (_selectedCategory == null) return;

    try {
      final uid = FirebaseAuth.instance.currentUser!.uid;

      await FirebaseFirestore.instance
          .collection("users")
          .doc(uid)
          .collection("logistics")
          .doc("profile")
          .set({
        "senderType": _selectedCategory == SenderCategory.business
            ? "business"
            : "personal",
        "createdAt": FieldValue.serverTimestamp(),
      });

      if (!mounted) return;

      if (_selectedCategory == SenderCategory.business) {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => BusinessDetailsPage(
              serviceType: widget.serviceType,
            ),
          ),
        );
      } else {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (_) => PackageDetailsPage(
              serviceType: widget.serviceType,
            ),
          ),
        );
      }
    } catch (e) {
      debugPrint("Logistics onboarding error: $e");

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString())),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_checkingUser) {
      return const Scaffold(
        backgroundColor: Colors.white,
        body: Center(
          child: CircularProgressIndicator(
            color: Colors.black,
          ),
        ),
      );
    }

    return Scaffold(
      backgroundColor: Colors.white,
      body: SafeArea(
        child: Padding(
          padding: const EdgeInsets.symmetric(
            horizontal: 22,
            vertical: 18,
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              GestureDetector(
                onTap: () => Navigator.pop(context),
                child: Container(
                  width: 38,
                  height: 38,
                  decoration: BoxDecoration(
                    color: Colors.grey.shade100,
                    shape: BoxShape.circle,
                  ),
                  child: const Icon(
                    Icons.arrow_back_ios_new_rounded,
                    size: 18,
                  ),
                ),
              ),
              const SizedBox(height: 35),
              const Text(
                "Select your category",
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.bold,
                ),
              ),
              const SizedBox(height: 10),
              Text(
                "Select your category to get a tailored experience according to your needs.",
                style: TextStyle(
                  fontSize: 15,
                  color: Colors.grey.shade700,
                  height: 1.5,
                ),
              ),
              const SizedBox(height: 35),
              _categoryCard(
                title: "Business",
                description:
                    "Perfect for businesses, online stores and SMEs that send packages regularly.",
                icon: Icons.business_center_rounded,
                accentColor: Colors.deepPurple,
                selected: _selectedCategory == SenderCategory.business,
                onTap: () {
                  setState(() {
                    _selectedCategory = SenderCategory.business;
                  });
                },
              ),
              const SizedBox(height: 18),
              _categoryCard(
                title: "Personal",
                description:
                    "For personal deliveries to family, friends or occasional customers.",
                icon: Icons.person_outline_rounded,
                accentColor: Colors.green,
                selected: _selectedCategory == SenderCategory.personal,
                onTap: () {
