  Future<void> _loadStates() async {
    try {
      final states = await LocationService.getStates();

      if (!mounted) return;

      setState(() {
        _states = states;
        _loadingStates = false;
      });
    } catch (e) {
      if (!mounted) return;

      setState(() {
        _loadingStates = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(e.toString())),
