                  const SizedBox(height: 18),
                  _loadingStates
                      ? const Center(
                          child: CircularProgressIndicator(
                            color: Colors.black,
                          ),
                        )
                      : _stateDropdown(),
                  const SizedBox(height: 18),
                  _loadingLocations
                      ? const Center(
                          child: Padding(
                            padding: EdgeInsets.symmetric(vertical: 20),
                            child: CircularProgressIndicator(
                              color: Colors.black,
