class DeliveryAgentPage extends StatelessWidget {
  const DeliveryAgentPage({super.key});

  Future<void> acceptRequest(BuildContext context, String requestId) async {
    final currentUser = FirebaseAuth.instance.currentUser;
    if (currentUser == null) return;

    final driverDoc = await FirebaseFirestore.instance
        .collection('Drivers')
        .doc(currentUser.uid)
        .get();

    final driverName = driverDoc.data()?['name'] ?? 'Unknown';

    await FirebaseFirestore.instance
        .collection('logistics_requests')
        .doc(requestId)
        .update({
      'status': 'accepted',
      'assignedAgent': currentUser.uid,
      'driverName': driverName,
      'assignedAt': FieldValue.serverTimestamp(),
    });

    // IMPORTANT: ensure navigation works properly
    if (!context.mounted) return;

    Navigator.push(
      context,
      MaterialPageRoute(
        builder: (_) => LogisticsDeliveryPage(requestId: requestId),
      ),
    );
  }

  Widget _buildOrdersStream(
    BuildContext context, {
    required List<String> statuses,
    required User currentUser,
    bool showAccept = false,
  }) {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection('logistics_requests')
          .where('status', whereIn: statuses)
          .snapshots(),
      builder: (context, snapshot) {
        if (!snapshot.hasData) {
          return const Center(child: CircularProgressIndicator());
        }

        final docs = snapshot.data!.docs;

        if (docs.isEmpty) {
          return const Center(child: Text("No orders found"));
        }

        return ListView.builder(
          itemCount: docs.length,
          itemBuilder: (context, index) {
            final doc = docs[index];
            final data = doc.data() as Map<String, dynamic>;
            final status = data['status'];

            return GestureDetector(
              onTap: () {
                // 🔥 NAVIGATION LOGIC
                if (status == "pickedup") {
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => DeliveryCodePage(requestId: doc.id),
                    ),
                  );
                } else if (status == "accepted") {
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => LogisticsDeliveryPage(requestId: doc.id),
                    ),
                  );
                } else if (status == "completed") {
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                      builder: (_) => OrderPlacedPage(orderId: doc.id),
                    ),
                  );
                }
              },
              child: Card(
                margin: const EdgeInsets.all(12),
                child: Padding(
                  padding: const EdgeInsets.all(12),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        data['packageName'] ?? '',
                        style: const TextStyle(fontWeight: FontWeight.bold),
                      ),
                      const SizedBox(height: 6),
                      Text("Pickup: ${data['pickupAddress'] ?? ''}"),
                      Text("Delivery: ${data['deliveryAddress'] ?? ''}"),
                      Text("Price: ₦${data['price'] ?? 0}"),
                      Text("Status: $status"),
                      const SizedBox(height: 10),
                      if (showAccept)
                        ElevatedButton(
                          onPressed: () async {
                            await acceptRequest(context, doc.id);
                          },
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.black,
                          ),
                          child: const Text("Accept Order"),
                        ),
                    ],
                  ),
                ),
              ),
            );
          },
        );
      },
    );
  }

  String formatCurrency(dynamic amount) {
    double val = 0;
    if (amount != null) {
      val = double.tryParse(amount.toString()) ?? 0;
    }
    final format = NumberFormat.currency(locale: "en_NG", symbol: "₦");
    return format.format(val);
  }

  @override
  Widget build(BuildContext context) {
    final currentUser = FirebaseAuth.instance.currentUser;

    return DefaultTabController(
      length: 3,
      child: Scaffold(
        backgroundColor: Colors.white,
        appBar: AppBar(
          backgroundColor: Colors.white,
          elevation: 0,
          leading: Padding(
            padding: const EdgeInsets.only(left: 10),
            child: GestureDetector(
              onTap: () => Navigator.pop(context),
              child: Container(
                decoration: BoxDecoration(
                  color: Colors.grey[100],
                  shape: BoxShape.circle,
                ),
                child: const Icon(Icons.arrow_back_ios, size: 14),
              ),
            ),
          ),
          title: const Text(
            "Partner",
            style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold),
          ),
          bottom: const TabBar(
            labelColor: Colors.black,
            indicatorColor: Colors.black,
            tabs: [
              Tab(text: "New"),
              Tab(text: "Pending"),
              Tab(text: "Completed"),
            ],
          ),
        ),
        body: currentUser == null
            ? const Center(child: Text("Not logged in"))
            : Column(
                children: [
                  // ================= DRIVER STATS =================
                  StreamBuilder<DocumentSnapshot>(
                    stream: FirebaseFirestore.instance
                        .collection('Drivers')
                        .doc(currentUser.uid)
                        .snapshots(),
                    builder: (context, driverSnapshot) {
                      if (!driverSnapshot.hasData) {
                        return const SizedBox(
                          height: 120,
                          child: Center(child: CircularProgressIndicator()),
                        );
                      }

                      final driverData = driverSnapshot.data!.data()
                              as Map<String, dynamic>? ??
                          {};

                      return StreamBuilder<QuerySnapshot>(
                        stream: FirebaseFirestore.instance
                            .collection('logistics_requests')
                            .where('assignedAgent', isEqualTo: currentUser.uid)
                            .snapshots(),
                        builder: (context, requestSnapshot) {
                          int totalDeliveries = 0;
                          double totalEarnings = 0;

                          if (requestSnapshot.hasData) {
                            final docs = requestSnapshot.data!.docs;
                            totalDeliveries = docs.length;

                            for (var doc in docs) {
                              final data = doc.data() as Map<String, dynamic>;
                              totalEarnings += double.tryParse(
                                      data['price']?.toString() ?? '0') ??
                                  0;
                            }
                          }

                          return Card(
                            margin: const EdgeInsets.all(16),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(16),
                            ),
                            child: Padding(
                              padding: const EdgeInsets.all(16),
                              child: Row(
                                children: [
                                  CircleAvatar(
                                    radius: 35,
                                    backgroundImage: driverData['photoUrl'] !=
                                            null
                                        ? NetworkImage(driverData['photoUrl'])
                                        : null,
                                    child: driverData['photoUrl'] == null
                                        ? const Icon(Icons.person)
                                        : null,
                                  ),
                                  const SizedBox(width: 15),
                                  Expanded(
                                    child: Column(
                                      crossAxisAlignment:
                                          CrossAxisAlignment.start,
                                      children: [
                                        Text(
                                          driverData['name'] ?? "Driver",
                                          style: const TextStyle(
                                            fontSize: 16,
                                            fontWeight: FontWeight.bold,
                                          ),
                                        ),
                                        const SizedBox(height: 10),
                                        Text("Deliveries: $totalDeliveries"),
                                        Text(
                                            "Earnings: ₦${totalEarnings.toStringAsFixed(0)}"),
                                      ],
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          );
                        },
                      );
                    },
                  ),

                  // ================= TABS =================
                  Expanded(
                    child: TabBarView(
                      children: [
                        // 🔹 NEW
                        _buildOrdersStream(
                          context,
                          statuses: ['pending'],
                          showAccept: true,
                          currentUser: currentUser,
                        ),

                        // 🔹 PENDING (accepted + picked_up)
                        _buildOrdersStream(
                          context,
                          statuses: ['accepted', 'pickedup'],
                          currentUser: currentUser,
                        ),

                        // 🔹 COMPLETED
                        _buildOrdersStream(
                          context,
                          statuses: ['completed'],
                          currentUser: currentUser,
                        ),
                      ],
                    ),
                  ),
                ],
              ),
      ),
    );
  }
}

class DispatchOnboarding extends StatefulWidget {
  const DispatchOnboarding({Key? key}) : super(key: key);

  @override
  State<DispatchOnboarding> createState() => _DispatchOnboardingState();
}

class _DispatchOnboardingState extends State<DispatchOnboarding> {
  final TextEditingController riderName = TextEditingController();
  final TextEditingController riderPhone = TextEditingController();
  final TextEditingController riderEmail = TextEditingController();
  final TextEditingController riderNIN = TextEditingController();

  final TextEditingController vehicleName = TextEditingController();
  final TextEditingController vehicleType = TextEditingController();
  final TextEditingController vehicleModel = TextEditingController();

  XFile? riderImage;
  XFile? vehicleImage;
  final ImagePicker _picker = ImagePicker();

  bool loading = false;

  Future<void> pickRiderImage() async {
    riderImage = await _picker.pickImage(source: ImageSource.gallery);
    setState(() {});
  }

  Future<void> pickVehicleImage() async {
    vehicleImage = await _picker.pickImage(source: ImageSource.gallery);
    setState(() {});
  }

  Future<void> saveData() async {
    if (riderName.text.isEmpty ||
        riderPhone.text.isEmpty ||
        riderEmail.text.isEmpty ||
        riderNIN.text.isEmpty ||
        vehicleName.text.isEmpty ||
        vehicleType.text.isEmpty ||
        vehicleModel.text.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text("Please fill all fields")),
      );
      return;
    }

    setState(() => loading = true);

    try {
      final uid = FirebaseAuth.instance.currentUser!.uid;
      await FirebaseFirestore.instance
          .collection('dispatch_riders')
          .doc(uid)
          .set({
        "riderName": riderName.text.trim(),
        "riderPhone": riderPhone.text.trim(),
        "riderEmail": riderEmail.text.trim(),
        "riderNIN": riderNIN.text.trim(),
        "vehicleName": vehicleName.text.trim(),
        "vehicleType": vehicleType.text.trim(),
        "vehicleModel": vehicleModel.text.trim(),
        "status": "pending_verification",
        "createdAt": FieldValue.serverTimestamp(),
      });

      if (!mounted) return;
      Navigator.push(
        context,
        MaterialPageRoute(builder: (context) => const DispatchDashboardPage()),
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text("Error: $e")),
      );
    }

    setState(() => loading = false);
  }

  Widget buildImageUpload(String label, Function() pickImage, XFile? file) {
    return GestureDetector(
      onTap: pickImage,
      child: Container(
        height: 110,
        width: double.infinity,
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(12),
          border: Border.all(color: Colors.deepPurple),
        ),
        child: file == null
            ? Center(child: Text("Upload $label"))
            : ClipRRect(
                borderRadius: BorderRadius.circular(12),
                child: kIsWeb
                    ? Image.network(
                        file.path,
                        fit: BoxFit.cover,
                      )
                    : Image.file(
                        File(file.path),
                        fit: BoxFit.cover,
                      ),
              ),
      ),
    );
  }

  Widget buildTextField(String label, TextEditingController controller) {
    return TextField(
      controller: controller,
      decoration:
          InputDecoration(labelText: label, border: const OutlineInputBorder()),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.grey.shade100,
      appBar: AppBar(
        //automaticallyImplyLeading: false, // 👈 turn this off since we customize it
        backgroundColor: Colors.white,
        elevation: 0,

        leading: Padding(
          padding: const EdgeInsets.only(left: 10),
          child: GestureDetector(
            onTap: () => Navigator.pop(context),
            child: Container(
              width: 25,
              height: 25,
              decoration: BoxDecoration(
                color: Colors.grey[100], // ✅ grey 50 look
                shape: BoxShape.circle,
              ),
              child: const Icon(
                Icons.arrow_back_ios,
                size: 14,
                color: Colors.black,
              ),
            ),
          ),
        ),

        title: const Padding(
          padding: EdgeInsets.only(left: 8), // ✅ spacing from icon
          child: Text(
            'Onboarding',
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.bold,
              color: Colors.black,
            ),
          ),
        ),
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            /// ------- PERSONAL DETAILS CARD -------
            Card(
              elevation: 3,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(15)),
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text("Personal Details",
                        style: TextStyle(
                            fontSize: 18, fontWeight: FontWeight.bold)),
                    const SizedBox(height: 15),
                    buildImageUpload(
                        "Rider Picture", pickRiderImage, riderImage),
                    const SizedBox(height: 15),
                    buildTextField("Full Name", riderName),
                    const SizedBox(height: 10),
                    buildTextField("Phone Number", riderPhone),
                    const SizedBox(height: 10),
                    buildTextField("Email Address", riderEmail),
                    const SizedBox(height: 10),
                    buildTextField("NIN Number", riderNIN),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 20),

            /// ------- VEHICLE DETAILS CARD -------
            Card(
              elevation: 3,
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(15)),
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text("Vehicle Details",
                        style: TextStyle(
                            fontSize: 18, fontWeight: FontWeight.bold)),
                    const SizedBox(height: 15),
                    buildImageUpload(
                        "Vehicle Image", pickVehicleImage, vehicleImage),
                    const SizedBox(height: 15),
                    buildTextField("Vehicle Name", vehicleName),
                    const SizedBox(height: 10),
                    buildTextField("Vehicle Type (Bike/Car/etc)", vehicleType),
                    const SizedBox(height: 10),
                    buildTextField("Vehicle Model", vehicleModel),
                  ],
                ),
              ),
            ),

            const SizedBox(height: 25),

            /// ------- SUBMIT BUTTON -------
            ElevatedButton(
              style: ElevatedButton.styleFrom(
                padding:
                    const EdgeInsets.symmetric(vertical: 15, horizontal: 120),
                shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(30)),
                backgroundColor: Colors.deepPurple,
              ),
              onPressed: loading ? null : saveData,
              child: loading
                  ? const CircularProgressIndicator(color: Colors.white)
                  : const Text("Get Onboard", style: TextStyle(fontSize: 16)),
            )
          ],
        ),
      ),
    );
  }
}

/// ---------------------- DRIVER ONBOARDING ----------------------
class ShuttleDriverOnboarding extends StatefulWidget {
  const ShuttleDriverOnboarding({Key? key}) : super(key: key);

  @override
  _ShuttleDriverOnboardingState createState() =>
      _ShuttleDriverOnboardingState();
}

class _ShuttleDriverOnboardingState extends State<ShuttleDriverOnboarding> {
  final _formKey = GlobalKey<FormState>();

  final TextEditingController nameCtrl = TextEditingController();
  final TextEditingController phoneCtrl = TextEditingController();
  final TextEditingController emailCtrl = TextEditingController();
  final TextEditingController vehicleModelCtrl = TextEditingController();
  final TextEditingController vehicleNameCtrl = TextEditingController();
  final TextEditingController vehicleCapacityCtrl = TextEditingController();

  Uint8List? driverImageBytes;
  Uint8List? vehicleImageBytes;

  bool loading = false;
  final picker = ImagePicker();

  Future<void> pickImage(bool isDriver) async {
    final picked = await picker.pickImage(source: ImageSource.gallery);
    if (picked == null) return;
    Uint8List bytes = await picked.readAsBytes();

    setState(() {
      if (isDriver) {
        driverImageBytes = bytes;
      } else {
        vehicleImageBytes = bytes;
      }
    });
  }

  Future<String> uploadToFirebase(Uint8List fileBytes, String folder) async {
    final uid = FirebaseAuth.instance.currentUser!.uid;
    final fileName = "$uid-${DateTime.now().millisecondsSinceEpoch}.jpg";
    final ref = FirebaseStorage.instance.ref("$folder/$fileName");
    await ref.putData(fileBytes);
    return await ref.getDownloadURL();
  }

  Future<void> saveDetails() async {
    if (!_formKey.currentState!.validate()) return;

    if (driverImageBytes == null || vehicleImageBytes == null) {
      _showSnack("Please upload both images");
      return;
    }

    setState(() => loading = true);

    try {
      String driverUrl =
          await uploadToFirebase(driverImageBytes!, "driverImages");
      String vehicleUrl =
          await uploadToFirebase(vehicleImageBytes!, "vehicleImages");

      String driverCode = "DB${Random().nextInt(90000) + 10000}";

      await FirebaseFirestore.instance
          .collection("shuttle_drivers")
          .doc(FirebaseAuth.instance.currentUser!.uid)
          .set({
        "name": nameCtrl.text.trim(),
        "phone": phoneCtrl.text.trim(),
        "email": emailCtrl.text.trim(),
        "driverImage": driverUrl,
        "vehicleImage": vehicleUrl,
        "vehicleModel": vehicleModelCtrl.text.trim(),
        "vehicleName": vehicleNameCtrl.text.trim(),
        "vehicleCapacity": int.parse(vehicleCapacityCtrl.text.trim()),

        /// NEW FIELDS
        "status": "offline",
        "activeInstitution": null,
        "pickupLocation": null,
        "destinationLocation": null,

        "driverCode": driverCode,
        "boardedPassengers": 0,
        "ticketIds": [],
        "amountCollected": 0.0,
        "earnings": 0.0,
        "timestamp": FieldValue.serverTimestamp(),
      });

      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const ShuttleDriverDashboard()),
      );
    } catch (e) {
      _showSnack("Error: $e");
    }

    setState(() => loading = false);
  }

  void _showSnack(String msg) {
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(msg)));
  }

  Widget _input(String label, TextEditingController ctrl,
      {TextInputType type = TextInputType.text}) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 15),
      child: TextFormField(
        controller: ctrl,
        keyboardType: type,
        validator: (v) => v!.isEmpty ? "Required" : null,
        decoration:
            InputDecoration(border: OutlineInputBorder(), labelText: label),
      ),
    );
  }

  Widget _imagePicker(String title, Uint8List? bytes, Function() onTap) {
    return InkWell(
      onTap: onTap,
      child: Container(
        height: 70,
        width: 70,
        decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(50),
            border: Border.all(color: Colors.grey)),
        child: bytes == null
            ? Center(child: Text(title))
            : ClipRRect(
                borderRadius: BorderRadius.circular(12),
                child: Image.memory(bytes, fit: BoxFit.cover),
              ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(backgroundColor: Colors.white, elevation: 0),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Form(
          key: _formKey,
          child: ListView(
            children: [
              const Text("Fill your personal and vehicle details.",
                  style: TextStyle(fontWeight: FontWeight.bold)),
              _imagePicker(
                  "Driver Image", driverImageBytes, () => pickImage(true)),
              _input("Full Name", nameCtrl),
              _input("Phone", phoneCtrl),
              _input("Email", emailCtrl),
              const SizedBox(height: 20),
              const Text("Vehicle Info",
                  style: TextStyle(fontWeight: FontWeight.bold)),
              _imagePicker(
                  "Vehicle Image", vehicleImageBytes, () => pickImage(false)),
              _input("Vehicle Model", vehicleModelCtrl),
              _input("Vehicle Name", vehicleNameCtrl),
              _input("Capacity", vehicleCapacityCtrl,
                  type: TextInputType.number),
              const SizedBox(height: 30),
              ElevatedButton(
                onPressed: loading ? null : saveDetails,
                child: loading
                    ? CircularProgressIndicator(color: Colors.white)
                    : Text("Get Onboard"),
              )
            ],
          ),
        ),
      ),
    );
  }
}

/// ---------------------- DRIVER DASHBOARD ----------------------

class ShuttleDriverDashboard extends StatefulWidget {
  const ShuttleDriverDashboard({Key? key}) : super(key: key);

  @override
  _ShuttleDriverDashboardState createState() => _ShuttleDriverDashboardState();
}

class _ShuttleDriverDashboardState extends State<ShuttleDriverDashboard>
    with SingleTickerProviderStateMixin {
  final user = FirebaseAuth.instance.currentUser;

  late AnimationController _shimmerController;

  @override
  void initState() {
    super.initState();

    _shimmerController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1200),
    )..repeat();
  }

  @override
  void dispose() {
    _shimmerController.dispose();
    super.dispose();
  }

  // ============================================================
  // GO ONLINE FLOW
  // ============================================================

  void openRouteSelector() async {
    final snapshot =
        await FirebaseFirestore.instance.collection("institutions").get();

    List<Map<String, dynamic>> institutions =
        snapshot.docs.map((e) => e.data()).toList();

    String? selectedInstitution;
    String? pickup;
    String? destination;

    final TextEditingController priceController = TextEditingController();

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(30),
        ),
      ),
      builder: (_) {
        return StatefulBuilder(
          builder: (context, setModalState) {
            List<String> locations = [];

            if (selectedInstitution != null) {
              final inst = institutions.firstWhere(
                (e) => e['name'] == selectedInstitution,
              );

              locations = List<String>.from(
                inst['locations'],
              );
            }

            return Padding(
              padding: EdgeInsets.fromLTRB(
                20,
                14,
                20,
                MediaQuery.of(context).viewInsets.bottom + 24,
              ),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    // Bottom sheet handle
                    Container(
                      width: 45,
                      height: 5,
                      decoration: BoxDecoration(
                        color: Colors.grey.shade300,
                        borderRadius: BorderRadius.circular(20),
                      ),
                    ),

                    const SizedBox(height: 22),

                    const Align(
                      alignment: Alignment.centerLeft,
                      child: Text(
                        "Select Route",
                        style: TextStyle(
                          fontSize: 22,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),

                    const SizedBox(height: 22),

                    // Institution
                    _routeSelectorField(
                      label: "Institution",
                      value: selectedInstitution,
                      icon: Icons.account_balance_rounded,
                      onTap: () async {
                        final result = await _showWhiteSelector(
                          title: "Select Institution",
                          options: institutions
                              .map((e) => e['name'].toString())
                              .toList(),
                          selectedValue: selectedInstitution,
                        );

                        if (result != null) {
                          setModalState(() {
                            selectedInstitution = result;
                            pickup = null;
                            destination = null;
                          });
                        }
                      },
                    ),

                    const SizedBox(height: 12),

                    // Pickup
                    _routeSelectorField(
                      label: "Pickup",
                      value: pickup,
                      icon: Icons.trip_origin_rounded,
                      enabled: selectedInstitution != null,
                      onTap: () async {
                        if (locations.isEmpty) return;

                        final result = await _showWhiteSelector(
                          title: "Select Pickup",
                          options: locations,
                          selectedValue: pickup,
                        );

                        if (result != null) {
                          setModalState(() {
                            pickup = result;
                          });
                        }
                      },
                    ),

                    const SizedBox(height: 12),

                    // Destination
                    _routeSelectorField(
                      label: "Destination",
                      value: destination,
                      icon: Icons.location_on_rounded,
                      enabled: selectedInstitution != null,
                      onTap: () async {
                        if (locations.isEmpty) return;

                        final result = await _showWhiteSelector(
                          title: "Select Destination",
                          options: locations,
                          selectedValue: destination,
                        );

                        if (result != null) {
                          setModalState(() {
                            destination = result;
                          });
                        }
                      },
                    ),

                    const SizedBox(height: 12),

                    // Price
                    TextField(
                      controller: priceController,
                      keyboardType: TextInputType.number,
                      decoration: InputDecoration(
                        hintText: "Enter Price",
                        prefixIcon: const Icon(
                          Icons.payments_outlined,
                          size: 20,
                        ),
                        filled: true,
                        fillColor: Colors.grey.shade100,
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(17),
                          borderSide: BorderSide.none,
                        ),
                      ),
                    ),

                    const SizedBox(height: 22),

                    SizedBox(
                      width: double.infinity,
                      height: 54,
                      child: ElevatedButton(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.black,
                          foregroundColor: Colors.white,
                          elevation: 0,
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(17),
                          ),
                        ),
                        onPressed: () async {
                          if (selectedInstitution == null ||
                              pickup == null ||
                              destination == null ||
                              priceController.text.isEmpty) {
                            return;
                          }

                          await FirebaseFirestore.instance
                              .collection("shuttle_drivers")
                              .doc(user!.uid)
                              .update({
                            "status": "online",
                            "activeInstitution": selectedInstitution,
                            "pickupLocation": pickup,
                            "destinationLocation": destination,
                            "price": int.parse(priceController.text),
                            "boardedPassengers": 0,
                            "amountCollected": 0,
                            "timestamp": FieldValue.serverTimestamp(),
                          });

                          Navigator.pop(context);
                        },
                        child: const Text(
                          "Go Online",
                          style: TextStyle(
                            fontSize: 16,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  // ============================================================
  // WHITE MODAL SELECTOR
  // ============================================================

  Future<String?> _showWhiteSelector({
    required String title,
    required List<String> options,
    String? selectedValue,
  }) {
    return showModalBottomSheet<String>(
      context: context,
      backgroundColor: Colors.white,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(28),
        ),
      ),
      builder: (context) {
        return SafeArea(
          child: Padding(
            padding: const EdgeInsets.fromLTRB(
              20,
              14,
              20,
              20,
            ),
            child: ConstrainedBox(
              constraints: const BoxConstraints(
                maxHeight: 500,
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Container(
                    width: 45,
                    height: 5,
                    decoration: BoxDecoration(
                      color: Colors.grey.shade300,
                      borderRadius: BorderRadius.circular(20),
                    ),
                  ),
                  const SizedBox(height: 20),
                  Align(
                    alignment: Alignment.centerLeft,
                    child: Text(
                      title,
                      style: const TextStyle(
                        fontSize: 21,
                        fontWeight: FontWeight.bold,
                      ),
                    ),
                  ),
                  const SizedBox(height: 16),
                  Flexible(
                    child: ListView.separated(
                      shrinkWrap: true,
                      itemCount: options.length,
                      separatorBuilder: (_, __) => const SizedBox(height: 8),
                      itemBuilder: (context, index) {
                        final option = options[index];
                        final isSelected = option == selectedValue;

                        return InkWell(
                          borderRadius: BorderRadius.circular(16),
                          onTap: () {
                            Navigator.pop(
                              context,
                              option,
                            );
                          },
                          child: Container(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 16,
                              vertical: 16,
                            ),
                            decoration: BoxDecoration(
                              color: isSelected
                                  ? Colors.grey.shade100
                                  : Colors.white,
                              borderRadius: BorderRadius.circular(16),
                              border: Border.all(
                                color: isSelected
                                    ? Colors.black
                                    : Colors.grey.shade200,
                              ),
                            ),
                            child: Row(
                              children: [
                                Expanded(
                                  child: Text(
                                    option,
                                    style: TextStyle(
                                      fontSize: 15,
                                      fontWeight: isSelected
                                          ? FontWeight.w700
                                          : FontWeight.w500,
                                    ),
                                  ),
                                ),
                                if (isSelected)
                                  const Icon(
                                    Icons.check_circle_rounded,
                                    color: Colors.black,
                                    size: 21,
                                  ),
                              ],
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  // ============================================================
  // ROUTE SELECTOR FIELD
  // ============================================================

  Widget _routeSelectorField({
    required String label,
    required String? value,
    required IconData icon,
    required VoidCallback onTap,
    bool enabled = true,
  }) {
    return InkWell(
      onTap: enabled ? onTap : null,
      borderRadius: BorderRadius.circular(17),
      child: Opacity(
        opacity: enabled ? 1 : .5,
        child: Container(
          padding: const EdgeInsets.symmetric(
            horizontal: 15,
            vertical: 15,
          ),
          decoration: BoxDecoration(
            color: Colors.grey.shade100,
            borderRadius: BorderRadius.circular(17),
          ),
          child: Row(
            children: [
              Icon(
                icon,
                size: 21,
                color: Colors.black87,
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      label,
                      style: TextStyle(
                        color: Colors.grey.shade600,
                        fontSize: 12,
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      value ?? "Select $label",
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: TextStyle(
                        fontSize: 15,
                        fontWeight:
                            value != null ? FontWeight.w600 : FontWeight.w400,
                        color:
                            value != null ? Colors.black : Colors.grey.shade500,
                      ),
                    ),
                  ],
                ),
              ),
              const Icon(
                Icons.keyboard_arrow_down_rounded,
                color: Colors.black54,
              ),
            ],
          ),
        ),
      ),
    );
  }

  // ============================================================
  // GO OFFLINE
  // ============================================================

  void goOffline() async {
    await FirebaseFirestore.instance
        .collection("shuttle_drivers")
        .doc(user!.uid)
        .update({
      "status": "offline",
      "activeInstitution": null,
      "pickupLocation": null,
      "destinationLocation": null,
    });
  }

  // ============================================================
  // DEPART TRIP
  // ============================================================

  Future<void> departTrip(Map<String, dynamic> data) async {
    final driverRef =
        FirebaseFirestore.instance.collection("shuttle_drivers").doc(user!.uid);

    await FirebaseFirestore.instance.collection("shuttle_departures").add({
      "driverId": user!.uid,
      "name": data['name'],
      "vehicleName": data['vehicleName'],
      "institution": data['activeInstitution'],
      "pickup": data['pickupLocation'],
      "destination": data['destinationLocation'],
      "price": data['price'],
      "passengers": data['boardedPassengers'],
      "capacity": data['vehicleCapacity'],
      "amount": data['amountCollected'],
      "departedAt": FieldValue.serverTimestamp(),
    });

    await driverRef.update({
      "status": "offline",
      "activeInstitution": null,
      "pickupLocation": null,
      "destinationLocation": null,
      "boardedPassengers": 0,
      "amountCollected": 0,
    });
  }

  // ============================================================
  // DEPART CONFIRMATION SNACKBAR
  // ============================================================

  void _confirmDepart(Map<String, dynamic> data) {
    final int passengers = data['boardedPassengers'] ?? 0;

    final dynamic amount = data['amountCollected'] ?? 0;

    ScaffoldMessenger.of(context).hideCurrentSnackBar();

    final snackBar = SnackBar(
      backgroundColor: Colors.black,
      behavior: SnackBarBehavior.floating,
      duration: const Duration(seconds: 8),
      margin: const EdgeInsets.fromLTRB(
        16,
        0,
        16,
        18,
      ),
      padding: EdgeInsets.zero,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(20),
      ),
      content: Container(
        padding: const EdgeInsets.fromLTRB(
          18,
          17,
          10,
          17,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            const Text(
              "Ready to depart?",
              style: TextStyle(
                color: Colors.white,
                fontSize: 16,
                fontWeight: FontWeight.bold,
              ),
            ),
            const SizedBox(height: 6),
            Text(
              "$passengers passengers boarded  •  ₦$amount collected",
              style: const TextStyle(
                color: Colors.white70,
