      child: ClipOval(
        child: imageUrl != null && imageUrl.toString().isNotEmpty
            ? Image.network(
                imageUrl,
                fit: BoxFit.cover,
                errorBuilder: (_, __, ___) {
                  return const Icon(
                    Icons.directions_bus_rounded,
                    size: 38,
                    color: Colors.grey,
