class HeaderWaveClipper extends CustomClipper<Path> {
  @override
  Path getClip(Size size) {
    final path = Path();

    path.lineTo(0, size.height - 25);

    // 🌊 First ripple
    path.quadraticBezierTo(
      size.width * 0.15,
      size.height + 15,
      size.width * 0.33,
      size.height - 20,
    );

    // 🌊 Second ripple
    path.quadraticBezierTo(
      size.width * 0.50,
      size.height - 55,
      size.width * 0.66,
      size.height - 20,
    );

    // 🌊 Third ripple
    path.quadraticBezierTo(
      size.width * 0.83,
      size.height + 15,
      size.width,
      size.height - 25,
    );

    path.lineTo(size.width, 0);
    path.close();

    return path;
  }

  @override
  bool shouldReclip(CustomClipper<Path> oldClipper) => false;
}

class HeaderDoodlePainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.amber.withOpacity(0.18)
      ..strokeWidth = 1.2
      ..style = PaintingStyle.stroke;

    final path = Path();

    // Left doodle
    path.moveTo(15, 35);
    path.quadraticBezierTo(40, 10, 65, 35);
    path.quadraticBezierTo(90, 60, 115, 35);

    // Top right
    path.moveTo(size.width - 120, 25);
    path.quadraticBezierTo(size.width - 80, 5, size.width - 45, 30);
    path.quadraticBezierTo(size.width - 15, 55, size.width - 5, 25);

    // Bottom left
    path.moveTo(25, size.height - 45);
    path.quadraticBezierTo(55, size.height - 70, 90, size.height - 45);

    // Bottom right
    path.moveTo(size.width - 100, size.height - 55);
    path.quadraticBezierTo(
        size.width - 60, size.height - 85, size.width - 20, size.height - 55);

    canvas.drawPath(path, paint);

    // Small decorative circles
    canvas.drawCircle(
      const Offset(55, 90),
      3,
      paint,
    );

    canvas.drawCircle(
      Offset(size.width - 70, 120),
      4,
      paint,
    );

    canvas.drawCircle(
      Offset(size.width * .5, 45),
      2,
      paint,
    );
  }

  @override
  bool shouldRepaint(CustomPainter oldDelegate) => false;
}

class Profile extends StatefulWidget {
  const Profile({Key? key}) : super(key: key);

  @override
  State<Profile> createState() => _ProfileState();
}

class _ProfileState extends State<Profile> {
  String name = "";
  String email = "";
  String phone = "";
  bool loading = true;

  @override
  void initState() {
    super.initState();
    _loadUser();
  }

  Future<void> _loadUser() async {
    final user = FirebaseAuth.instance.currentUser;

    if (user == null) return;

    setState(() {
      name = user.displayName ?? "User";
      email = user.email ?? "";
      phone = user.phoneNumber ?? "No phone"; // may be null
      loading = false;
    });
  }

  void openMenu(BuildContext context) {
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (context) => FractionallySizedBox(
        heightFactor: 0.6,
        child: Padding(
          padding: const EdgeInsets.all(20.0),
          child: Column(
            children: [
              const SizedBox(height: 10),
              Container(
                width: 40,
                height: 4,
                decoration: BoxDecoration(
                  color: Colors.grey[800],
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
              const SizedBox(height: 20),
              _menuItem(
                icon: 'assets/images/service.png',
                title: 'Become a Driver',
                onTap: () {
                  Navigator.pop(context);
                  Navigator.push(
                    context,
                    MaterialPageRoute(builder: (context) => EarnPage()),
                  );
                },
              ),
              _menuItem(
                icon: 'assets/images/customer-service.png',
                title: 'Orders',
                onTap: () {
                  Navigator.pop(context);
                  Navigator.push(
                    context,
                    MaterialPageRoute(
                        builder: (context) => const UserOrdersListPage()),
                  );
                },
              ),
              _menuItem(
                icon: 'assets/images/help.png',
                title: 'Dispatch Riders',
                onTap: () async {
                  final currentUserId = FirebaseAuth.instance.currentUser!.uid;

                  final vendorDoc = await FirebaseFirestore.instance
                      .collection('dispatch_riders')
                      .doc(currentUserId)
                      .get();

                  if (vendorDoc.exists) {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                        builder: (context) => const DispatchDashboardPage(),
                      ),
                    );
                  } else {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                          builder: (context) => const DispatchOnboarding()),
                    );
                  }
                },
              ),
              _menuItem(
                icon: 'assets/images/help.png',
                title: 'Vendors',
                onTap: () async {
                  final currentUserId = FirebaseAuth.instance.currentUser!.uid;

                  final vendorDoc = await FirebaseFirestore.instance
                      .collection('Vendors')
                      .doc(currentUserId)
                      .get();

                  if (vendorDoc.exists) {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                          builder: (context) =>
                              VendorDashboardPage(vendorId: currentUserId)),
                    );
                  } else {
                    Navigator.push(
                      context,
                      MaterialPageRoute(
                          builder: (context) => const VendorOnboardingPage()),
                    );
                  }
                },
              ),
              _menuItem(
                icon: 'assets/images/help.png',
                title: 'Shuttle Drivers',
                onTap: () async {
                  final currentUserId = FirebaseAuth.instance.currentUser?.uid;
                  if (currentUserId == null) return;

                  try {
                    final driverDoc = await FirebaseFirestore.instance
                        .collection('shuttle_drivers')
                        .doc(currentUserId)
                        .get();

                    if (driverDoc.exists) {
                      Navigator.pushReplacement(
                        context,
                        MaterialPageRoute(
                            builder: (_) => ShuttleDriverDashboard()),
                      );
                    } else {
                      Navigator.pushReplacement(
                        context,
                        MaterialPageRoute(
                            builder: (_) => ShuttleDriverOnboarding()),
                      );
                    }
                  } catch (e) {
                    print("Error checking shuttle driver doc: $e");
                    ScaffoldMessenger.of(context)
                        .showSnackBar(SnackBar(content: Text("Error: $e")));
                  }
                },
              ),
              _menuItem(
                icon: 'assets/images/help.png',
                title: 'Providers',
                onTap: () async {
                  final currentUserId = FirebaseAuth.instance.currentUser?.uid;
                  if (currentUserId == null) return;

                  try {
                    final driverDoc = await FirebaseFirestore.instance
                        .collection('providers')
                        .doc(currentUserId)
                        .get();

                    if (driverDoc.exists) {
                      Navigator.pushReplacement(
                        context,
                        MaterialPageRoute(builder: (_) => ProviderHomePage()),
                      );
                    } else {
                      Navigator.pushReplacement(
                        context,
                        MaterialPageRoute(
                            builder: (_) => ProviderOnboardingPage()),
                      );
                    }
                  } catch (e) {
                    print("Error checking provider doc: $e");
                    ScaffoldMessenger.of(context)
                        .showSnackBar(SnackBar(content: Text("Error: $e")));
                  }
                },
              ),
            ],
          ),
        ),
      ),
    );
  }

